-- GENERATED by `wfj generate` from data/quest/quest-0005.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [5001] = { "⟦Bijou's Belongings=Beni di Bijou⟧", "Trova i ⟦Bijou's Belongings=Beni di Bijou⟧ e restituiscili alla proprietaria. Buona fortuna!", "Di solito non tratto con <un/una> {race}, ma a quanto pare sono tra l'incudine e il troll. Vedi, la mia missione qui è della massima importanza per l'⟦Horde=Orda⟧. Le informazioni che ho scoperto, però, riguardano anche il bene dell'⟦Alliance=Alleanza⟧. Credimi, non sono una simpatizzante dell'⟦Alliance=Alleanza⟧, ma la minaccia dei ⟦Blackrock=Roccianera⟧ è più grande di un semplice branco di orchi.\n\nTu mi aiuti a ritrovare la mia roba e io ti aiuto con qualche informazione che potrebbe tornare utile alla tua gente.\n\nAffare fatto?", "Fortuna?", "Ma guarda un po'! Dov'erano??", 0xb62123b7, 0xb905391b, 0x6060e58e, 0x87e6d3ba, 0xb600db21, "....." },
  [5002] = { "Messaggio per Maxwell", "Va' nelle ⟦Burning Steppes=Steppe Ardenti⟧ e consegna l'⟦Bijou's Information=Informazione di Bijou⟧ al maresciallo Maxwell.", "Sono una goblin di parola, {race}. Ora ascolta bene:\n\nQuesti orchi servono soprattutto come bestie da soma e carne da cannone per lo Stormo dei Draghi Neri!\n\nIl loro vero capo è nientemeno che Nefarian, progenie di Alamorte. Ho anche scoperto dove si trovano i sottoposti di Nefarian in questa parte della cittadella.\n\nPorta questa mappa al maresciallo Maxwell, nelle ⟦Burning Steppes=Steppe Ardenti⟧. Ci sono segnati i luoghi in cui si trovano questi demoni, così sarà facile individuarli.", "Ah, {name}. È passato molto tempo.", "Questo coincide con gran parte di quello che sapevamo già. In ogni caso, sono informazioni interessanti e piuttosto spiacevoli.\n\nI segni su questa mappa si riveleranno preziosi per sfoltire la minaccia dei ⟦Blackrock=Roccianera⟧.", 0xd738e388, 0x9f2ff06a, 0x01a3d183, 0x8dba76de, 0x762d90e6, "....." },
  [5021] = { "Meglio tardi che mai", "I vaneggiamenti della donna spettrale indicavano che le serviva far consegnare un pacco. Diceva che si trovava dov'era il suo cavallo. Su dove sia il cavallo o dove andasse consegnato il pacco, il fantasma resta incomprensibile.", "«Il pacco deve essere consegnato... consegnato prima che io resti intrappolata qui!»\n\nLe grida di una donna in preda al panico sembrano quasi un sussurro che fluttua per la casa. Rannicchiata nell'angolo al piano di sopra c'è l'apparizione di una donna. Non sembra del tutto consapevole di ciò che la circonda, e si accorge di te solo vagamente.\n\n«Sei qui per consegnare il mio pacco? Ti prego, prima che le cose peggiorino! Stavo per andarmene a cavallo. Dovrebbe essere ancora vicino al mio cavallo... o è troppo tardi?»", nil, "Un pacco nel fienile, che altrimenti ti sarebbe sfuggito, ora spicca tra il degrado e le rovine. Forse è quello di cui parlava con tanta insistenza il fantasma di Janice Felstone...", 0x1d1c5dd8, 0x70391ade, 0x3a27de2c, nil, 0x45c650cb, "...m." },
  [5022] = { "Meglio tardi che mai", "Rivolgiti agli Agenti Reali di ⟦Stormwind=Roccavento⟧ per scoprire dove si trovi una certa Emma Felstone. Di solito c'è un funzionario del censimento nel municipio.", "Raccogli il pacco e togli il sottile strato di polvere e sporcizia che vi si era depositato. È indirizzato, con una grafia frettolosa, a una certa Emma Felstone di ⟦Stormwind City=Roccavento⟧; la consegna del pacco risale a ben più di quattro anni fa.\n\nAnche se non è chiaro se Emma Felstone sia ancora viva, è risaputo che il municipio di ⟦Stormwind City=Roccavento⟧ tiene registri sulla popolazione della città. Se ne occupano gli Agenti Reali del Censimento di ⟦Stormwind City=Roccavento⟧.", "Benvenut<o/a> nell'ufficio del censimento di ⟦Stormwind=Roccavento⟧. Se ti servono informazioni sulla nostra popolazione, posso aiutarti.", "Un pacco per una certa Emma Felstone, dici? Ultimo indirizzo conosciuto ⟦Stormwind=Roccavento⟧, quattro anni fa? Be', vediamo un po'...\n\nStando a quanto sappiamo, circa quattro anni fa in città c'era una certa Emma Felstone. Anzi, dovrei dire forse: il censimento a cui faccio riferimento è di cinque anni fa, e non risulta che abbia lasciato la città. Questo però non significa che sia ancora qui.\n\nUn momento... questo pacco non sarà mica per Ol' Emma, vero?", 0x1d1c5dd8, 0xdcdc7598, 0xf0839606, 0x5991a2dc, 0x06b012f4, "....." },
  [5023] = { "Meglio tardi che mai", "Rivolgiti ai Sovrintendenti Reali di ⟦Undercity=Sepulcra⟧ per scoprire dove si trovi un certo Jeremiah Felstone. Di solito c'è un funzionario del censimento vicino all'ufficio di registrazione di gilde e insegne.", "Raccogli il pacco e togli il sottile strato di polvere e sporcizia che vi si era depositato. È indirizzato, con una grafia frettolosa, a un certo Jeremiah Felstone di Lordaeron; la consegna del pacco risale a ben più di quattro anni fa.\n\nAnche se non è chiaro se Jeremiah Felstone sia ancora vivo, è risaputo che ⟦Undercity=Sepulcra⟧, un tempo nota come Lordaeron, tiene registri sulla popolazione della città. Se ne occupano i Sovrintendenti Reali del Censimento di ⟦Undercity=Sepulcra⟧.", "Sei qui per chiedere assistenza al censimento di ⟦Undercity=Sepulcra⟧, o solo per chiedermi se qualcuno che conoscevi è morto? Me lo chiedono spesso.", "Un pacco per un certo Jeremiah Felstone, con ultimo indirizzo conosciuto a Lordaeron... Dovrei poterti aiutare.\n\nJeremiah Felstone era in città prima della pestilenza. Anzi, dovrei dire l'ex Jeremiah Felstone: alcuni Reietti hanno cambiato cognome per liberarsi del loro aspetto di un tempo. Questo caso non fa eccezione: l'ex Jeremiah Felstone ora è conosciuto come Jeremiah Payson.\n\nAspetta un attimo... non è il venditore di scarafaggi?", 0x1d1c5dd8, 0x19871f59, 0x2f752d9b, 0x8ef887b9, 0x0cd06198, "....." },
  [5041] = { "Provviste per il ⟦Crossroads=Crocevia⟧", "Trova le casse di rifornimenti del ⟦Crossroads=Crocevia⟧ e riportale a Thork, nelle ⟦Barrens=Savane⟧.", "Con quell'attacco alla carovana abbiamo perso provviste di cui avevamo un disperato bisogno.\n\nFinora hai avuto il coraggio di affrontare la tribù dei ⟦Razormane=Chiomaguzza⟧, e ti chiederò di farlo ancora, ma stavolta vorrei anche che tenessi gli occhi aperti per ritrovare parte delle nostre provviste perdute. Probabilmente le troverai sparse nei loro accampamenti, dove i verrospini ingrassano grazie alle loro azioni disonorevoli.\n\nLa gente del ⟦Crossroads=Crocevia⟧ sarebbe in debito con te.", "Come procede la ricerca delle provviste, {name}? Confido che i verrospini cadano facilmente sotto la tua forza.", "Ah ah! Grazie, {name}! Questo ci aiuterà moltissimo. Sei una benedizione per il ⟦Crossroads=Crocevia⟧ e per l'⟦Horde=Orda⟧. Se posso fare qualcosa per te, ti prego, fammelo sapere.", 0x4b2a9bbe, 0x69fcf120, 0x11724923, 0x89163eaf, 0xd476a085, "....." },
  [5042] = { "⟦Agamaggan's Strength=Forza di Agamaggan⟧", nil, nil, "Mi servono 4 frammenti di sangue se vuoi la forza di Agamaggan, {race}.\n\nCon questa benedizione i tuoi nemici si farebbero piccoli davanti alla tua forza. <sbuffa>\n\nI più grandi guerrieri dei Chiomaguzza sono pervasi di questo potere!", "Se solo Mangletooth fosse libero di vederti fare strage di quelli che l'hanno tradito! <sbuffa>\n\nTi ringrazio per aver eliminato altri ⟦Bristleback=Mantotergo⟧ raccogliendo questi frammenti. Ti prego, continua così e io continuerò ad aiutarti. <sbuffa>", 0x0b63dce6, nil, nil, 0x7cbc8fc6, 0x4c396d41, ".mm.." },
  [5043] = { "⟦Agamaggan's Agility=Agilità di Agamaggan⟧", nil, nil, "Si dice che i migliori esploratori della mia tribù abbiano una precisione senza rivali, e che nessun ladro <sbuffa> possa eguagliare la loro rapidità in battaglia.\n\nPortami 4 frammenti di sangue e ti renderò più agile di qualunque verrospino nato.", "Che la tua mira sia infallibile e i colpi della tua arma vadano a segno, {race}.\n\nLo spirito di Agamaggan è con te. Torna <sbuffa> da me, se vuoi. Mangletooth ti benedirà ancora, se il grande dio cinghiale lo riterrà degno. <sbuffa>", 0xbfb78098, nil, nil, 0xbf6c88ce, 0x3cf06179, ".mm.." },
  [5044] = { "⟦Wisdom of Agamaggan=Saggezza di Agamaggan⟧", nil, nil, "Gli sciamani e i geomanti delle tribù dei verrospini <sbuffa> invocano la forza di Agamaggan per aiutarli in battaglia e nei loro rituali, {race}.\n\nSe anche tu desideri il potere aggiuntivo della benedizione di Agamaggan per i tuoi incantesimi, portami 4 frammenti di sangue e Mangletooth ti aiuterà. <sbuffa>", "Ora i tuoi nemici dovrebbero temerti ancora di più, {race}. <sbuffa>\n\nRacconta a Mangletooth della tua astuzia in battaglia quando ci rivedremo, che sia in questa vita o nella prossima. <sbuffa>", 0x2493ca20, nil, nil, 0x07bb03e2, 0x30cb7a53, ".mm.." },
  [5045] = { "⟦Rising Spirit=Spirito Ascendente⟧", nil, nil, "Guerrieri di ogni tipo <sbuffa> hanno bisogno di uno spirito forte. Spinge a imprese più grandi quando ogni speranza è perduta. I <sbuffa> ⟦Razormane=Chiomaguzza⟧ lo sanno bene. Siamo una tribù spirituale: andiamo più fieri del nostro legame con Agamaggan che della nostra abilità <sbuffa> in battaglia.\n\nPortami 4 frammenti di sangue e benedirò il tuo spirito per la battaglia. <sbuffa>", "I nostri più grandi guerrieri e i nostri più grandi <sbuffa> sciamani invidierebbero la tua volontà, {race}.\n\nSconfiggi altri Mantotergo, sapendo che non possono fermarti! <sbuffa>", 0x67558646, nil, nil, 0xb9f5d16c, 0xc40eb9eb, ".mm.." },
  [5046] = { nil, nil, nil, "Tutti quelli che <sbuffa> vanno in battaglia hanno bisogno di protezione. Le ossa devono essere forti. La pelle dura. <sbuffa> Anche la mia tribù lo sa e, per aggiungere qualcosa alla protezione naturale che ci danno aculei e cuoio, <sbuffa> spesso invochiamo Agamaggan perché ci protegga prima di andare in guerra.\n\nPortami 4 frammenti di sangue <sbuffa> e ti concederò la stessa protezione.", "Va' in guerra, {race}.", 0x41b394c0, nil, nil, 0x24679bfc, 0xd6cd4420, "emm.." },
  [5047] = { "Pip Quickwit, al tuo servizio!", "Parla con Malyfous Darkhammer a ⟦Everlook=Lungavista⟧.", "Troverai Malyfous Darkhammer a ⟦Everlook=Lungavista⟧, {class}. Digli che 'Pip sta benone' e che la tuta funziona alla perfezione.\n\nPoi dagli questo:\n\n<Pip ti porge un pezzo di carne luminescente.>\n\nL'ho strappato dalle viscere della bestia durante la mia 'vacanza'.\n\nScommetto che Malyfous saprà dirti con buona precisione cosa può fare con i pezzi di un mostro come questo!\n\nOh, immagino che tu non sappia dove si trova ⟦Everlook=Lungavista⟧, vero? A ⟦Winterspring=Fontefredda⟧, <amico/amica>!", "Sì?", "Vivo? La tuta ha funzionato? E cosa abbiamo qui?", 0x7e03d8eb, 0x2f591ac4, 0x6063c392, 0x0c079f52, 0x909b86e3, ".....", nil, nil, 0xe0b81e59, nil, nil },
  [5048] = { "La buona Emma", "Trova Ol' Emma a ⟦Stormwind=Roccavento⟧ e scopri se è davvero Emma Felstone. Se lo è, forse le farebbe piacere il pacco che Janice Felstone ha preparato per lei.", "È un tantino scorbutica, e molto probabilmente fuori di zucca... ma i registri indicano che Ol' Emma corrisponde al profilo di quella che potrebbe essere Emma Felstone.\n\nForse hai visto Ol' Emma girovagare per la città: parla da sola, il più delle volte farfugliando cose senza senso. Comunque non fa del male a niente e a nessuno, perciò la gente in genere la lascia stare.\n\nTutto considerato, direi che Ol' Emma è davvero Emma Felstone. Potresti provare a chiederle se il suo cognome è proprio Felstone.", "Ti direi di levarti dal mio prato, ma come vedi non ne ho uno.", "Il mio nome è davvero Emma Felstone: sei la prima persona da anni a chiamarmi così. Chi... chi sei?\n\nDici di aver conosciuto... mia sorella?! È ancora viva? Ma chi voglio prendere in giro, certo che no. Quando la pestilenza è scoppiata a Lordaeron, mi aspettavo ormai il peggio. Tanti della mia famiglia sono morti... o peggio. Ed eccomi qui, la pazza Ol' Emma, tutta sola. Cosa sei, <un/una> profanat<ore/rice> di tombe o roba simile? In cerca del tuo prossimo bersaglio?\n\nCosa... hai un pacco per me da parte di mia sorella?", 0x54e3cb36, 0xcab0ca91, 0x6b6f28a3, 0x8b85f199, 0x6b8bbfec, "....." },
  [5049] = { "Il blues di Jeremiah", "Trova Jeremiah Payson a ⟦Undercity=Sepulcra⟧ e scopri se è davvero Jeremiah Felstone. Se lo è, forse gli farebbe piacere il pacco che Janice Felstone ha preparato per lui.", "Dalle prove che ho potuto raccogliere, la persona che cerchi, nonché il destinatario previsto del pacco, è Jeremiah Payson, il venditore di scarafaggi di ⟦Undercity=Sepulcra⟧.\n\nHo sempre pensato che ci voglia un dono speciale per vendere... scarafaggi. Senza dubbio sei nel bel mezzo di un'epica peregrinazione, possente {class}. Ti lascerò alle tue imprese che cambiano il mondo. Permettimi, però, di avere una parte nella tua magnum opus rivelandoti che si trova vicino alla banca, a strisciare come si conviene sotto una delle passerelle.", "Ogni volta che qualcuno schiaccia uno scarafaggio, io piango. Ti prego, non farmi piangere.", "Non uso quel nome da anni... ma sì, in un certo periodo della mia vita, prima di questa gloriosa non vita, quello era il mio cognome.\n\nSostieni di aver conosciuto mia sorella... o meglio, di averle parlato di recente.\n\nA lei, che è morta.\n\nDa quattro anni.\n\nSai, se le mie ossa non fossero già abbastanza fragili, sarei tentato di rompermi un piede sul tuo didietro. Sei proprio un avvoltoio, eh?\n\nCosa... hai un pacco per me da parte di mia sorella?", 0xbe8b1cef, 0x0e42b052, 0x05312067, 0xf8f8bac4, 0x3755ef66, "....." },
  [5050] = { "⟦Good Luck Charm=Talismano Portafortuna⟧", "Restituisci a Janice Felstone, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧, il suo ⟦Good Luck Half-Charm=Mezzo Talismano Portafortuna⟧.", "A quanto pare mi sbagliavo su di te, {name}, e per questo ti devo delle scuse. Mia sorella mi ha mandato un certo numero di effetti personali, tra cui, ironia della sorte, l'atto di proprietà della fattoria Felstone. Credo che per ora rinuncerò a reclamarla.\n\nSe lo spirito di mia sorella resta legato alla fattoria e non riesce a trovare pace, ti prego... potresti restituirle questo? È metà di un talismano portafortuna che aveva; l'altra metà ce l'aveva suo marito.\n\nForse sapere che ho queste cose darà finalmente pace alla sua anima.", "John, tesoro... sei tu? Ho così freddo all'improvviso...", "Restituisci il mezzo talismano all'apparizione. Lei lo guarda, poi guarda te con aria speranzosa.\n\n«Tesoro, dove hai messo la tua metà del talismano? Non possiamo stare insieme se non abbiamo entrambe le metà. Tesoro... mi vedi?»", 0x5a377e71, 0x9e16a7c6, 0x9652e8b3, 0xf293a279, 0xdb61f9a5, "....." },
  [5051] = { "Due metà diventano una", "Trova l'altra metà del ⟦Good Luck Charm=Talismano Portafortuna⟧ da qualche parte nella fattoria dei Felstone, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧, e riassemblalo.\n\nConsegna il ⟦Good Luck Charm=Talismano Portafortuna⟧ a Janice Felstone nella fattoria dei Felstone, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧.", "I vaneggiamenti del povero fantasma continuano:\n\n«Ho tanto freddo, John. Portami il tuo talismano e staremo insieme! Presto, John, prima che arrivi la pestilenza a trasformarci in bestie orrende! Non riesco a vederti, John... ma so che sei vicino. Ti sento vicino a me.»\n\nForse, se si trovasse e si riassemblasse la seconda metà del talismano, sarebbe proprio ciò che cerca lo spirito di Janice Felstone.", "John, non lasciare che i ghoul ti prendano... non lasciare che i ghoul prendano me... brutti ghoul... il nostro talismano ci terrà al sicuro.", "Consegni il talismano portafortuna riassemblato al fantasma di Janice Felstone. Non appena lo stringe, noti in lei un cambiamento quasi immediato. La sua forma eterea scintilla e ti guarda con occhi limpidi ma tristi.\n\n«Mi hai liberata... Non avrò più bisogno di questo talismano. Ti prego, prendilo: forse darà a te il conforto che ha dato a me.»", 0xa34e95f1, 0xc71af3bd, 0xf0bffb94, 0xdb1e717d, 0xa724f59a, "....." },
  [5052] = { "Frammenti di Sangue di Agamaggan", "Porta un ⟦Blood Shard=Frammento di Sangue⟧ a Mangletooth al Camp Taurajo, nelle ⟦Barrens=Savane⟧.\n\nRaccogli altri Frammenti di Sangue se vuoi che ti benedica con il potere di Agamaggan.", "Insieme alle spine, il sangue ha toccato <sbuffa> altri aspetti della terra: pietre rosso sangue mescolate ad altri minerali. I ⟦Bristleback=Mantotergo⟧ scavano questi frammenti e li portano come totem <sbuffa> per avere forza in battaglia e come totem per la loro magia. <sbuffa>\n\nIo conosco i segreti di quella magia.\n\nPorta a Mangletooth uno di questi frammenti di sangue per dimostrare che hai capito. Porta a Mangletooth molti frammenti, e lui ti benedirà con la magia dei verrospini... la magia di Agamaggan! <sbuffa>", "Le nostre tribù accorrono nelle zone spinose di tutte le ⟦Barrens=Savane⟧ <sbuffa> perché sono luoghi sacri, ma nessuno è sacro quanto Lamaspina. Il corpo di Agamaggan forma l'intera Lamaspina, <sbuffa> ma i Sotterranei sono protetti in modo speciale, perché l'ingresso è fatto dalla sua grande fauce! <sbuffa> Inghiotte interi quelli che non gli sono fedeli, e ne sputa i corpi dopo averli masticati! <sbuffa>\n\nAgamaggan ha lasciato qui il suo corpo per proteggerci, e ci dona il suo spirito perché noi possiamo proteggere lui. <sbuffa>", "Ah, hai capito davvero. <sbuffa> Le mie parole non sono andate perse alle tue orecchie, {race}. Mangletooth sarà anche in gabbia, ma nessuna gabbia può fermare il potere di Agamaggan! <sbuffa>\n\nIl tocco del frammento, la sensazione che dà... è passato tanto tempo, {race}.\n\nSai cosa si prova? A vedersi strappare il proprio potere?\n\nMa questa è una storia per un'altra volta. Ti ho promesso informazioni. Ti ho promesso il potere di Agamaggan. Il mio popolo ha voltato le spalle a Mangletooth. Ora io scateno te contro di loro. <sbuffa>", 0xb007b4a5, 0x0721e680, 0xcdb0e5ac, 0xb95880b0, 0x95e10b3f, "....." },
  [5054] = { "Ursius dei Denterotto", "Storm Shadowhoof, a ⟦Everlook=Lungavista⟧, a ⟦Winterspring=Fontefredda⟧, vuole che tu uccida Ursius.", "Tra le montagne innevate di ⟦Winterspring=Fontefredda⟧, a nord-ovest, un abile cacciatore bracca la sua preda... Parlo di Ursius degli orsi Denterotto, una bestia agile e astuta.\n\nOra ti mando contro di lui. Si aggira per le colline digradanti a nord-ovest di ⟦Everlook=Lungavista⟧. Trovalo e dagli la caccia, prima che scopra le tue intenzioni.\n\nTutti quelli che hanno affrontato Ursius si sono presto ritrovati a essere la preda, e lui il cacciatore. Stai in guardia.", "Ora va', {class}. Trova Ursius.", "Non era un compito facile, eppure hai eccelso. Ma non credere troppo in fretta di avermi impressionato, {name}.", 0x2d87691c, 0x584134b3, 0x37176232, 0xed33f70d, 0x995c5073, "....." },
  [5055] = { "Brumeran di Ventofreddo", "Storm Shadowhoof, a ⟦Everlook=Lungavista⟧, a ⟦Winterspring=Fontefredda⟧, vuole che tu uccida Brumeran.", "Rapida e astuta, Brumeran plana silenziosa sui paesaggi innevati della parte meridionale di ⟦Winterspring=Fontefredda⟧. Ma non lasciare che il suo aspetto aggraziato ti convinca che sia innocua. Tutti quelli che la incrociano pagano un prezzo alto, e spesso con la vita.\n\nCerca Brumeran tra le chimere Ventofreddo. Sconfiggila, poi torna da me.", "Brumeran ti chiama, {name}.", "Sì. Sei tornat<o/a>. Ora credo che tu sia per natura <un/una> ver<o/a> <cacciatore/cacciatrice>. Hai affrontato la più feroce delle creature e sei tornat<o/a>, superando le mie aspettative.\n\nOra sei pront<o/a> per la mia ultima richiesta.", 0x5897dde2, 0x1afc51dd, 0x5a42a2b5, 0xbd73e20c, 0x9c722726, "....." },
  [5056] = { nil, "Storm Shadowhoof, a ⟦Everlook=Lungavista⟧, a ⟦Winterspring=Fontefredda⟧, vuole che tu sconfigga Shy-Rotam.", "Nel nord di ⟦Winterspring=Fontefredda⟧, i grandi felini si radunano attorno a un grosso punto di riferimento chiamato ⟦Frostsaber Rock=Roccia delle Fiere Glaciali⟧. Il capo di questi felini è conosciuto con il nome di Shy-Rotam. Sconfiggere la matriarca delle fiere glaciali ti farebbe guadagnare molto rispetto agli occhi di ogni altro {race}.\n\nTorna nelle terre selvagge e ostili e, una volta lì, raccogli la carne consacrata delle fiere glaciali. Trova la pietra di Shy-Rotam e deponila lì. La carne dei suoi simili posta davanti a lei evocherà Shy-Rotam, furente.\n\nPreparati alla sua furia e sconfiggila.", "Shy-Rotam è audace e implacabile: difenderà i suoi simili con ardore feroce.", "Hai dimostrato sia la tua forza sia la tua determinazione. Molte altre sfide ti attendono, ma ti ho già mostrato tutto ciò che potevo.", 0xe75213da, 0x782e1d52, 0x88f9b80b, 0x832ddc24, 0x6e86fee9, "e...." },
  [5057] = { "Imprese passate", "Porta lo Storm Shadowhoof's Marker a Melor Stonehoof, al ⟦Thunder Bluff=Picco del Tuono⟧.", "Prima ancora che tu mi parlassi, {name}, avevo sentito delle tue imprese... del tuo desiderio incrollabile di dimostrare il tuo valore, delle tue eccezionali capacità come {class}, e ora so che queste cose sono vere.\n\nChi eccelle come te merita un riconoscimento. Porta questo contrassegno a un mio amico a ⟦Thunder Bluff=Picco del Tuono⟧, Melor Stonehoof. Sono certo che si ricorderà di te e di ciò che hai compiuto tanto tempo fa. Parlagli delle tue recenti vittorie e non dimenticare mai ciò che hai compiuto oggi.", nil, "Impariamo dalle esperienze della vita, {name}. Sono certo che le tue ti abbiano solo reso più forte e più saggi<o/a>. Sei cresciut<o/a> molto da quando ci siamo parlati la prima volta.\n\nPrendi questo in ricordo delle difficili imprese che hai compiuto come {class} {race}, e sappi che avrai sempre il mio rispetto e la mia ammirazione.", 0x223a5993, 0xbde5b62f, 0xfff4bf10, nil, 0xcac05ca4, "...m." },
  [5058] = { "Il diario della signora Dalson", nil, nil, nil, "Un diario dalle pagine ingiallite è aperto sull'ultima annotazione:\n\n\"Non so cosa succederà ora che Harold si è trasformato. Mi ci sono volute tutte le forze per trascinarlo nell'unico posto che ho trovato dove chiuderlo a chiave e tenerlo dentro. Ho nascosto la chiave addosso a me, e prego che funzioni...\n\nSpero di riuscire ad andarmene da qui, ma per farlo mi servono soldi. Credo che la nostra roba sia tutta nel mobiletto... e ora che ci penso, la chiave non ce l'ha addosso Harold?\n\nCi dormirò sopra, ora sono stanca morta.\"", 0x79b50b15, nil, nil, nil, 0x04f8236d, ".mmm." },
  [5060] = { "Sotto chiave", nil, nil, "Davanti a te c'è un mobiletto estremamente robusto, chiuso saldamente da una serratura incorporata. Il frontale del mobiletto è profondamente graffiato e segnato. Si direbbe il risultato di numerosi e violenti tentativi falliti di svelare i segreti che il mobiletto nasconde alla vista.\n\nSe vuoi aprire questo mobiletto, dovrai trovare la chiave.", "La chiave presa dai resti mostruosi del contadino Dalson entra perfettamente nella serratura. Le ante del mobiletto si spalancano, rivelando diversi oggetti rimasti intatti che sembrano piuttosto preziosi.", 0x41d8cf5e, nil, nil, 0x65ca593a, 0xc4ba31d6, ".mm.." },
  [5061] = { "⟦Aquatic Form=Forma Acquatica⟧", "Torna a Darnassus e mostra il ⟦Pendant of the Sea Lion=Pendente del Leone Marino⟧ a Mathrengyl Bearwalker.", "Hai completato le lezioni che tutti i giovani druidi ricevono prima di poter assumere un aspetto acquatico. Ora torna dal tuo istruttore, Mathrengyl Bearwalker, a Darnassus. Mostragli il tuo pendente e dimostragli che sei pront<o/a> a imparare ciò che ha da insegnarti. Completerà il tuo addestramento, permettendoti di diventare tutt'uno con l'acqua.\n\nAddio, giovane <druido/druida>. Ci rivedremo.", "Il tuo ritorno a Darnassus non è passato inosservato, ma prima di insegnarti la tua forma acquatica mi serve una prova delle lezioni che hai imparato a ⟦Moonglade=Radaluna⟧.\n\nHai il ⟦Pendant of the Sea Lion=Pendente del Leone Marino⟧?", "Davvero notevole, {name}. Sei pront<o/a> a imparare la tua forma acquatica, ed è un piacere per me insegnartela.\n\nInoltre, in riconoscimento di quanto hai ottenuto nelle due prove, ti do questo oggetto. Spero che sarà un'aggiunta gradita al tuo equipaggiamento di <protettore/protettrice> della natura e custode dell'equilibrio.", 0xb41f2b6a, 0x8aa8f24e, 0x489ae05e, 0x5ac3a51a, 0xd9b19ec7, "....." },
  [5062] = { "Il fuoco sacro", "Raccogli 10 fasci di ⟦Incendia Agave=Agave Incendiaria⟧, poi consulta Magatha Grimtotem sull'⟦Elder Rise=Altura degli Anziani⟧, a Picco del Tuono.", "Arikara è una creatura letale che va affrontata in fretta. Per darle la caccia dovrai accendere il sacro fuoco della vita: questo evocherà Arikara.\n\nVa' ora a raccogliere la rara pianta di ⟦Incendia Agave=Agave Incendiaria⟧. Quando ne avrai raccolta abbastanza, chiedi consiglio a Magatha Grimtotem sull'⟦Elder Rise=Altura degli Anziani⟧, a ⟦Thunder Bluff=Picco del Tuono⟧. È una potente sciamana in grado di incantare l'agave per creare una polvere che accenderà il fuoco.\n\nViaggia verso nord-est fino alla Boiling Pool e raccogli l'⟦Incendia Agave=Agave Incendiaria⟧.", "Dunque, Motega Firemain porta notizie di Arikara... be', questa sì che è una notizia grave.\n\n<Magatha si guarda intorno.>\n\nArikara è una creatura letale, nata al solo scopo di vendicarsi di chi ha commesso atti efferati.\n\n<Magatha sorride.>", "Bene, hai raccolto la quantità necessaria di Agave Incendiaria. Questa erba rara, che si trova solo a ⟦Thousand Needles=Millepicchi⟧, aiuterà ad accendere il sacro fuoco della vita, ora sopito.\n\n<Magatha comincia a incantare l'Agave Incendiaria.>", 0x9dc5fce0, 0x70d40b13, 0x0a6138b7, 0x33505e7f, 0xf61de319, "....." },
  [5064] = { "Spie tra i ⟦Grimtotem=Totem Truce⟧", "Trova e recupera le tre Note Segrete nel ⟦Darkcloud Pinnacle=Pinnacolo Nubenera⟧.", "{name}, in passato ci hai servito bene, perciò ora ti affido una missione importante. Il clan ⟦Grimtotem=Totem Truce⟧ sta tramando qualcosa in segreto. Nelle ultime settimane sono stati visti tre agenti di origine sconosciuta far visita ai ⟦Grimtotem=Totem Truce⟧. Abbiamo scoperto che questi messaggi custoditi si trovano in forzieri separati nel ⟦Darkcloud Pinnacle=Pinnacolo Nubenera⟧.\n\n{name}, se riuscirai in questa pericolosa missione, ti ricompenserò come meriti.", "Hai scoperto cosa stanno tramando i ⟦Grimtotem=Totem Truce⟧?", "Per il Grande ⟦Spirit Totem=Totem dello Spirito⟧! È davvero una notizia terribile. Devo cominciare a prepararmi a qualunque cosa accada.\n\n{name}, come promesso, ecco la ricompensa per il tuo coraggioso servizio.", 0x1d41db0b, 0x6337089b, 0xe2051aef, 0xeadd4ac5, 0x5057c83b, "....." },
  [5065] = { "Le tavolette perdute di Mosh'aru", "Porta la Terza Tavoletta Mosh'aru e la Quarta Tavoletta Mosh'aru al prospettore Ironboot, a Tanaris.", "Il troll con cui hai parlato non ha detto la verità. Le due tavolette che hai recuperato per lui parlavano di come imprigionare l'essenza di Hakkar, ma quella leggenda nasconde molto di più. Ho studiato a lungo e ho scoperto che le tavolette di Mosh'aru sono sei, non due! Sei!\n\nE temo che i segreti custoditi dalle altre non ci piaceranno...\n\nTrova la terza e la quarta tavoletta di Mosh'aru. Sono nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧, in mano ai troll Mossflayer. Trovale e portamele.", "Hai le tavolette? Temo che i loro testi rivelino una grande minaccia per il nostro mondo.", "Le hai trovate! Fantastico!\n\nGrazie, {name}. Studierò a fondo questi testi e ne decifrerò il significato.\n\nTu, invece, hai un altro compito...", 0xe77103e4, 0xdbd88b64, 0xfd9f868d, 0xfb0acacc, 0x5da12bd6, "....." },
  [5066] = { "Chiamata alle armi: le ⟦Plaguelands=Terre Infette⟧!", "Cerca il comandante Ashlam Valorfist. Il suo campo base si trova all'⟦Chillwind Camp=Accampamento di Ventofreddo⟧, a nord delle ⟦Alterac Mountains=Montagne d'Alterac⟧.", "Udite, udite! Tutti gli eroi sono chiamati ad ascoltare queste parole!\n\nIl Regno di ⟦Stormwind=Roccavento⟧ ha lanciato una chiamata alle armi! Chiunque sia in grado di combattere è invitato a impugnare le armi contro l'oscura minaccia del Flagello, nelle terre settentrionali dei Regni Orientali! Corrono voci di nuove minacce che sorgono dalle rovine delle ⟦Plaguelands=Terre Infette⟧!\n\nEroi del regno, cercate il comandante Ashlam Valorfist, che ha stabilito il suo campo base all'⟦Chillwind Camp=Accampamento di Ventofreddo⟧, a nord delle ⟦Alterac Mountains=Montagne d'Alterac⟧!", nil, "Benvenut<o/a> nelle ⟦Plaguelands=Terre Infette⟧, <eroe/eroina>. Questa è una delle frontiere più pericolose di Azeroth, soprattutto con la minaccia incombente del Flagello a nord e a nord-est. Sono lieto di sapere che il richiamo squillante del dovere e del servizio al bene superiore non è rimasto inascoltato da te!\n\nSe sei pront<o/a> a sporcarti le mani, qui ai margini delle ⟦Plaguelands=Terre Infette⟧ c'è molto da fare per gli eroi volenterosi e capaci.", 0x7b917538, 0x754a0fb2, 0xc77e27ed, nil, 0xb7a1f1f9, "...m." },
  [5081] = { "La missione di Maxwell", "Raggiungi i ⟦Blackrock Spire=Bastioni di Roccianera⟧ e distruggi War Master Voone, Highlord Omokk e Overlord Wyrmthalak. Torna dal maresciallo Maxwell quando avrai finito.", "Queste informazioni colmano le lacune della nostra conoscenza, altrimenti impeccabile, dei ⟦Blackrock Spire=Bastioni di Roccianera⟧.\n\nL'attacco dev'essere decisivo, {name}.\n\nPer prima cosa va distrutto il loro maestro di guerra, il troll Voone. Senza i suoi piani di battaglia, gli orchi ⟦Blackrock=Roccianera⟧ precipiteranno nel caos.\n\nPoi dovrai eliminare il gran signore degli ogre, Omokk. Senza la sua guida, i codardi ogre di ⟦Blackrock=Roccianera⟧ sono impotenti.\n\nInfine il signore supremo della cittadella: Wyrmthalak. Con Wyrmthalak morto, il loro comando centrale resterà senza un tramite.", "Rapporto?", "Ottimo lavoro, {name}. Se non altro, ci hai fatto guadagnare altro tempo: tempo prezioso, preziosissimo.", 0xc1d7f82a, 0x1da97ed4, 0x4be46f5e, 0x443e5ca0, 0x59df8873, "....." },
  [5082] = { "La minaccia dei Freddinverno", "Donova Snowden, a ⟦Winterspring=Fontefredda⟧, vuole che tu uccida 8 Winterfall Pathfinder, 8 Winterfall Den Watcher e 8 Winterfall Totemic.", "Sono venuta a ⟦Winterspring=Fontefredda⟧ per studiare le ⟦Frostfire Hot Springs=Sorgenti di Fuocogelo⟧. Ho notato che l'acqua sembra avere... strane proprietà. Non sono ancora riuscita a scoprirne l'origine e, a dirti la verità, ultimamente ho avuto qualche difficoltà a causa dei mezzorsi Freddinverno.\n\nSembrano attratti dalle sorgenti, proprio come me. Sono diventati estremamente protettivi verso l'acqua e non mi lasciano avvicinare alle due sorgenti più grandi, a nord di qui.\n\nVorrei continuare i miei studi: mi aiuterai?", "Ti sono grata per l'aiuto!", "Grazie mille, {name}! Ora posso tornare al lavoro.\n\nHai trovato qualcosa di interessante all'accampamento dei Freddinverno?", 0x4fbdaff6, 0x80980e27, 0x39dd244f, 0xc3066c72, 0xe6b3e78a, "....." },
  [5083] = { "⟦Winterfall Firewater=Corroborante dei Freddinverno⟧", "Porta l'Empty Firewater Flask a Donova Snowden, a ⟦Winterspring=Fontefredda⟧.", "La fiaschetta che hai preso ai mezzorsi Freddinverno è vuota, ma dentro noti alcune gocce di uno strano liquido verde; sembra quasi brillare.\n\nSarà qualcosa di importante?\n\nDonova Snowden probabilmente saprebbe dirti di più, visto che è accampata da un po' di tempo presso le sorgenti calde di ⟦Winterspring=Fontefredda⟧.", "Che cosa hai trovato?", "L'hai presa ai Freddinverno?", 0x15a9986b, 0x0434cdb1, 0xb596a84a, 0xd0ef59f6, 0xcb26aece, "....." },
  [5084] = { "Preda della corruzione", "Cerca un indizio nell'accampamento dei mezzorsi Legnomorto, nel nord del ⟦Felwood=Vilbosco⟧.", "Questo liquido verdastro... mi ricorda un po' la melma che ho visto attraversando il ⟦Felwood=Vilbosco⟧. E ho visto alcuni Winterfall Runner passare nel territorio dei Mordilegno... Forse queste cose hanno a che fare con la fiaschetta che hai trovato, {name}.\n\nC'è un grosso gruppo di mezzorsi appena oltre il ⟦Timbermaw Hold=Rifugio dei Mordilegno⟧, nel ⟦Felwood=Vilbosco⟧. Si chiamano tribù dei Legnomorto e sono stati corrotti e fatti impazzire dal vil. Perché non dai un'occhiata da quelle parti e vedi se trovi prove di traffici tra i Freddinverno e i Legnomorto?", nil, "Nel calderone ribolle una sostanza putrida dall'odore ripugnante...", 0x3b25fa7e, 0xabd4571f, 0x98d89400, nil, 0xe72eed6e, "...m." },
  [5085] = { "Una sostanza misteriosa", "Riferisci le tue scoperte a Donova Snowden.", "La sostanza verdastra nel calderone sembra simile a quella che hai trovato nella fiaschetta. Questa strana poltiglia potrebbe essere corrotta quanto i mezzorsi che l'hanno prodotta...\n\nSe i mezzorsi Freddinverno la usano, vuol dire che presto saranno corrotti quanto la tribù dei Legnomorto?\n\nSarebbe meglio riferire le tue scoperte a Donova, insieme a un campione del liquido del calderone.", "Spero che tu abbia trovato qualcosa, {name}. I Freddinverno sono sempre più aggressivi!", "Sei davvero <pieno/piena> di risorse, {name}. Credi che i mezzorsi Freddinverno siano stati all'accampamento dei Legnomorto?", 0x231688a0, 0x30444789, 0xd6bbb6f1, 0x0f8de502, 0xbc19bf3d, "....." },
  [5086] = { "Orrori tossici", "Raccogli 3 Goccia di Orrore Tossico per Donova Snowden, a ⟦Winterspring=Fontefredda⟧.", "Ho studiato il campione che hai riportato e, anche se non posso esserne certa, credo contenga tracce di elementi tossici. L'unico modo per saperlo con sicurezza, però, è raccoglierne un po' per fare un confronto.\n\nCredo che i mezzorsi Legnomorto ricavino questi elementi da altre creature corrotte del ⟦Felwood=Vilbosco⟧; in particolare dagli elementali che vivono nel ⟦Irontree Woods=Bosco di Troncoferro⟧, chiamati orrori tossici.\n\nRaccogli qualche campione da confrontare, ma fa' attenzione: laggiù è molto pericoloso!", "Credo che stiamo cominciando a capire cosa succede qui, {name}.", "Devo confrontarla con la sostanza che hai trovato nel calderone, e poi sono sicura che ne sapremo di più.", 0x26ee22fb, 0x501b4707, 0x001b66ba, 0x09b0df92, 0x0cbe58e7, "....." },
  [5087] = { "I corrieri dei Freddinverno", "Trova i Winterfall Runner e impedisci loro di consegnare il carico al ⟦Winterfall Village=Villaggio dei Freddinverno⟧.", "Molto interessante, {name}...\n\nQuando questa sostanza tossica si mescola con l'acqua delle sorgenti calde perde la sua tossicità e conserva solo la capacità di alterare per un po' chi la ingerisce. Ecco perché i Freddinverno difendono le sorgenti calde con tanto fervore: gli servono per purificare il loro corroborante.\n\nDobbiamo fermarli e tagliare i contatti tra i Freddinverno e i Legnomorto. Un gruppo di corrieri percorre la strada tra il loro villaggio e ⟦Felwood=Vilbosco⟧. Trovali, sconfiggili e ruba il loro carico.", "Vediamo cosa succede quando i Freddinverno restano senza corroborante!", "<Donova esamina il contenuto della cassa.>\n\nMi chiedo se ingerire questa sostanza renda i mezzorsi più aggressivi. Sembrano davvero molto più grossi...", 0x2f0113a6, 0x230d59b0, 0xfd258e1b, 0x1014a9a4, 0x0a41afec, "....." },
  [5088] = { nil, "Uccidi Arikara. Porta i suoi resti e la ⟦Incendia Powder=Polvere Incendiaria⟧ a Motega Firemane, all'⟦Whitereach Post=Accampamento di Manto Bianco⟧, come prova della tua impresa.", "Porta questa ⟦Incendia Powder=Polvere Incendiaria⟧ raffinata e purificata a ⟦Thousand Needles=Millepicchi⟧ e gettala sul sacro fuoco della vita. Si trova nel ⟦Darkcloud Pinnacle=Pinnacolo Nubenera⟧, su un picco isolato dove seppelliscono i loro morti.\n\nL'incantesimo che ho intessuto nella ⟦Incendia Powder=Polvere Incendiaria⟧ evocherà Arikara davanti a te, {name}.\n\nTemo che stia dando la caccia a Cairne Bloodhoof; troppe tradizioni dei tauren sono cambiate, e temo che questo abbia fatto infuriare Arikara. Muoviti in fretta, prima che sia tutto perduto, {class}!", "Hai ucciso il feroce serpente Arikara, {name}?", "Non ha senso. Perché Arikara dovrebbe dare la caccia a Cairne Bloodhoof? Magatha non può sbagliarsi, è la nostra sciamana più potente.\n\n<Motega scuote la testa.>\n\nIn ogni caso, la tua grande impresa per l'⟦Horde=Orda⟧ non passerà inosservata: ti prego, scegli una di queste ricompense per il tuo aiuto.", 0x23d8ed72, 0x9be1e884, 0x8904b789, 0x593eac54, 0x685290fb, "e...." },
  [5089] = { "⟦General Drakkisath's Command=Comando del Generale Drakkisath⟧", "Porta il ⟦General Drakkisath's Command=Comando del Generale Drakkisath⟧ al maresciallo Maxwell, nelle ⟦Burning Steppes=Steppe Ardenti⟧.", "Dal cadavere del serpe sconfitto recuperi quello che sembra un messaggio di una certa importanza: una lettera del suo superiore, il generale Drakkisath, riguardo al protocollo.\n\nL'istinto ti dice di portarla al maresciallo Maxwell.", "Cos'hai lì, {name}?", "La faccenda si complica...", 0xf8941430, 0x20e21738, 0x0981eb66, 0x421c38bd, 0x84ca30b3, "....." },
  [5090] = { "Chiamata alle armi: le ⟦Plaguelands=Terre Infette⟧!", "Cerca il comandante Ashlam Valorfist. Il suo campo base si trova all'⟦Chillwind Camp=Accampamento di Ventofreddo⟧, a nord delle ⟦Alterac Mountains=Montagne d'Alterac⟧.", "Udite, udite! Tutti gli eroi sono chiamati ad ascoltare queste parole!\n\nIl Regno di ⟦Stormwind=Roccavento⟧ ha lanciato una chiamata alle armi! Chiunque sia in grado di combattere è invitato a impugnare le armi contro l'oscura minaccia del Flagello, nelle terre settentrionali dei Regni Orientali! Corrono voci di nuove minacce che sorgono dalle rovine delle ⟦Plaguelands=Terre Infette⟧!\n\nEroi del regno, cercate il comandante Ashlam Valorfist, che ha stabilito il suo campo base all'⟦Chillwind Camp=Accampamento di Ventofreddo⟧, a nord delle ⟦Alterac Mountains=Montagne d'Alterac⟧!", nil, "Benvenut<o/a> nelle ⟦Plaguelands=Terre Infette⟧, <eroe/eroina>. Questa è una delle frontiere più pericolose di Azeroth, soprattutto con la minaccia incombente del Flagello a nord e a nord-est. Sono lieto di sapere che il richiamo squillante del dovere e del servizio al bene superiore non è rimasto inascoltato da te!\n\nSe sei pront<o/a> a sporcarti le mani, qui ai margini delle ⟦Plaguelands=Terre Infette⟧ c'è molto da fare per gli eroi volenterosi e capaci.", 0x7b917538, 0x754a0fb2, 0xc77e27ed, nil, 0xe8509ad0, "...m." },
  [5091] = { "Chiamata alle armi: le ⟦Plaguelands=Terre Infette⟧!", "Cerca il comandante Ashlam Valorfist. Il suo campo base si trova all'⟦Chillwind Camp=Accampamento di Ventofreddo⟧, a nord delle ⟦Alterac Mountains=Montagne d'Alterac⟧.", "Udite, udite! Tutti gli eroi sono chiamati ad ascoltare queste parole!\n\nIl Regno di ⟦Stormwind=Roccavento⟧ ha lanciato una chiamata alle armi! Chiunque sia in grado di combattere è invitato a impugnare le armi contro l'oscura minaccia del Flagello, nelle terre settentrionali dei Regni Orientali! Corrono voci di nuove minacce che sorgono dalle rovine delle ⟦Plaguelands=Terre Infette⟧!\n\nEroi del regno, cercate il comandante Ashlam Valorfist, che ha stabilito il suo campo base all'⟦Chillwind Camp=Accampamento di Ventofreddo⟧, a nord delle ⟦Alterac Mountains=Montagne d'Alterac⟧!", nil, "Benvenut<o/a> nelle ⟦Plaguelands=Terre Infette⟧, <eroe/eroina>. Questa è una delle frontiere più pericolose di Azeroth, soprattutto con la minaccia incombente del Flagello a nord e a nord-est. Sono lieto di sapere che il richiamo squillante del dovere e del servizio al bene superiore non è rimasto inascoltato da te!\n\nSe sei pront<o/a> a sporcarti le mani, qui ai margini delle ⟦Plaguelands=Terre Infette⟧ c'è molto da fare per gli eroi volenterosi e capaci.", 0x7b917538, 0x754a0fb2, 0xc77e27ed, nil, 0xe8509ad0, "...m." },
  [5092] = { "Aprire la strada", "Uccidi 10 Skeletal Flayer e 10 Slavering Ghoul alla ⟦Sorrow Hill=Collina del Cordoglio⟧.\n\nTorna dal comandante Ashlam Valorfist all'⟦Chillwind Camp=Accampamento di Ventofreddo⟧, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧.", "Dato che le strade occidentale e settentrionale che portano ad Andorhal sono ben fortificate, intendo colpire la città dalla strada orientale, meno difesa. Il Flagello si affida alla barriera di non morti che infesta la ⟦Sorrow Hill=Collina del Cordoglio⟧ come prima linea di difesa. Se vogliamo avanzare su Andorhal, dovremo passare per la ⟦Sorrow Hill=Collina del Cordoglio⟧.\n\nIl tuo primo incarico sarà aprire la strada attraverso la ⟦Sorrow Hill=Collina del Cordoglio⟧. Sfoltisci gli scheletri e i ghoul che infestano la zona, poi torna a farmi rapporto quando avrai finito!", "Voglio che ti prepari al peggio, {name}: tira fuori tutto il coraggio che hai. Il compito che ci aspetta non sarà facile. Mentre raduniamo qui le nostre forze per colpire infine il Flagello, tu farai parte dell'avanguardia che porterà la battaglia fino a loro! La missione che ti è stata assegnata alla ⟦Sorrow Hill=Collina del Cordoglio⟧ aprirà la nostra strada verso la vittoria!", "Missione compiuta, {name}! Ben giocata, ben giocata.\n\nPermettimi di ricompensare il lavoro che hai svolto finora con un po' di monete dalle casse di ⟦Stormwind=Roccavento⟧. Ti consiglio di spenderle in materiale che ti aiuti nella prossima missione... una che ti porterà tra le rovine della stessa Andorhal.\n\nTieniti pront<o/a>! Resta vigile!", 0xd2c451f5, 0x96757f86, 0xbbefaa38, 0x89451a7b, 0x40d0f72b, "....." },
  [5093] = { "Chiamata alle armi: le ⟦Plaguelands=Terre Infette⟧!", "Cerca l'alto esecutore Derrington. Il suo campo base si trova alla Granbarricata, a est delle Radure di Tirisfal e di ⟦Undercity=Sepulcra⟧.", "Eroi del regno, ascoltatemi: l'⟦Horde=Orda⟧ vi chiama ad agire senza indugio!\n\nÈ stata lanciata una chiamata alle armi: chiunque sia in grado di combattere impugni le armi contro il Flagello! Corrono voci di nuove minacce che sorgono dalle rovine dei Regni Orientali. Incombono a est di ⟦Undercity=Sepulcra⟧, nelle regioni settentrionali delle terre ora note come ⟦Plaguelands=Terre Infette⟧!\n\nEroi del regno, cercate l'alto esecutore Derrington, che ha stabilito il suo campo base alla Granbarricata, a est delle Radure di Tirisfal!", nil, "Benvenut<o/a> nelle ⟦Plaguelands=Terre Infette⟧, <eroe/eroina>. Questa è una delle frontiere più pericolose di Azeroth, con la minaccia incombente del Flagello a est, e ancora più a est da lì. Sono lieto di sapere che la chiamata del dovere e del servizio all'⟦Horde=Orda⟧ non è rimasta inascoltata da te!\n\nSe sei pront<o/a> a sporcarti le mani, qui ai margini delle ⟦Plaguelands=Terre Infette⟧ c'è molto da fare per gli eroi volenterosi e capaci.", 0x7b917538, 0x1bad0a2f, 0x9504b319, nil, 0x00c7d144, "...m." },
  [5094] = { "Chiamata alle armi: le ⟦Plaguelands=Terre Infette⟧!", "Cerca l'alto esecutore Derrington. Il suo campo base si trova alla Granbarricata, a est delle Radure di Tirisfal e di ⟦Undercity=Sepulcra⟧.", "Eroi del regno, ascoltatemi: l'⟦Horde=Orda⟧ vi chiama ad agire senza indugio!\n\nÈ stata lanciata una chiamata alle armi: chiunque sia in grado di combattere impugni le armi contro il Flagello! Corrono voci di nuove minacce che sorgono dalle rovine dei Regni Orientali. Incombono a est di ⟦Undercity=Sepulcra⟧, nelle regioni settentrionali delle terre ora note come ⟦Plaguelands=Terre Infette⟧!\n\nEroi del regno, cercate l'alto esecutore Derrington, che ha stabilito il suo campo base alla Granbarricata, a est delle Radure di Tirisfal!", nil, "Benvenut<o/a> nelle ⟦Plaguelands=Terre Infette⟧, <eroe/eroina>. Questa è una delle frontiere più pericolose di Azeroth, con la minaccia incombente del Flagello a est, e ancora più a est da lì. Sono lieto di sapere che la chiamata del dovere e del servizio all'⟦Horde=Orda⟧ non è rimasta inascoltata da te!\n\nSe sei pront<o/a> a sporcarti le mani, qui ai margini delle ⟦Plaguelands=Terre Infette⟧ c'è molto da fare per gli eroi volenterosi e capaci.", 0x7b917538, 0x1bad0a2f, 0x9504b319, nil, 0x00c7d144, "...m." },
  [5095] = { "Chiamata alle armi: le ⟦Plaguelands=Terre Infette⟧!", "Cerca l'alto esecutore Derrington. Il suo campo base si trova alla Granbarricata, a est delle ⟦Tirisfal Glades=Radure di Tirisfal⟧ e di ⟦Undercity=Sepulcra⟧.", "Eroi del regno, ascoltatemi: l'⟦Horde=Orda⟧ vi chiama ad agire senza indugio!\n\nÈ stata lanciata una chiamata alle armi: chiunque sia in grado di combattere impugni le armi contro il Flagello! Corrono voci di nuove minacce che sorgono dalle rovine dei Regni Orientali. Incombono a est di ⟦Undercity=Sepulcra⟧, nelle regioni settentrionali delle terre ora note come ⟦Plaguelands=Terre Infette⟧!\n\nEroi del regno, cercate l'alto esecutore Derrington, che ha stabilito il suo campo base alla Granbarricata, a est delle ⟦Tirisfal Glades=Radure di Tirisfal⟧!", nil, "Benvenut<o/a> nelle ⟦Plaguelands=Terre Infette⟧, <eroe/eroina>. Questa è una delle frontiere più pericolose di Azeroth, con la minaccia incombente del Flagello a est, e ancora più a est da lì. Sono lieto di sapere che la chiamata del dovere e del servizio all'⟦Horde=Orda⟧ non è rimasta inascoltata da te!\n\nSe sei pront<o/a> a sporcarti le mani, qui ai margini delle ⟦Plaguelands=Terre Infette⟧ c'è molto da fare per gli eroi volenterosi e capaci.", 0x7b917538, 0x3496d17e, 0x4167d15e, nil, 0x00c7d144, "...m." },
  [5096] = { "Diversivi scarlatti", "Raggiungi il campo base della Crociata Scarlatta tra il ⟦Felstone Field=Campo di Vilpietra⟧ e le Lacrime di Dalson e distruggi la loro tenda di comando.\n\nPianta lo stendardo del Flagello nel campo, poi torna dall'alto esecutore Derrington alla Granbarricata, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧.", "Prima di Andorhal dobbiamo affrontare la minaccia della ⟦Scarlet Crusade=Crociata Scarlatta⟧ che avanza da ⟦Hearthglen=Valsalda⟧. Si sono accampati tra il ⟦Felstone Field=Campo di Vilpietra⟧ e le Lacrime di Dalson, e ci costringono a rischiare uno scontro contro il Flagello e la Crociata insieme.\n\nIl mio piano è metterli l'uno contro l'altro mandandoti a distruggere la tenda di comando che hanno montato; usa un po' di ⟦Flame in a Bottle=Fiamma in Bottiglia⟧ da questa cassa di incendiari. Una volta rasa al suolo, pianta questo stendardo del Flagello accanto alla tenda. Con un po' di fortuna ignoreranno noi e si concentreranno sul Flagello per vendicarsi.", "Un'incursione a sorpresa contro la precaria posizione avanzata della ⟦Scarlet Crusade=Crociata Scarlatta⟧ ci darà un margine di tempo per poter marciare su Andorhal. Confido che tu sia qui per annunciare un successo!\n\nUna volta portata a termine, dovremo lavorare con diligenza e in fretta. Non abbiamo i mezzi né gli uomini per combattere il Flagello e la ⟦Scarlet Crusade=Crociata Scarlatta⟧ allo stesso tempo, se non abboccano al nostro piccolo stratagemma.", "Ben eseguito, {name}. Il tuo attacco alla ⟦Scarlet Crusade=Crociata Scarlatta⟧ ci farà guadagnare tempo. Ho mandato uno dei miei migliori esploratori a sorvegliare il campo e ad assicurarsi che le forze della Crociata che arriveranno a rinforzare la posizione abbocchino all'esca.\n\nOra che la pressione su di noi è diminuita, dovremmo finalmente poter rischiare una missione dentro Andorhal, e per giunta importante. Visto il tuo successo fin qui, mi piacerebbe molto che te ne occupassi tu.", 0xbdf948db, 0x3fc3d507, 0xbe79ad52, 0x3b96be5f, 0xe0fffe3e, "....." },
  [5097] = { "Lungo le torri di guardia", "Con la ⟦Beacon Torch=Torcia del Faro⟧ segna ogni torre di Andorhal; per riuscirci dovrai metterti sulla soglia della torre.\n\nQuando tutte e quattro le torri saranno segnate, riporta la ⟦Beacon Torch=Torcia del Faro⟧ al comandante Ashlam Valorfist, all'⟦Chillwind Camp=Accampamento di Ventofreddo⟧, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧.", "Con un congegno magico chiamato torcia del faro possiamo segnare i bersagli che scegliamo per le future azioni delle nostre truppe. A questo proposito, crediamo che il Flagello usi le torri di guardia di Andorhal per controllare i movimenti delle sue truppe.\n\nLa tua missione: sfonda le difese di Andorhal e piazza i segnali in tutte e quattro le torri di guardia. Per piazzare il segnale dovrai trovarti sulla soglia di ogni torre; a quel punto la torre verrà segnata. La torcia del faro ha solo cinque cariche, quindi usale con giudizio!", "Una volta segnate, le torri diventeranno bersagli di massima priorità per il nostro attacco ad Andorhal. Sospetto che, una volta neutralizzate le torri, verrà allo scoperto la vera minaccia di Andorhal. Da quel momento sarà uno scontro aperto per il controllo della città!\n\nSei tornat<o/a> per riferire un successo, vero? Non dimenticare anche la torcia del faro: dobbiamo tenere sotto controllo il nostro materiale.", "I miei sacerdoti riferiscono che i nostri rilevatori di segnali captano segnali fortissimi da tutte e quattro le torri! Oserei dire che hai portato a termine un'altra missione con un successo pieno e totale! Ben fatto ancora una volta, {name}!\n\nCon le torri segnate, i preparativi per l'attacco sono pronti. È giunto il momento di portare la battaglia al Flagello!", 0x7d392ded, 0x803d6c0b, 0x6158171c, 0x1bebd1b4, 0xfee8a424, "....." },
  [5098] = { "Lungo le torri di guardia", "Con la ⟦Beacon Torch=Torcia del Faro⟧ segna ogni torre di Andorhal; per riuscirci dovrai metterti sulla soglia della torre.\n\nQuando tutte e quattro le torri saranno segnate, riporta la ⟦Beacon Torch=Torcia del Faro⟧ all'alto esecutore Derrington, alla Granbarricata, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧.", "Con un congegno magico chiamato torcia del faro possiamo segnare i bersagli che scegliamo per le future azioni delle nostre truppe. A questo proposito, crediamo che il Flagello usi le torri di guardia di Andorhal per controllare i movimenti delle sue truppe.\n\nLa tua missione: sfonda le difese di Andorhal e piazza i segnali in tutte e quattro le torri di guardia. Per piazzare il segnale dovrai trovarti sulla soglia di ogni torre; a quel punto la torre verrà segnata. La torcia del faro ha solo cinque cariche, quindi usale con giudizio!", "Una volta segnate, le torri diventeranno bersagli di massima priorità per il nostro attacco ad Andorhal. Sospetto che, una volta neutralizzate le torri, verrà allo scoperto la vera minaccia di Andorhal. Da quel momento sarà uno scontro aperto per il controllo della città!\n\nSei tornat<o/a> per riferire un successo, vero? Non dimenticare anche la torcia del faro: dobbiamo tenere sotto controllo il nostro materiale.", "I miei stregoni riferiscono che i nostri rilevatori di segnali captano segnali fortissimi da tutte e quattro le torri! Hai eseguito i miei ordini con l'abilità e la precisione di un veterano consumato. Il tuo servizio all'⟦Horde=Orda⟧ è stato debitamente annotato ancora una volta, {name}!\n\nCon le torri segnate, i preparativi per l'attacco sono pronti. È giunto il momento di portare la battaglia al Flagello!", 0x7d392ded, 0xd0c3eb85, 0x6158171c, 0x1bebd1b4, 0x40e0bbc0, "....." },
  [5101] = { "La definitiva missione di prova di Lee... della rovina!", "Uccidi 6 pecore per Benny e poi scappa a gambe levate!\n\nScherzavo... sulla parte della fuga.", "Bah! Che ti credi che è, una specie di missione di prova? Scommetto che ci stanno pure gli errori di battitura!\n\nSe tu pensa che la mia missione sarà facile, allora ti sbagli di grosso!\n\nAmmazzami dieci pecore (1933) e non tornare finché non l'hai fatto!", nil, nil, 0xbc8fc11e, 0x2265a0a6, 0x9d3537f4, nil, nil, "...mm" },
  [5102] = { "La fine del generale Drakkisath", "Raggiungi i ⟦Blackrock Spire=Bastioni di Roccianera⟧ e distruggi General Drakkisath. Torna dal maresciallo Maxwell quando avrai finito.", "Combattiamo queste bestie su due fronti: dalla nostra capitale, ⟦Stormwind=Roccavento⟧, le combattiamo dall'interno, e qui, nelle ⟦Burning Steppes=Steppe Ardenti⟧, portiamo la battaglia fin sulla loro soglia. Dobbiamo essere vigili, {name}. Nessuno dovrà essere risparmiato dalla nostra ira, così come nessuno dei nostri è stato risparmiato quando hanno colpito le nostre case e le nostre famiglie.\n\nTrova questo generale Drakkisath e distruggilo!\n\nIl compito non sarà certo semplice, ma le ricompense saranno straordinarie.", "È fatta?", "Di sicuro la prossima volta colpiremo i loro signori dei draghi. Ben fatto, valoroso soldato dell'⟦Alliance=Alleanza⟧! Davvero ben fatto.", 0xda93b846, 0x12dc4302, 0x505fe600, 0xcd001c89, 0x72a4103b, "....." },
  [5103] = { "Una morte rovente", "Qualcuno a questo mondo saprà di certo cosa fare con questi guanti. Buona fortuna!", "Di questo umano restano solo alcune ossa carbonizzate. Sembra sia morto a un passo da ciò che cercava: dei guanti lunghi a piastre compatte.\n\nForse dovresti prendere i guanti e uscire dal fuoco?", nil, "Ma che...", 0x8ca51a7a, 0xafc08c96, 0x7b24a4a8, nil, 0xeef4b8c1, "...m." },
  [5121] = { "Il gran capo dei Freddinverno", "Donova Snowden, a ⟦Winterspring=Fontefredda⟧, vuole che tu sconfigga High Chief Winterfall.", "Anche se sappiamo ancora molto poco del perché i mezzorsi abbiano cominciato a ingerire questa strana sostanza, credo sia meglio porvi fine prima che la situazione sfugga di mano.\n\nI mezzorsi Freddinverno di solito non sono una tribù aggressiva, e questo cambiamento nel loro comportamento mi fa pensare che stiano eseguendo gli ordini del loro capo. Molto probabilmente non possiamo rimediare al danno già fatto, ma credo che, se il loro capo verrà ucciso, non peggioreranno.\n\nDirigiti a est, verso il ⟦Winterfall Village=Villaggio dei Freddinverno⟧.", "Forse scoprirai di più al ⟦Winterfall Village=Villaggio dei Freddinverno⟧, {name}.", "Grazie mille, {name}. Spero di poter tornare ai miei studi senza il timore di finire in un'imboscata. Ti prego, accetta questo come ricompensa.", 0x59ba9908, 0x9c90284c, 0x285ff1e1, 0x3e30620a, 0x0f79db1a, "....." },
  [5123] = { "L'ultimo tassello", "Porta il Crudely-written Log a Donova Snowden, a ⟦Winterspring=Fontefredda⟧.", "Il registro che hai trovato addosso al gran capo sembra corposo, ma dopo averne sfogliato un paio di pagine ti accorgi che non riesci a leggerne il testo. I segni sono così rozzi e mal tracciati che non sei sicur<o/a> che qualcuno sia in grado di leggerli.\n\nMa forse Donova saprà dirti cosa c'è scritto...", "Allora, cos'è questo, {name}?", "Chissà cosa significa tutto questo... non riesco a capirci niente...", 0x28d3ab49, 0x996aba1d, 0xef97d132, 0x57559a46, 0xe7bd7f23, "....." },
  [5124] = { "⟦Fiery Plate Gauntlets=Guanti Lunghi a Piastre Ardenti⟧", "Porta a Malyfous Darkhammer 6 Lingotto di Torio Incantato, 2 ⟦Essence of Fire=Essenza di Fuoco⟧ e 4 Rubino Stellato. Dovrai anche consegnare i tuoi ⟦Unfired Plate Gauntlets=Guanti Lunghi a Piastre Compatte⟧.", "Per la barba di Thaurissan!\n\nDove li hai trovati?\n\nMa soprattutto, sei dispost<o/a> a separartene? Naturalmente ti pagherei per un gesto così nobile.\n\nFacciamo così, {name}. Se mi dai quei guanti compatti, ti insegnerò a farne un paio tutto tuo. Devi solo raccogliere i materiali per me, così potrò mettere a punto la ricetta esatta.\n\nAffare fatto??\n\nEcco la lista di ciò che mi serve. Il torio non incantato lo anticipo io, visto che i guanti li fornisci tu.", "Il tempo è denaro, {name}, e io non ho molto né dell'uno né dell'altro.", "Come promesso, {name}, ecco la tua ricetta! Ti aggiungo anche qualcosina in più per tutto il tuo impegno e la tua dedizione. Tanto, che me ne faccio di questi???", 0x4cbb6a5e, 0x87725cc6, 0xccc5a0a0, 0x4f1bc461, 0xda449a9a, "....." },
  [5125] = { "La resa dei conti di Aurius", nil, nil, nil, "{name}, sto morendo... ma la mia anima è salva. Per questo ti devo più di quanto le parole possano dire. Ti prego, prendi questo... e continua a combattere, <valoroso/valorosa> {class}!", 0xca17361a, nil, nil, nil, 0x26926d49, ".mmm." },
  [5126] = { "Il racconto di Lorax", "Parla con Lorax. Ascolta ciò che ha da dire.", "Il satiro cammina avanti e indietro parlando da solo. Vuoi interrogarlo?", nil, "<Lorax ride.>", 0x290b6d8d, 0xbdcfbb0e, 0x7dffec5d, 0x000c2356, 0xa9fb4adc, "...e." },
  [5127] = { "La forgia demoniaca", "Raggiungi i ⟦Blackrock Spire=Bastioni di Roccianera⟧ e trova Goraluk Anvilcrack. Uccidilo, poi usa la ⟦Blood Stained Pike=Picca Macchiata di Sangue⟧ sul suo cadavere. Quando la sua anima sarà stata risucchiata, la picca diventerà una ⟦Soul Stained Pike=Picca dell'Anima Macchiata⟧.\n\nDevi anche trovare il ⟦Unforged Rune Covered Breastplate=Pettorale Corazzato Runico Grezzo⟧.\n\nRiporta sia la ⟦Soul Stained Pike=Picca dell'Anima Macchiata⟧ sia il ⟦Unforged Rune Covered Breastplate=Pettorale Corazzato Runico Grezzo⟧ a Lorax, a ⟦Winterspring=Fontefredda⟧.", "Lorax propone patti, non li accetta da mortali insignificanti.\n\nUn patto lo farò con te, però... prendi questa picca, è intrisa di potenti energie vili. Quando troverai Goraluk Anvilcrack, uccidilo e conficcagli questa picca nel cuore morente. La sua anima ha barattato, la sua anima io avrò. Riportami la picca e riportami il pettorale che il ladro ha rubato, e ti insegnerò ciò che lui avrebbe dovuto imparare.", "Non tentare...", "Il patto non hai tradito. L'anima ho rapito. Il premio è servito.", 0x04505c04, 0xeee70ecd, 0x08cf14df, 0xabcd5b4a, 0x34e0a0e5, "....." },
  [5128] = { "⟦Words of the High Chief=Parole del Gran Capo⟧", "Porta il Crudely-written Log a Kelek Skykeeper, nel ⟦Felwood=Vilbosco⟧ meridionale.", "I Freddinverno non sono più una minaccia per me, ma se vuoi ancora scoprire cosa spingeva i mezzorsi a produrre e a bere questo strano liquore, credo che dovresti cercare Kelek Skykeeper.\n\nFa parte di un gruppo chiamato ⟦Emerald Circle=Fede di Smeraldo⟧, druidi dediti al loro lavoro nel ⟦Felwood=Vilbosco⟧ per guarire la terra dalla corruzione.\n\nKelek ha molta esperienza con i mezzorsi del ⟦Felwood=Vilbosco⟧, e forse saprà dirti di più sul registro.\n\nGrazie ancora, {name}.", "La ⟦Emerald Circle=Fede di Smeraldo⟧ è amica di tutti, {race}. Cosa posso fare per te?", "Sì, se mi lasci esaminarlo per un po', forse riuscirò a tradurtelo.\n\n<Kelek sfoglia le pagine.>\n\nQuando avrò potuto esaminarlo tutto, ti manderò a chiamare.\n\nGrazie per averlo condiviso con me, {name}. Si sa molto poco dei mezzorsi Freddinverno.", 0x87959bae, 0x4374f442, 0xd7d7c1e5, 0x9a2ba698, 0x3af9ca76, "....." },
  [5141] = { "⟦Dragonscale Leatherworking=Conciatura delle Scaglie di Drago⟧", "Porta 2 Pettorale Corazzato di ⟦Scorpid=Scorpide⟧ Indurito, 2 ⟦Tough Scorpid Gloves=Guanti di Scorpide Induriti⟧ e 10 Scaglie di Drago Consumate a Peter Galen ad Azshara.\n\nCompletando questa missione avrai accesso all'arte della ⟦Dragonscale Leatherworking=Conciatura delle Scaglie di Drago⟧.\n\nCompletare questa missione ti impedirà di imparare la ⟦Elemental Leatherworking=Conciatura Elementale⟧ e la ⟦Tribal Leatherworking=Conciatura Tribale⟧; assicurati che sia questa la strada che vuoi seguire prima di farlo.", "La Conciatura delle Scaglie di Drago non è facile, ma dà enormi soddisfazioni. Ti insegnerò a realizzare queste pregiate armature di maglia, ma solo se accetti certe condizioni.\n\nScegliendo questa strada, accetti di non imparare mai la Conciatura Elementale o quella Tribale: al vertice del mestiere c'è posto per una sola delle tre. Inoltre, mi servono alcuni esemplari del tuo miglior lavoro con le armature di scorpide. Infine, mi serve la prova che sai procurarti la materia prima del mestiere: le scaglie dei dragoidi.", "Se sei <pronto/pronta> a prendere una decisione definitiva e diventare <un/una> <conciatore/conciatrice> di scaglie di drago, io sono pronto a prenderti come <allievo/allieva>. Portami ciò che ti ho chiesto e cominceremo la tua formazione.", "Te lo concedo: ci vuole una volontà forte per prendere una decisione definitiva come quella che hai appena preso. Ti assicuro che la Conciatura delle Scaglie di Drago si rivelerà una strada redditizia e gratificante.\n\nPer addestrarti in quest'arte in futuro, ti basterà parlare con me e ti metterò a disposizione tutte le conoscenze che non hai ancora fatto tue.", 0x2bc93035, 0x317a30f5, 0x7a9a3232, 0x250fb4b6, 0x4027ea2b, "....." },
  [5142] = { "La piccola Pamela", "Trova Pamela Redpath.", "Molti di noi morirono nella battaglia del ⟦Darrowshire=Borgo di Darrow⟧. Tanti morirono... e peggio.\n\nQuando la battaglia cominciò nascosi mia nipote Pamela, e non so cosa le sia successo. Non sono che uno spirito errante, ma il mio cuore desidera ancora conoscere la sorte di Pamela.\n\nTi prego, <buon/buona> {class}. Andrai al ⟦Darrowshire=Borgo di Darrow⟧ a cercarla? Si trova a est, oltre il ⟦Gahrron's Withering=Podere di Gahrron⟧.", nil, "Ciao. Io sono Pamela, tu come ti chiami?", 0xbf5c69cb, 0x652ecebd, 0x91cf2076, nil, 0x278965d4, "...m." },
  [5143] = { "⟦Tribal Leatherworking=Conciatura Tribale⟧", "Porta una ⟦Wild Leather Vest=Veste di Cuoio Selvatico⟧ e un ⟦Wild Leather Helmet=Elmetto di Cuoio Selvatico⟧ a Caryssia Moonhunter a Feralas.\n\nCompletando questa missione avrai accesso all'arte della ⟦Tribal Leatherworking=Conciatura Tribale⟧.\n\nCompletare questa missione ti impedirà di imparare la ⟦Dragonscale Leatherworking=Conciatura delle Scaglie di Drago⟧ e la ⟦Elemental Leatherworking=Conciatura Elementale⟧; assicurati che sia questa la strada che vuoi seguire prima di farlo.", "Imparare la Conciatura Tribale richiede di comprendere quanto sia davvero primordiale la natura; so che padroneggi già l'arte di creare armature di cuoio selvatico, e intendo completare il tuo addestramento.\n\nSappi questo, {class}: scegliendo questa strada accetti di non imparare mai la Conciatura delle Scaglie di Drago o quella Elementale; c'è posto per praticare una sola delle tre arti. Inoltre, portami i migliori esemplari delle tue armature di cuoio selvatico. Da lì inizieremo il tuo cammino verso la maestria.", "La natura è una forza che va placata prima che tu possa sperare di imparare a piegarne la volontà nei tuoi indumenti di cuoio. Portami la tua offerta a questa forza, e farò in modo che la tua voce venga ascoltata.", "Hai offerto i tuoi doni migliori, e presto la natura ti permetterà di piegarla alla tua volontà. Quando avrò completato il tuo tirocinio, il tuo lavoro sarà una forza della natura a sé stante.\n\nPer addestrarti in quest'arte in futuro, ti basterà parlare con me e ti metterò a disposizione tutte le conoscenze che non hai ancora fatto tue.", 0x6f10746f, 0xed791b97, 0xeb474bee, 0xb22401c2, 0x4cce757a, "....." },
  [5144] = { "⟦Elemental Leatherworking=Conciatura Elementale⟧", "Porta 2 ⟦Heart of Fire=Cuore di Fuoco⟧, 2 ⟦Globe of Water=Globo d'Acqua⟧, 2 ⟦Core of Earth=Nucleo di Terra⟧ e 2 ⟦Breath of Wind=Soffio di Vento⟧ a Sarah Tanner nella ⟦Searing Gorge=Gorgia Rovente⟧.\n\nCompletando questa missione avrai accesso all'arte della ⟦Elemental Leatherworking=Conciatura Elementale⟧.\n\nCompletare questa missione ti impedirà di imparare la ⟦Dragonscale Leatherworking=Conciatura delle Scaglie di Drago⟧ e la ⟦Tribal Leatherworking=Conciatura Tribale⟧; assicurati che sia questa la strada che vuoi seguire prima di farlo.", "La Conciatura Elementale è ciò che conosco, e se sei <disposto/disposta> ad aprire la mente ai poteri superiori della materia, condividerò con te tutto ciò che c'è da imparare.\n\nSappi questo, {class}: scegliendo questa strada accetti di non imparare mai la Conciatura delle Scaglie di Drago o quella Tribale; c'è posto per praticare una sola delle tre arti. Inoltre, mi serve una prova adeguata che sei in sintonia con gli elementi della natura; a tal fine, portami le essenze più pure di fuoco, acqua, terra e vento.", "Realizzare questo tipo di armature di cuoio richiede pazienza e dedizione. Una volta che avrai legato il tuo destino agli elementi, non potrai più voltare loro le spalle. Portami la prova che ne sei <degno/degna>, e cominceremo.", "Hai fatto la tua scelta, e gli elementi ti accolgono. Quando avrò completato il tuo tirocinio, avrai la volontà necessaria per creare i più pregiati indumenti di cuoio.\n\nPer addestrarti in quest'arte in futuro, ti basterà parlare con me e ti metterò a disposizione tutte le conoscenze che non hai ancora fatto tue.", 0x9503323d, 0x2ac5b0e7, 0xd87a1461, 0xae7f88b1, 0xe07be135, "....." },
  [5145] = { "⟦Dragonscale Leatherworking=Conciatura delle Scaglie di Drago⟧", "Porta 2 Pettorale Corazzato di ⟦Scorpid=Scorpide⟧ Indurito, 2 ⟦Tough Scorpid Gloves=Guanti di Scorpide Induriti⟧ e 10 Scaglie di Drago Consumate a Thorkaf Dragoneye nelle ⟦Badlands=Maleterre⟧.\n\nCompletando questa missione avrai accesso all'arte della ⟦Dragonscale Leatherworking=Conciatura delle Scaglie di Drago⟧.\n\nCompletare questa missione ti impedirà di imparare la ⟦Elemental Leatherworking=Conciatura Elementale⟧ e la ⟦Tribal Leatherworking=Conciatura Tribale⟧; assicurati che sia questa la strada che vuoi seguire prima di farlo.", "La Conciatura delle Scaglie di Drago non è facile, ma dà enormi soddisfazioni. Ti insegnerò a realizzare queste pregiate armature di maglia, ma solo se accetti certe condizioni.\n\nScegliendo questa strada, accetti di non imparare mai la Conciatura Elementale o quella Tribale: al vertice del mestiere c'è posto per una sola delle tre. Inoltre, mi servono alcuni esemplari del tuo miglior lavoro con le armature di scorpide. Infine, mi serve la prova che sai procurarti la materia prima del mestiere: le scaglie dei dragoidi.", "Se sei <pronto/pronta> a prendere una decisione definitiva e diventare <un/una> <conciatore/conciatrice> di scaglie di drago, io sono pronto a prenderti come <allievo/allieva>. Portami ciò che ti ho chiesto e cominceremo la tua formazione.", "Te lo concedo: ci vuole una volontà forte per prendere una decisione definitiva come quella che hai appena preso. Ti assicuro che la Conciatura delle Scaglie di Drago si rivelerà una strada redditizia e gratificante.\n\nPer addestrarti in quest'arte in futuro, ti basterà parlare con me e ti metterò a disposizione tutte le conoscenze che non hai ancora fatto tue.", 0x2bc93035, 0x335fe73f, 0x7a9a3232, 0x250fb4b6, 0x4027ea2b, "....." },
  [5146] = { "⟦Elemental Leatherworking=Conciatura Elementale⟧", "Porta 2 ⟦Heart of Fire=Cuore di Fuoco⟧, 2 ⟦Globe of Water=Globo d'Acqua⟧, 2 ⟦Core of Earth=Nucleo di Terra⟧ e 2 ⟦Breath of Wind=Soffio di Vento⟧ a Brumn Winterhoof sui monti d'Arathi.\n\nCompletando questa missione avrai accesso all'arte della ⟦Elemental Leatherworking=Conciatura Elementale⟧.\n\nCompletare questa missione ti impedirà di imparare la ⟦Dragonscale Leatherworking=Conciatura delle Scaglie di Drago⟧ e la ⟦Tribal Leatherworking=Conciatura Tribale⟧; assicurati che sia questa la strada che vuoi seguire prima di farlo.", "La Conciatura Elementale è ciò che conosco, e se sei <disposto/disposta> ad aprire la mente ai poteri superiori della materia, condividerò con te tutto ciò che c'è da imparare.\n\nSappi questo, {class}: scegliendo questa strada accetti di non imparare mai la Conciatura delle Scaglie di Drago o quella Tribale; c'è posto per praticare una sola delle tre arti. Inoltre, mi serve una prova adeguata che sei in sintonia con gli elementi della natura; a tal fine, portami le essenze più pure di fuoco, acqua, terra e vento.", "Realizzare questo tipo di armature di cuoio richiede pazienza e dedizione. Una volta che avrai legato il tuo destino agli elementi, non potrai più voltare loro le spalle. Portami la prova che ne sei <degno/degna>, e cominceremo.", "Hai fatto la tua scelta, e gli elementi ti accolgono. Quando avrò completato il tuo tirocinio, avrai la volontà necessaria per creare i più pregiati indumenti di cuoio.\n\nPer addestrarti in quest'arte in futuro, ti basterà parlare con me e ti metterò a disposizione tutte le conoscenze che non hai ancora fatto tue.", 0x9503323d, 0x631d83fb, 0xd87a1461, 0xae7f88b1, 0xe07be135, "....." },
  [5147] = { "RICERCATO: Arnak Grimtotem", "Uccidi Arnak Grimtotem e porta la prova della tua impresa al guardiacolli Longhorn al ⟦Freewind Post=Presidio di Ventolibero⟧.", "Ricercato: Arnak Grimtotem\n\nArnak l'esiliato è ricercato per gli atroci crimini di omicidio e rapimento. Lauti compensi andranno a chi avrà il coraggio di assicurare questo criminale alla giustizia.\n\nArnak è stato visto l'ultima volta sulle rupi vicino al ⟦Darkcloud Pinnacle=Pinnacolo Nubenera⟧. Mostra la prova della tua impresa al guardiacolli Longhorn, al ⟦Freewind Post=Presidio di Ventolibero⟧, per riscuotere la ricompensa.", "Hai notizie di quell'assassino di Arnak Grimtotem?", "Ah! Be', questa è un'ottima notizia! Cominciavo a pensare che non sarebbe mai stato assicurato alla giustizia!\n\nEccoti, {name}... e grazie. Le notizie dei crimini infami di Arnak mi facevano ribollire il sangue!", 0x975f70b8, 0x910d7242, 0x50ebc814, 0x12fd03ba, 0xf92279b7, "....." },
  [5148] = { "⟦Tribal Leatherworking=Conciatura Tribale⟧", "Porta una ⟦Wild Leather Vest=Veste di Cuoio Selvatico⟧ e un ⟦Wild Leather Helmet=Elmetto di Cuoio Selvatico⟧ a Se'Jib nella Valle di Rovotorto.\n\nCompletando questa missione avrai accesso all'arte della ⟦Tribal Leatherworking=Conciatura Tribale⟧.\n\nCompletare questa missione ti impedirà di imparare la ⟦Dragonscale Leatherworking=Conciatura delle Scaglie di Drago⟧ e la ⟦Elemental Leatherworking=Conciatura Elementale⟧; assicurati che sia questa la strada che vuoi seguire prima di farlo.", "Imparare la Conciatura Tribale richiede di comprendere quanto sia davvero primordiale la natura; so che padroneggi già l'arte di creare armature di cuoio selvatico, e intendo completare il tuo addestramento.\n\nSappi questo, {class}: scegliendo questa strada accetti di non imparare mai la Conciatura delle Scaglie di Drago o quella Elementale; c'è posto per praticare una sola delle tre arti. Inoltre, portami i migliori esemplari delle tue armature di cuoio selvatico. Da lì inizieremo il tuo cammino verso la maestria.", "La natura è una forza che va placata prima che tu possa sperare di imparare a piegarne la volontà nei tuoi indumenti di cuoio. Portami la tua offerta a questa forza, e farò in modo che la tua voce venga ascoltata.", "Hai offerto i tuoi doni migliori, e presto la natura ti permetterà di piegarla alla tua volontà. Quando avrò completato il tuo tirocinio, il tuo lavoro sarà una forza della natura a sé stante.\n\nPer addestrarti in quest'arte in futuro, ti basterà parlare con me e ti metterò a disposizione tutte le conoscenze che non hai ancora fatto tue.", 0x6f10746f, 0x3cd2784c, 0xeb474bee, 0xb22401c2, 0x4cce757a, "....." },
  [5149] = { "La ⟦Pamela's Doll=Bambola di Pamela⟧", "Trova la Bambola di Pamela.", "La zia Marlene mi ha detto di restare qui a casa nostra perché il mio papà doveva andare a combattere. Il mio papà è l'uomo più coraggioso del mondo intero!\n\nMa sono qui da tanto tempo, e lui non è venuto a prendermi. A volte vengono delle persone cattive che mi sussurrano cose, e io voglio che il mio papà le mandi via, ma lui non c'è!\n\nE a volte, quando fa buio, voglio giocare con la mia bambola, ma non posso perché l'ho lasciata in paese.\n\nMe la trovi tu, la mia bambola?", "Hai trovato la mia bambola?", "L'hai trovata! Hai trovato la mia bambola! Oh, grazie!", 0xc2bf6af3, 0x7119b829, 0xde335067, 0x1cbf400c, 0x7bcdc282, "....." },
  [5151] = { "⟦Hypercapacitor Gizmo=Ingranaggio Ipercapacitante⟧", "Uccidi la belva e riporta l'⟦Hypercapacitor Gizmo=Ingranaggio Ipercapacitante⟧ e la ⟦Panther Cage Key=Chiave della Gabbia della Pantera⟧ a Wizlo Bearingshiner.", "Sono l'unico sopravvissuto all'attacco dei centauri alla nostra carovana! Una pantera rara ma possente fa la guardia al mio ingranaggio migliore, che porta appeso al collo. Ah! Persino i centauri tremano davanti a quella belva feroce!\n\nEcco la chiave della gabbia. Lì si sono presi tutto, ma lei l'hanno lasciata stare. Uccidi quella belva e riportami il mio ipercapacitore, e ti ricompenserò.\n\nLa carovana distrutta è appena a nord di qui.", "Hai il mio ipercapacitore?", "Il mio ipercapacitore! Mi terrà occupato per un bel po', finché non avrò capito a cosa serve...", 0x0f8bf73d, 0x8b6a9674, 0xdeb68b59, 0xaf2e4c2b, 0xa40857a1, "....." },
  [5152] = { "Zia Marlene", "Parla con Marlene, a sud delle rovine di Andorhal.", "Oh, mi sento così sola! Dov'è la mia famiglia? Zia Marlene mi ha detto di restare qui, ma poi se n'è andata e non è più tornata! E il mio papà... l'hai visto?\n\nForse zia Marlene sa dov'è. Vive vicino ad Andorhal, in una casa a sud. Mi pare che fosse su una collina... ha detto che era su una collina.\n\nTi prego, {name}. Sei <il/la> mi<o/a> nuov<o/a> amic<o/a>! Parleresti con mia zia per me?", nil, "Hai visto Pamela? Come sta? È viva?? Oh, no! Povera Pamela! Era così giovane, una bambina così felice...\n\nNon sa cosa sia successo a suo padre, vero? Mio fratello, Joseph?\n\nNo... non potrebbe capire cosa è successo a Joseph. E anche se potesse, non ho il coraggio di dirglielo...", 0xbf32e4a8, 0x02c7f350, 0x681a5775, nil, 0x73074fb9, "...m." },
  [5153] = { "Una strana storica", "Porta la ⟦Joseph's Wedding Ring=Fede Nuziale di Joseph⟧ a Chromie.", "Vorrei che Joseph potesse tornare con sua figlia, ma non può essere. La sua anima è stata distorta dal Flagello ed è diventato un mostro. Oh, è condannato!\n\nMa forse possiamo cambiare il suo destino.\n\nCerca il monumento di Joseph tra le tombe qui fuori. Il suo corpo non c'è, perché anni fa fu calpestato e distrutto, ma sotto il monumento c'è la sua fede nuziale. Porta quell'anello a Chromie... una strana gnoma con strani poteri.\n\nChromie si trova nella locanda in rovina, nell'angolo nord-occidentale di Andorhal.", "La tua visita ha qualcosa di tempestivo. Non vieni dal futuro, vero?", "Che cos'è? Una fede nuziale? Fammi vedere...\n\nAh! Questo anello un tempo era al dito di un grand'uomo, ma nel passato di quell'uomo c'è molta tragedia.\n\nSei qui per aiutarlo? Ormai per lui è troppo tardi... ma forse possiamo aiutarlo nel passato!", 0xcb8b9956, 0xe21c496d, 0x436bc567, 0x382329e8, 0x490fbfd0, "....." },
  [5154] = { "Gli ⟦Annals of Darrowshire=Annali del Borgo di Darrow⟧", "Porta gli ⟦Annals of Darrowshire=Annali del Borgo di Darrow⟧ a Chromie, ad Andorhal.", "Per salvare Joseph Redpath dobbiamo prima scoprire il suo passato. Possiamo farlo con gli ⟦Annals of Darrowshire=Annali del Borgo di Darrow⟧, un libro custodito nel municipio di Andorhal.\n\nPortami quel libro. Così potremo conoscere il destino di Joseph e, con un po' di fortuna... cambiarlo!", "Hai trovato il libro, {name}?", "Ben fatto, l'hai trovato!\n\nL'hai letto? Si parla di Joseph Redpath? Se sì, forse possiamo salvarlo!\n\nAh. Gli ⟦Annals of Darrowshire=Annali del Borgo di Darrow⟧ raccontano una storia molto inquietante. Dicono che durante la battaglia Joseph Redpath fu corrotto e si unì alle file del Flagello! Poi tradì i difensori del ⟦Darrowshire=Borgo di Darrow⟧.\n\nÈ un destino crudele. Se possiamo, dovremmo cercare di cambiarlo, non credi?", 0xe83edb2f, 0x08fe7e5b, 0xed3cf36e, 0xfe172e90, 0x64d242ef, "....." },
  [5155] = { "Le forze di Jaedenar", "Entra a Jaedenar e uccidi 4 Jaedenar Hound, 4 Jaedenar Guardsman, 6 Jaedenar Adept e 6 Jaedenar Cultist, poi torna da Greta Mosshoof nel ⟦Felwood=Vilbosco⟧.", "Se devo fidarmi di te in questa faccenda, prima dovrai dimostrare il tuo valore.\n\nDevo sapere che sei nemic<o/a> del ⟦Shadow Council=Concilio dell'Ombra⟧, i responsabili di molti mali, qui e altrove.\n\nAddentrati nel ⟦Felwood=Vilbosco⟧. A ovest vedrai un sentiero che porta a Jaedenar. È lì che il Concilio trama con la Legione Infuocata.\n\nScendi nelle profondità di uno degli eremi corrotti che occupano e uccidi quelli della loro specie. Torna da me quando l'avrai fatto. Allora saprò che vuoi davvero aiutarci.", "Come procede la tua battaglia, {name}? So che versare sangue come prova d'onore può disgustare qualcuno, ma devi capire che serve a due scopi: mi rendi il compito più facile riducendo il loro numero, e noi due guadagniamo un rispetto reciproco che non potrà che renderci più forti nei tempi a venire.\n\nSpero che tu capisca.", "Bene, {name}! Con il loro numero in calo, possiamo incalzarli ancora di più.\n\nCom'è stato il tuo primo assaggio del loro potere? Erano forti come pensavi? Di più? O forse non sono stati affatto un problema per te. Non sarebbe straordinario?\n\nParleremo più avanti dei dettagli delle tue imprese. Ora dobbiamo concentrarci su altro.", 0x8fc92571, 0x42e95290, 0x5050219c, 0x35903617, 0x70ed3eba, "....." },
  [5156] = { "Verificare la corruzione", "Cerca e distruggi 2 Entropic Beast e 2 Entropic Horror mentre esplori la ⟦Shatter Scar Vale=Valle dei Crateri Infernali⟧. Dopo aver controllato se i crateri sono ancora pieni d'acqua vil corrotta, torna da Taronn Redfeather nel ⟦Felwood=Vilbosco⟧.", "A nord, lungo il lato orientale della strada, nella zona chiamata ⟦Shatter Scar Vale=Valle dei Crateri Infernali⟧, c'è un'area dove durante l'ultima grande guerra furono fatti piovere gli infernali: i crateri sfregiano ancora la terra, come gli infernali stessi.\n\nSono curioso di due cose. Primo: ci sono ancora elementali entropici che vagano nella zona? E secondo: i crateri sono ancora pieni dell'acqua corrotta e fetida che vi si è raccolta anni fa? Mi aiuterai a controllare, {name}? Ma fa' attenzione: gli infernali distruggono qualsiasi cosa si trovi sul loro cammino.", "Spero che la tua ricerca vada bene, {name}. Non mi sono ancora spinto così a nord ma, lo ammetto, l'idea di incrociare un infernale, prima o poi, mi spaventa un pochino. Sono creature senza cervello, ma comunque piuttosto minacciose.", "Bene che tu sia viv<o/a>, {name}. Male che l'acqua ci sia ancora. Speravo di trovare almeno una fonte d'acqua pura qui nel ⟦Felwood=Vilbosco⟧. Sembra che la mia ricerca sia fallita. Con quella fonte il processo di guarigione della terra sarebbe stato molto più facile.\n\nDovrò occuparmi di salvare le creature della foresta che posso, distruggendo invece quelle così corrotte da essere un pericolo per sé stesse quanto per chi viaggia in questa foresta un tempo possente.", 0x707d2810, 0x78c00251, 0xa6862cb5, 0x78297b9e, 0xbbd1d03a, "....." },
  [5157] = { "Raccolta dell'acqua corrotta", "Porta la ⟦Empty Canteen=Borraccia Vuota⟧ al Pozzo Lunare al centro di Jaedenar e riempila, poi torna da Greta Mosshoof a ⟦Felwood=Vilbosco⟧.", "Nel cuore di Jaedenar si trova l'⟦Shadow Hold=Eremo delle Ombre⟧, la fortezza principale della loro corruzione e malvagità.\n\nIl ⟦Shadow Council=Concilio dell'Ombra⟧ protegge il suo covo con incantesimi sotto forma di bracieri. Se voglio scoprire altro sul nostro nemico attraverso la divinazione, quei bracieri vanno spenti. Così dovrei riuscire a spiare il Concilio e scoprire chi lo guida.\n\nSe puoi, prendi questa borraccia e riempila al Pozzo Lunare al centro di Jaedenar. Poi torna da me.", "Una volta che avremo l'acqua del Pozzo Lunare, la purificheremo e la useremo per spegnere i bracieri di protezione nell'⟦Shadow Hold=Eremo delle Ombre⟧. Così dovrei avere tutto il tempo per vedere nelle stanze più profonde e scoprire chi guida davvero questo... culto.\n\nPrego che la Madre Terra sia con noi.", "Questo andrà benissimo, {name}.\n\nOra, oltre a versare l'acqua sui bracieri, dobbiamo soltanto farla purificare. Non dovrebbe essere difficile: basterà un piccolo viaggio.\n\nSpero che riusciremo a farlo in fretta.", 0x72751fe0, 0xd3f452ab, 0xf7284a6b, 0x73064c54, 0xb56d1812, "....." },
  [5158] = { "In cerca di aiuto spirituale", "Porta l'Acqua del Pozzo Lunare Corrotto a Islen Waterseer nelle ⟦Barrens=Savane⟧.", "Porta l'acqua corrotta nelle ⟦Barrens=Savane⟧, {name}. A sud di ⟦Ratchet=Porto Paranco⟧, nascosta lungo la riva, c'è una mia vecchia amica, una sciamana di nome Islen Waterseer. È una sciamana potente e ci aiuterà. Il suo legame con gli spiriti dell'acqua è sempre stato forte. La nobiltà del nostro compito dovrebbe bastare a convincere lei e gli spiriti dell'acqua ad aiutarci in questa impresa.\n\nDovresti trovarla in un piccolo accampamento proprio in riva all'acqua. E, {name}, ignora i pirati... sono solo una seccatura, non una minaccia per te.", "Sento che non sei <un/una> semplice viaggiat<ore/rice> in cerca della strada per ⟦Ratchet=Porto Paranco⟧. Vieni, siediti e riposa nel nostro accampamento. Parlami quando sei pront<o/a>.", "Ah, ti serve che l'acqua di questo Pozzo Lunare venga purificata. Fermare questa forza maligna a ⟦Felwood=Vilbosco⟧ sembra abbastanza nobile, ma non spetta a me decidere se l'acqua sarà purificata. Chiederò agli spiriti dell'acqua: starà a loro decidere se la causa è giusta.\n\nDammi un momento e riferirò loro la tua richiesta. Spero che siano ben disposti verso la tua causa quanto lo sono io.", 0xe9c94673, 0x8c1ae134, 0x8c67b7e1, 0xeaaeba42, 0x805dd0cc, "....." },
  [5159] = { "L'acqua purificata torna nel ⟦Felwood=Vilbosco⟧", "Porta l'Acqua del Pozzo Lunare Purificata a Greta Mosshoof nel ⟦Felwood=Vilbosco⟧.", "Ringrazia gli spiriti, {name}. Sono loro ad averti aiutato, non io.\n\nOra ti consegno quest'acqua purificata. Ti prego, porta a Greta i miei saluti e i miei migliori auguri. Sta affrontando qualcosa di più grande di molti di noi... come sono certa scoprirà presto.\n\nIl ⟦Shadow Council=Concilio dell'Ombra⟧ non è una forza da prendere alla leggera, {name}. Ricordalo.\n\nOra va'. Prendi l'acqua e torna da Greta.", "Ah, vedo che sei <tornato/tornata>, {name}. Bene. Hai trovato Islen nelle ⟦Barrens=Savane⟧? O dobbiamo trovare un altro modo per raggiungere i nostri scopi?", "Quest'acqua dovrebbe essere più che sufficiente per i nostri scopi.\n\nSono lieta di sapere che Islen è riuscita ad aiutarci. Il suo legame con gli spiriti dell'acqua è sempre stato forte. È anche saggia, ed è raro che gli spiriti non condividano il suo scopo. Il fatto che entrambi abbiano benedetto il nostro compito mi fa sperare che siamo sulla strada giusta.", 0x51c0ce90, 0xf96df8a9, 0x913e20cc, 0xecbf45be, 0xe41510cb, "....." },
  [5160] = { "La matrona protettrice", "Raggiungi ⟦Winterspring=Fontefredda⟧ e trova Haleh. Consegnale la scaglia di Awbee.", "Raggiungi Kalimdor, {race}. Il nostro stormo dimora nelle terre gelide di ⟦Winterspring=Fontefredda⟧. Una volta a ⟦Winterspring=Fontefredda⟧, trova le grotte di Mazthoril.\n\nSui pavimenti ghiacciati di Mazthoril troverai delle rune color cobalto. Tieni in mano una delle mie scaglie e mettiti su una runa: verrai trasportat<o/a> da Haleh, la nostra matrona protettrice.\n\nDalle la scaglia, così che possa scrutare ciò che ho visto e sentito qui, in questo luogo condannato.", "È bello vederti, {name}.", "Gli Aspetti insistono che restiamo fuori dalle faccende dei mortali. In questo mondo, però, non sempre è possibile, soprattutto quando uno dei nostri ignora con disprezzo tali editti.", 0xc391bb7b, 0xa5a91318, 0x9355b076, 0x4cfaa283, 0x8f52e29c, "....." },
  [5161] = { "L'ira dello Stormo dei Draghi Blu", "Parla con Haleh se vuoi proseguire.", "Sappiamo cosa cerca di fare la stirpe maledetta di Alamorte e sappiamo che non può essere permesso.\n\nA causa della protezione che il Massiccio ⟦Blackrock=Roccianera⟧ offre a Nefarian, per noi è diventato sempre più difficile intervenire.\n\nPossiamo però darti potere, mortale, se così sceglierai.\n\nIl cammino che hai davanti è pieno di pericoli. Devi decidere se accettare il nostro aiuto. Riflettici e torna a parlarmi quando avrai preso una decisione.", nil, "Così sia...", 0x26fdd8bc, 0xf97c753c, 0x6f38ba43, nil, 0x85bcef4f, "...m." },
  [5162] = { "L'ira dello Stormo dei Draghi Blu", "Parla con Jeziba nelle ⟦Plaguelands=Terre Infette⟧. Risiede ad Andorhal.", "È l'arcano che io controllo, ed è l'arcano che ti manderà alla tua prossima destinazione.\n\nQuando sarai pront<o/a>, il viaggio avrà inizio. Andrai nelle ⟦Plaguelands=Terre Infette⟧ e parlerai con Jeziba.\n\nÈ un mortale saggio come gli antichi e paziente come la terra immobile. Lo troverai ad Andorhal.", nil, "Sono Jeziba, che molti conoscono come lo Scultore. Ciò che scolpisco, però, non sono statue, ma eroi.", 0x26fdd8bc, 0x635a993b, 0x620414b2, nil, 0xc438fdd0, "...m." },
  [5163] = { "Ci siamo, yeti?", "Prendi lo ⟦Umi's Mechanical Yeti=Yeti Meccanico di Umi⟧ e spaventa i suoi amici:\n\nLegacki a ⟦Everlook=Lungavista⟧ (⟦Winterspring=Fontefredda⟧)\n\nSprinkle a ⟦Gadgetzan=Meccania⟧ (Tanaris)\n\nQuixxil al ⟦Marshal's Refuge=Rifugio dei Grant⟧ (⟦Un'Goro Crater=Cratere di Un'Goro⟧)\n\nQuando hai finito, riporta lo ⟦Mechanical Yeti=Yeti Meccanico⟧ a Umi.", "È tutto pronto, {name}!\n\nHo già mandato una lettera ai miei amici per dire che ho una sorpresa per loro. Ed è qui che entri in gioco tu!\n\nTi darò il mio yeti meccanico: devi fare una sorpresa a ciascuno dei miei amici andandolo a trovare, accendendo lo yeti e mandandoglielo contro.\n\nQuando l'avrai mostrato a Legacki a ⟦Everlook=Lungavista⟧, a Sprinkle a ⟦Gadgetzan=Meccania⟧ e a Quixxil al ⟦Marshal's Refuge=Rifugio dei Grant⟧, torna a raccontarmi cos'è successo!\n\nE poi riportami anche il mio yeti, per favore.", "Non vedo l'ora di sapere come reagiscono i miei amici!\n\nNon se lo aspetteranno mai!", "Ah! Ci penseranno due volte prima di prendere di nuovo in giro le mie idee!\n\nGrazie dell'aiuto, {name}. Senza di te non mi sarei divertita così tanto!", 0xf5c82ef5, 0x5e7ceae9, 0xf9385400, 0x20cadf74, 0xe542ccd4, "....." },
  [5164] = { nil, "Leggi dal Catalogue of the Wayward.", "Haleh non avrebbe potuto scegliere uno strumento di giustizia migliore. Leggi dal Catalogue of the Wayward e sarai illuminat<o/a>.\n\nSe perseverai... se farai ciò che ti viene chiesto... se sopravvivrai... entrerai nella schiera degli eroi.", nil, "Centinaia e centinaia di pagine fitte di testo e simboli incomprensibili costituiscono il grosso di questo libro.", 0xed554449, 0x2a99d9b1, 0x5299594c, nil, 0x7082f4ba, "e..m." },
  [5165] = { "Spegnere le fiamme della protezione", "Usando l'Acqua del Pozzo Lunare Purificata, spegni le fiamme dei quattro bracieri della protezione nell'⟦Shadow Hold=Eremo delle Ombre⟧, a ⟦Felwood=Vilbosco⟧, poi torna da Greta Mosshoof al ⟦Emerald Sanctuary=Santuario di Smeraldo⟧.", "Ora devi tornare a Jaedenar. Con ogni probabilità i bracieri sono sparsi per tutto l'⟦Shadow Hold=Eremo delle Ombre⟧. Spegni le loro fiamme una per una e le protezioni erette dal Concilio cadranno, almeno per un breve periodo. Io aspetterò che accada. Quando succederà, scruterò nel profondo dell'Eremo e cercherò di scoprire chi è la testa di questa bestia. Allora, e solo allora, penseremo ad attaccarli direttamente.", "I bracieri vanno spenti, se vogliamo avere qualche speranza di prepararci a una battaglia ben più grande. Entrare nella tana del drago senza sapere nulla è un'impresa da folli. E questo è molto peggio di un drago. Il ⟦Shadow Council=Concilio dell'Ombra⟧ è l'unico responsabile di un gran numero di crimini e atrocità. Dovremo agire in fretta, se vogliamo fermarli.", "Sono riuscita a vederti con i miei incantesimi appena si sono spente le fiamme dell'ultimo braciere. Ben fatto, {name}.\n\nHo scoperto alcune cose prima che gli stregoni del Concilio dell'Ombra riuscissero a lanciare di nuovo i loro incantesimi. Spero che basti.\n\nPer ora riposa. Tra un momento ti dirò cosa ho scoperto.", 0x060d8cde, 0x01b6e1bb, 0x34b77fa3, 0x0ddbd317, 0xb0dbc7d6, "....." },
  [5166] = { nil, "Per forgiare il Breastplate of the Chromatic Flight dovrai portare i seguenti oggetti a Jeziba lo 'Scultore':\n\n1 Chromatic Carapace.\n\n10 Scaglia Cromatica Brillante.\n\n10 ⟦Blood of Heroes=Sangue degli Eroi⟧.\n\n10 Pezze Consumate dell'Abominio.", "Forgiare un pettorale potente che protegga dagli attacchi incessanti dello stormo cromatico è un'impresa che poggia sull'ironia.\n\nLe scaglie delle stesse bestie che combattiamo vanno cucite sul carapace intatto di un antico draco o drago cromatico. Al momento non se ne conosce nessuno, e dobbiamo sperare che non ne esista mai nessuno.\n\nInfine, forse il più difficile di tutti i componenti: il Sangue degli Eroi.\n\nSarà lo Scultore, alla fine, a forgiare questa creazione.", "Hai scelto saggiamente, {race}.", "Non hai ancora capito? Il viaggio era la meta. Non senti le cicatrici della battaglia? Il dolore che hai patito?\n\nAvendo superato la prova, sei un essere più potente. Molto più potente. Questo pettorale è solo un riflesso delle tue capacità innate.", 0xa124a904, 0xc606abe5, 0xb7d99786, 0x1fc489bf, 0xa4e224c5, "e...." },
  [5167] = { nil, "Per forgiare i Legplates of the Chromatic Defier dovrai portare i seguenti oggetti a Jeziba lo 'Scultore':\n\n1 Chromatic Carapace.\n\n10 Scaglia Cromatica Brillante.\n\n10 ⟦Blood of Heroes=Sangue degli Eroi⟧.\n\n5 ⟦Skin of Shadow=Pelle dell'Ombra⟧.", "Il carapace di un draco cromatico adulto serve a formare la base dei gambali. Sul telaio di filo si stratificano poi le scaglie cromatiche brillanti, incantate nel Sangue degli Eroi. Infine, la morbida Pelle dell'Ombra va applicata all'interno degli schinieri.", "Un oggetto simile non è mai stato forgiato!", "Fiuteranno l'odore dei loro simili quando entrerai nelle loro sale, {name}. Schiacciali con la loro stessa paura!", 0x616f9739, 0x5d1142af, 0x5608021e, 0x59f95cf3, 0x8e19a64b, "e...." },
  [5168] = { "Gli eroi del ⟦Darrowshire=Borgo di Darrow⟧", "Porta il ⟦Davil's Libram=Libro di Davil⟧ e lo ⟦Redpath's Shield=Scudo di Tracciarossa⟧ a Carlin Redpath.", "Gli eroi del ⟦Darrowshire=Borgo di Darrow⟧ mi stanno a cuore, e il libro che mi hai portato, gli ⟦Annals of Darrowshire=Annali del Borgo di Darrow⟧, narra le loro storie.\n\nParla del paladino Davil Lightfire e di come la Crociata portò il suo libro al municipio di ⟦Hearthglen=Valsalda⟧.\n\nI suoi passi parlano anche di mio fratello, il capitano Redpath. Dopo il suo tradimento, il suo scudo fu spezzato e gettato via, e ora giace nel posto più impensabile: vicino al fienile del ⟦Gahrron's Withering=Podere di Gahrron⟧.\n\nRaccogli queste reliquie, {name}. Il destino e la tragedia le avvolgono.", "Hai le reliquie, {name}?", "Hai il libro e lo scudo!\n\nLa loro storia è intrecciata con quella del ⟦Darrowshire=Borgo di Darrow⟧ e, in qualche modo, so che il destino li riunirà di nuovo.", 0xb9a8852f, 0x624d91d0, 0x720e7acf, 0x8fc0ba94, 0xa04658d6, "....." },
  [5181] = { "I malvagi del ⟦Darrowshire=Borgo di Darrow⟧", "Porta il ⟦Skull of Horgus=Teschio di Horgus⟧ e la ⟦Shattered Sword of Marduk=Spada Infranta di Marduk⟧ a Carlin Redpath, alla ⟦Light's Hope Chapel=Cappella della Luce⟧.", "Gli ⟦Annals of Darrowshire=Annali del Borgo di Darrow⟧ parlano dei malvagi di quella battaglia. Narrano di come il signore dei ghoul Horgus il Devastatore fu distrutto dalle forze dell'⟦Alliance=Alleanza⟧ durante lo scontro. Il suo corpo fu gettato in un lago a nord-ovest del ⟦Corin's Crossing=Crocevia di Corin⟧, e il suo teschio è ancora lì.\n\nMarduk Pozzanera non fu mai sconfitto, ma la sua leggendaria spada andò in frantumi e fu perduta. Giace sul fondo della gola a ovest del ⟦Corin's Crossing=Crocevia di Corin⟧.\n\nRecupera questi oggetti, {name}. Non so perché, ma sono certo che il loro destino sia legato a te.", "Hai trovato il teschio e la spada, {name}?", "Li hai trovati! Ben fatto, {name}! Queste reliquie racchiudono un potere che non comprendo del tutto, un potere che un giorno saprai domare.\n\nMi riportano anche alla mente ricordi oscuri, ricordi di morte e tradimento, e dell'ultima notte del ⟦Darrowshire=Borgo di Darrow⟧...", 0xee997fcd, 0xe2e47744, 0x3c5af42a, 0x85a8ad4c, 0xd32ff9c9, "....." },
  [5202] = { "Una strana chiave rossa", "Esplora Jaedenar per scoprire a cosa serve la Blood Red Key.", "La piccola chiave rossa sembra fatta di una specie di materiale osseo. È pesante in mano, ma pare molto fragile. Perché mai un membro del ⟦Shadow Council=Concilio dell'Ombra⟧ dovrebbe avere una cosa del genere? Forse a Jaedenar c'è qualcosa che questa strana chiave può aprire.", "Comincio a chiedermi se uscirò mai da questa gabbia.\n\nÈ solo questione di tempo prima che mi sacrifichino a qualunque demone adorino. Mostri!", "La chiave, l'hai trovata! Ti prego, dammela e finalmente potrò fuggire!", 0x991b63d4, 0x45dab60d, 0x9b7ac879, 0x4cef28eb, 0xd6c7cd3e, "....." },
  [5203] = { "Salvataggio da Jaedenar", "Scorta Arko'narin fino al luogo in cui sono custoditi Lightforge e il suo equipaggiamento, poi proteggila mentre fuggite dall'⟦Shadow Hold=Eremo delle Ombre⟧. Dopodiché cerca Jessir Moonbow a ⟦Felwood=Vilbosco⟧ per raccontarle cos'è successo ai suoi amici.", "Ma, per quanto mi addolori, c'è una cosa da fare prima di tutto: devo trovare Lightforge, la spada di Trey, e fuggire dall'⟦Shadow Hold=Eremo delle Ombre⟧ per riferire ai miei superiori cosa sta succedendo qui. Puoi aiutarmi, {name}?\n\nIl nostro equipaggiamento non è lontano da qui, e hai già dimostrato di saper sopravvivere al percorso fino in cima.\n\nDopo la fuga andrò a Darnassus, se tu riesci a trovare la mia amica Jessir vicino al confine di ⟦Ashenvale=Valtetra⟧. Doveva incontrarci all'accampamento della Fede di Smeraldo, lì vicino.\n\nChe ne dici, {name}? Puoi aiutarmi ancora una volta?", "Hai il fiato corto, {name}. Stai bene, o c'è qualcosa che non va?", "Sei tu che hai aiutato Arko a fuggire? Sono così contenta che tu mi abbia trovata. È passata di qui non molto tempo fa, diretta a Darnassus. Aveva con sé Lightforge e non si è nemmeno fermata a farsi curare dai druidi. Ha detto che era troppo urgente.\n\nPerò mi ha raccontato del tuo incontro con lo spirito di Trey. Che destino terribile per un Cavaliere della ⟦Silver Hand=Mano d'Argento⟧. Non l'ha dato a vedere, ma so che il pensiero di aver perso uno dei suoi amici più cari la sta logorando dentro.", 0x21b3f3ee, 0xee60e3b9, 0xb7e1dfa0, 0x12c1ee3b, 0x018e6027, "....." },
  [5204] = { "Il castigo della Luce", "Torna a Jaedenar e uccidi la succube Rakaiah prima di cercare i ⟦Remains of Trey Lightforge=Resti di Trey Forgialuce⟧.", "Vorrebbe far finta di stare bene. Le piacerebbe farmi credere di essere abbastanza forte da affrontare tutto questo da sola, ma io so come stanno le cose. La morte di Trey e il racconto delle torture che ha subito la tormenteranno a lungo, e non possiamo farci niente. Però possiamo darle un po' di pace!\n\n{name}, torna all'⟦Shadow Hold=Eremo delle Ombre⟧, uccidi l'aguzzino di Trey e trova i suoi resti. Non c'è motivo per non chiudere tutte queste questioni in sospeso mentre Arko'narin piange a modo suo.", "Esamini il corpo e non c'è alcun dubbio: questi sono i resti del Cavaliere della ⟦Silver Hand=Mano d'Argento⟧ Trey Lightforge. Per un attimo pensi ad Arko'narin e ti chiedi se nella tua vita qualcuno abbia mai contato per te quanto quest'uomo contava per la prigioniera Elfa della Notte che hai appena aiutato a fuggire dall'⟦Shadow Hold=Eremo delle Ombre⟧.\n\nDopo esserti pres<o/a> un altro momento per raccogliere i pensieri, sai che non puoi riportare i resti del paladino a Jessir senza prima uccidere il suo aguzzino.", "Raccogli i resti del paladino con tutta la cura possibile, pensando che almeno il suo spirito è stato liberato da ogni dolore o sofferenza che possa avergli inflitto.", 0xc22d8991, 0x11a66fd0, 0xcb462280, 0x05b3f9be, 0x7b290b2e, "....." },
  [5206] = { "I predoni del ⟦Darrowshire=Borgo di Darrow⟧", "Porta 5 Teschio Echeggiante e il ⟦Mystic Crystal=Cristallo Mistico⟧ a Carlin Redpath, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧.", "Chromie ha detto che le reliquie che hai raccolto sono reagenti per un potente incantesimo, e ne serve ancora uno: i teschi dei membri del Flagello che presero parte alla battaglia del ⟦Darrowshire=Borgo di Darrow⟧.\n\nPrendi questo cristallo e dai la caccia ai campioni del Flagello per prenderne i teschi. Il cristallo è incantato: se un campione ha preso parte alla battaglia, quando passerai il cristallo sopra il suo teschio, questo risuonerà. Portami quei teschi echeggianti.\n\nVa', {name}. Troverai i campioni del Flagello nella Radura Venefica, a nord, e a Valfungosa, a ovest.", "Hai i teschi? Chromie ha detto che saranno fondamentali per il suo incantesimo, e quell'incantesimo ci darà la possibilità di salvare il ⟦Darrowshire=Borgo di Darrow⟧.", "Li hai trovati! Magnifico!\n\nAnche se non capisco del tutto come possano aiutarci, sento il loro potere e so nelle ossa che sono legati al mio villaggio natale, il ⟦Darrowshire=Borgo di Darrow⟧.", 0xc0850ae0, 0xb2ca6195, 0x888b808d, 0x58454114, 0x745f946d, "....." },
  [5210] = { "Il fratello Carlin", "Porta gli ⟦Extended Annals of Darrowshire=Annali Estesi del Borgo di Darrow⟧ a Carlin Redpath, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧.", "Grazie alla mia magia, gli ⟦Annals of Darrowshire=Annali del Borgo di Darrow⟧ hanno guadagnato delle pagine in fondo, e ora la loro storia si spinge oltre la battaglia. Uno dei passi aggiunti parla di un altro Redpath, Carlin, sopravvissuto al tradimento di Joseph. Ora Carlin si trova nelle ⟦Plaguelands=Terre Infette⟧, a est, alla ⟦Light's Hope Chapel=Cappella della Luce⟧.\n\nPrendi il libro e parla con lui.", "Vieni da ovest? Come se la passa il resto di Lordaeron? So che Andorhal è perduta, ma il Flagello ha già raggiunto la bella Tirisfal?", "Che libro è questo? Gli ⟦Annals of Darrowshire=Annali del Borgo di Darrow⟧? Era la mia casa prima della guerra... la mia casa prima della battaglia che la distrusse! Perché mi hai portato questo libro?\n\nMa guarda qui! In fondo ci sono pagine che raccontano i giorni dopo la battaglia! Ecco un passo su di me! E uno su mio fratello Joseph! Questo libro dice il vero?\n\nDobbiamo scoprire la verità!", 0xaef5197d, 0x4f2113e1, 0xe662d317, 0x1c11302d, 0x2938b896, "....." },
  [5211] = { "I difensori del ⟦Darrowshire=Borgo di Darrow⟧", "Libera 15 Darrowshire Spirit e torna da Carlin Redpath.", "Molti difensori caddero nella battaglia del ⟦Darrowshire=Borgo di Darrow⟧. E molti ora vagano di nuovo come orrendi servitori del Flagello! Trova queste povere anime e poni fine alla loro sofferenza!\n\nDai la caccia ai Cannibal Ghoul, ai Gibbering Ghoul e ai Diseased Flayer. Molti di questi mostri un tempo erano la brava gente del ⟦Darrowshire=Borgo di Darrow⟧, e distruggere ora i loro corpi renderà libere le loro anime.\n\nLi troverai a ⟦Plaguewood=Malaselva⟧, al ⟦Corin's Crossing=Crocevia di Corin⟧ e in altre roccaforti del Flagello nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧.", "I poveri difensori del ⟦Darrowshire=Borgo di Darrow⟧ mi invocano nei miei sogni, {name}. Devi liberarli!", "È bello sapere che hai trovato le anime tormentate dei miei confratelli e le hai liberate. Il mio cuore piangerà meno, sapendo che almeno alcuni dei difensori del ⟦Darrowshire=Borgo di Darrow⟧ non languono più nell'abietta schiavitù del Flagello.", 0xa05a685e, 0x26b8451f, 0x5d3c4ea2, 0x2c1c9b22, 0x2bcd7686, "....." },
  [5212] = { "La carne non mente", "Recupera 20 Campioni di Carne Infetta a Stratholme e portali a Betina Bigglezink. Sospetti che qualunque creatura di Stratholme abbia addosso questi campioni di carne.", "Gli speziali dei Reietti non sono gli unici esseri al mondo istruiti nelle scienze.\n\nStudio la pestilenza da anni, {race}. Pensavamo che la virulenza della pestilenza stesse calando, ma ciò che ho scoperto qui nelle ⟦Plaguelands=Terre Infette⟧ è sorprendente. La pestilenza sembra diventare più forte!\n\nDevo fare altri esami! La fonte più potente della pestilenza è la carne contaminata degli ultimi infettati. Raggiungi Stratholme e portami dei campioni, {name}.", "C'è chi dice che mi preoccupo troppo. A loro rispondo: 'Voi non vi preoccupate abbastanza!'", "Qualcosa è cambiato nella struttura chimica dei principi attivi della pestilenza. Servono altri dati.", 0x4f72055c, 0xfe312ef9, 0x542ecc95, 0x698b30e4, 0x1aca3b74, "....." },
  [5213] = { "Il principio attivo", "Raggiungi Stratholme e perquisisci gli ziggurat. Trova i nuovi ⟦Scourge Data=Dati del Flagello⟧ e portali a Betina Bigglezink.", "Dovrai addentrarti più a fondo a Stratholme, {name}.\n\nOltre i primi cancelli troverai gli ziggurat. Sappiamo che il Flagello trae un grande potere da queste strutture. Perquisisci gli ziggurat e torna con tutte le informazioni che riesci a scoprire.", "Siamo sul punto di scoprire cosa sia questo nuovo principio attivo della pestilenza!", "Sorprendente! Ci vorranno mesi per sezionarli e analizzarli. L'⟦Argent Dawn=Alba d'Argento⟧ ti ringrazia per i tuoi sforzi, {name}.\n\nCon la nostra benedizione, scegli tra questo ⟦Seal of the Dawn=Sigillo dell'Alba⟧ e questa ⟦Rune of the Dawn=Runa dell'Alba⟧. Puoi usare l'uno o l'altra al posto di un normale ⟦Argent Dawn Commission=Distintivo dell'Alba d'Argento⟧ per raccogliere Pietre del Flagello per nostro conto. Se dovessi perdere il tuo, parla con me e te ne procurerò uno nuovo.", 0x12b4da0e, 0xfd49cf32, 0xa118cb82, 0x30423f48, 0xb7f5f20c, "....." },
  [5214] = { "Il grande Ezra Grimm", "Trova la tabaccheria di Ezra Grimm a Stratholme e recupera una scatola di ⟦Grimm's Premium Tobacco=Tabacco Premium di Grimm⟧. Torna da Smokey LaRue quando il lavoro è fatto.", "Una cosa terribile... quello che è successo a Ezra. Vedi, la città fu saccheggiata ed Ezra non voleva lasciarsi dietro la sua preziosa merce. L'ultima cosa che ricordo che disse fu: «Brucerò fino all'ultima foglia prima che ci mettano sopra quelle loro maledette mani sporche!»\n\nMi piacerà pure un buon sigaro, ma non sono uno sciocco. Quel giorno lasciai Ezra e il suo delizioso negozio. Immagino che sia finito tra le fiamme, ma se c'è anche solo una possibilità che una scatola del suo famoso tabacco sia ancora intatta...\n\nChe ne dici, {name}? La trovi una scatola per il vecchio Smokey?", "Non ce la faccio, {name}! Devi aiutarmi! Sto morendo!", "Oh, dolce, dolce sigaro, quanto mi sei mancato...", 0x946173e2, 0x4d00c606, 0x6ce4681e, 0x4c662689, 0xb1152024, "....." },
  [5215] = { "I calderoni del Flagello", "Parla con la somma sacerdotessa MacDonnell alla ⟦Chillwind Point=Gola di Ventofreddo⟧, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧.", "Nelle terre di quella che fu Lordaeron ci sono otto calderoni: quattro qui a ovest e altri quattro annidati a est. Questi calderoni sputano veleni nell'aria, diffondendo la piaga in tutta la regione per conto del Flagello.\n\nIl potere negromantico di Kel'Thuzad è troppo forte per spegnere del tutto questi calderoni, ma crediamo di aver trovato un modo per volgerli a nostro vantaggio. La mia vice, la somma sacerdotessa MacDonnell, sarà il tuo riferimento per questo incarico; proseguirà lei con le istruzioni.", nil, "Che il potere della Luce risplenda su di te in questi tempi bui, {class}. Sono lieta di farti da coordinatrice nel nostro piano per sabotare i calderoni del Flagello.\n\nIl nostro obiettivo sarà cambiare la composizione della piaga prodotta dai calderoni in qualcosa che danneggi il Flagello. Per ottenere questo cambiamento dovrai assicurarti l'accesso a ciascuno dei quattro calderoni presenti nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧.\n\nTieniti pront<o/a>, <eroe/eroina>, perché ti attende una gloriosa battaglia contro il vile Flagello!", 0xa319eb04, 0x9a36e545, 0xce7d7f7e, nil, 0x6d217a47, "...m." },
  [5216] = { "Obiettivo: ⟦Felstone Field=Campo di Vilpietra⟧", "Raggiungi il ⟦Felstone Field=Campo di Vilpietra⟧, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧, per trovare e sconfiggere il Cauldron Lord che vi si trova. Potrebbe avere una chiave che apre l'accesso al calderone. Devi avere con te la ⟦Empty Felstone Field Bottle=Bottiglia del Campo di Vilpietra Vuota⟧ per prelevare un campione dei veleni usati nel calderone.", "Dei quattro calderoni qui a ovest, quello del ⟦Felstone Field=Campo di Vilpietra⟧ potrebbe essere il più facile da raggiungere. Il Flagello vi ha piazzato truppe meno esperte, anche se non vanno sottovalutate.\n\nVa' al ⟦Felstone Field=Campo di Vilpietra⟧, a nord-ovest di Andorhal, e affronta il signore del calderone che si trova lì. Crediamo che abbia una chiave che apre l'accesso al calderone. Una volta aperto, usa questa bottiglia per prelevare un campione dei veleni contenuti nel calderone; ci servirà per studiarlo e sviluppare un antidoto.", "Un pannello d'accesso al calderone rimane saldamente chiuso. Per aprirlo dovrai trovare la chiave.", "La chiave presa al signore del calderone Bilemaw apre perfettamente il pannello d'accesso. Dal pannello aperto esce un fetore nauseabondo, mentre una miscela sconosciuta di sostanze concentrate turbina dentro il calderone.\n\nC'è un piccolo rubinetto sotto cui la bottiglia entra abbastanza bene, e ti permette di prelevare un campione per la somma sacerdotessa MacDonnell, alla ⟦Chillwind Point=Gola di Ventofreddo⟧.", 0x92061966, 0x1dcb8d00, 0x7e63a5ca, 0x19857230, 0x6349babe, "....." },
  [5217] = { "Ritorno all'⟦Chillwind Camp=Accampamento di Ventofreddo⟧", "Porta la ⟦Filled Felstone Field Bottle=Bottiglia del Campo di Vilpietra Piena⟧ alla somma sacerdotessa MacDonnell, all'⟦Chillwind Camp=Accampamento di Ventofreddo⟧, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧.", "Riempi la bottiglia con abbastanza intruglio velenoso del calderone da avere un campione adatto allo studio.\n\nCon il veleno in mano, è ora di tornare dalla somma sacerdotessa MacDonnell all'⟦Chillwind Camp=Accampamento di Ventofreddo⟧ per completare la missione.", "Bentornat<o/a> nella relativa sicurezza dell'⟦Chillwind Camp=Accampamento di Ventofreddo⟧, {name}. Che progressi hai da riferire sui calderoni?", "Ben fatto, {name}: all'alchimista Arbington basterà pochissimo tempo per analizzarlo e mettere a punto un antidoto da introdurre nel calderone. Se riusciremo a pomparne abbastanza nell'aria, potremmo indebolire tutto il Flagello presente qui.\n\nSarà senza dubbio un'impresa lunga; dovremo colpire di continuo questi calderoni e introdurre i nostri reagenti nella loro miscela. Ma se riusciremo a tenere il ritmo, avremo un enorme vantaggio sul Flagello quando verrà il momento della battaglia!", 0xb5ee8811, 0xf055d521, 0x1dc2b280, 0xa5d00fba, 0x9b944f2c, "....." },
  [5219] = { "Obiettivo: Lacrime di Dalson", "Raggiungi le Lacrime di Dalson, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧, per trovare e sconfiggere il Cauldron Lord che vi si trova, e usa la sua chiave per accedere al calderone. Devi avere con te la ⟦Empty Dalson's Tears Bottle=Bottiglia di Lacrime di Dalson Vuota⟧ per prelevare un campione dei veleni usati nel calderone.", "Uno dei calderoni della piaga si trova nel campo di una vecchia fattoria, che oggi chiamano Lacrime di Dalson. Ebbene, oggi non verseremo lacrime, perché sventeremo i piani del Flagello e lo faremo soffocare nei suoi stessi fumi!\n\nVa' alle Lacrime di Dalson, quasi esattamente a nord di Andorhal, ed elimina il signore del calderone che si trova lì. Dovrebbe avere una chiave, come l'ultimo, che ti permetterà di entrare nel calderone. Usa questa bottiglia per prelevare un campione dall'interno del calderone; ogni calderone usa una sua miscela di tossine.", "Un pannello d'accesso al calderone rimane saldamente chiuso. Per aprirlo dovrai trovare la chiave.", "La macabra chiave trovata sul signore del calderone scivola facilmente in una serratura e poi scompare, dandoti accesso permanente al calderone. Icori densi e viscosi pulsano attraverso tubi contorti nella struttura sottostante del calderone.\n\nC'è un piccolo rubinetto sotto cui la bottiglia entra abbastanza bene, e ti permette di prelevare un campione per la somma sacerdotessa MacDonnell, alla ⟦Chillwind Point=Gola di Ventofreddo⟧.", 0xd56b9979, 0x0f3a6108, 0xf7c7dc48, 0x19857230, 0x868a59fa, "....." },
  [5220] = { "Ritorno all'⟦Chillwind Camp=Accampamento di Ventofreddo⟧", "Porta la ⟦Filled Dalson's Tears Bottle=Bottiglia di Lacrime di Dalson Piena⟧ alla somma sacerdotessa MacDonnell, all'⟦Chillwind Camp=Accampamento di Ventofreddo⟧, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧.", "Riempi con cura la bottiglia con abbastanza icore del calderone da avere un campione che ritieni di dimensioni adeguate.\n\nCon il veleno in mano, è ora di tornare dalla somma sacerdotessa MacDonnell all'⟦Chillwind Camp=Accampamento di Ventofreddo⟧ per completare la missione.", "Sappiamo che ogni calderone usa una diversa miscela di reagenti per generare la sua tossina portatrice di piaga; allo stesso modo, sappiamo che dovremo sviluppare un agente neutralizzante diverso per ciascun calderone. Il tuo campione delle Lacrime di Dalson sarà la chiave per capire quali reagenti specifici richiede quel calderone.", "Ah, qui c'è materiale in abbondanza da studiare. Ben fatto, {name}!\n\nPer ora, il prossimo passo spetta a noi. Dovremo stilare un elenco di reagenti che, combinati con ciò che è già nel calderone, agiscano da antidoto.\n\nL'unico modo per introdurlo è mettere i reagenti direttamente nel calderone. L'alchimista Arbington avrà altre informazioni in merito, quindi parla con lui appena puoi.", 0xb5ee8811, 0x7a8719c4, 0x2df77e31, 0xdcb81fc2, 0x99b957f3, "....." },
  [5222] = { "Obiettivo: Campo Putrido", "Raggiungi il Campo Putrido, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧, per trovare e sconfiggere il Cauldron Lord che vi si trova, e usa la sua chiave per accedere al calderone. Devi avere con te la ⟦Empty Writhing Haunt Bottle=Bottiglia del Campo Putrido Vuota⟧ per prelevare un campione dei veleni usati nel calderone.", "Due calderoni sono stati aperti con successo; anche se potrai accedervi quando vorrai, vogliamo comunque aprire gli altri due che restano. Così avremo tutti più modi per introdurre l'agente neutralizzante!\n\nStavolta colpirai il calderone del Campo Putrido. Si trova quasi esattamente a est di Andorhal, piuttosto vicino alle mura in rovina della città; anche stavolta elimina il signore del calderone che si trova lì per prendergli la chiave. Usa questa bottiglia per prelevare il campione dal calderone.\n\nBuona caccia, {name}!", "Un pannello d'accesso al calderone rimane saldamente chiuso. Per aprirlo dovrai trovare la chiave.", "La chiave del signore del calderone apre il pannello d'accesso di questo calderone e poi scompare, proprio come le altre chiavi dei due calderoni che hai affrontato prima. Una sostanza dall'odore putrido ribolle violentemente sotto la piattaforma del calderone.\n\nC'è un piccolo rubinetto sotto cui la bottiglia entra abbastanza bene, e ti permette di prelevare un campione per la somma sacerdotessa MacDonnell, alla ⟦Chillwind Point=Gola di Ventofreddo⟧.", 0x6f80571e, 0x1fc4daf4, 0x49ce8443, 0x19857230, 0x92049294, "....." },
  [5223] = { "Ritorno all'⟦Chillwind Camp=Accampamento di Ventofreddo⟧", "Porta la ⟦Filled Writhing Haunt Bottle=Bottiglia del Campo Putrido Piena⟧ alla somma sacerdotessa MacDonnell, all'⟦Chillwind Camp=Accampamento di Ventofreddo⟧, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧.", "Riempi con delicatezza la bottiglia vuota; un campione della sostanza ripugnante che ribolle sotto la piattaforma del calderone ora ondeggia avanti e indietro nel fragile contenitore di vetro.\n\nCon il veleno in mano, è ora di tornare dalla somma sacerdotessa MacDonnell all'⟦Chillwind Camp=Accampamento di Ventofreddo⟧ per completare la missione.", "Una volta analizzato con successo il campione prelevato dal calderone del Campo Putrido, avremo una terza via per scagliare un devastante agente neutralizzante sul Flagello!", "Un'altra missione eseguita alla perfezione, {name}! Così abbiamo tre calderoni da rivolgere contro il Flagello. Se il dominio negromantico di Kel'Thuzad su queste terre non fosse forte come lo è ora, oserei dire che li avresti spenti del tutto!\n\nL'alchimista Arbington avrà un rapporto su ciò che servirà a questo calderone, come agli altri calderoni sovvertiti, per diffondere il nostro agente neutralizzante contro la piaga. Detto questo, è giunto il momento di portare sotto il nostro controllo l'ultimo calderone dell'ovest!", 0xb5ee8811, 0xc03ccc2f, 0xe333822c, 0xf24f8119, 0x7d43aa3d, "....." },
  [5225] = { "Obiettivo: ⟦Gahrron's Withering=Podere di Gahrron⟧", "Va' al ⟦Gahrron's Withering=Podere di Gahrron⟧, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧, per trovare e sconfiggere il Cauldron Lord che vi si trova, e usa la sua chiave per accedere al calderone. Devi avere con te la ⟦Empty Gahrron's Withering Bottle=Bottiglia del Podere di Gahrron Vuota⟧ per prelevare un campione dei veleni usati nel calderone.", "L'ultimo calderone rimasto si trova in una fattoria che oggi chiamano ⟦Gahrron's Withering=Podere di Gahrron⟧. È sorvegliato da alcuni dei servitori più temibili del Flagello: per la precisione, spettri e fantasmi. Non vanno presi alla leggera, {name}.\n\nIl ⟦Gahrron's Withering=Podere di Gahrron⟧ è esattamente a nord-est della nostra posizione, vicino a dove iniziano le ⟦Eastern Plaguelands=Terre Infette Orientali⟧; anche qui, elimina il signore del calderone che si trova lì per prendergli la chiave. Ecco la tua bottiglia per il campione, vuota; riportamela piena. Che la Luce ti protegga in questa pericolosa missione, {class}.", "Un pannello d'accesso al calderone rimane saldamente chiuso. Per aprirlo dovrai trovare la chiave.", "La chiave del signore del calderone Soulwrath si disintegra appena tocca la serratura del pannello d'accesso alla base della piattaforma del calderone. Dall'interno si sente un leggero sferragliare, e il pannello si spalanca rivelando altre tossine viscose nella struttura del calderone.\n\nC'è un piccolo rubinetto sotto cui la bottiglia entra abbastanza bene, e ti permette di prelevare un campione per la somma sacerdotessa MacDonnell, alla ⟦Chillwind Point=Gola di Ventofreddo⟧.", 0xbd246940, 0x48ca8f98, 0xfd678d22, 0x19857230, 0xb16092b0, "....." },
  [5226] = { "Ritorno all'⟦Chillwind Camp=Accampamento di Ventofreddo⟧", "Porta la ⟦Filled Gahrron's Withering Bottle=Bottiglia del Podere di Gahrron Piena⟧ alla somma sacerdotessa MacDonnell all'⟦Chillwind Camp=Accampamento di Ventofreddo⟧, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧.", "Chiudi con cura il rubinetto del pannello di controllo, osservando gli icori putridi del calderone gocciolare nella bottiglia vuota.\n\nCon il veleno in mano, è ora di tornare dalla somma sacerdotessa MacDonnell all'⟦Chillwind Camp=Accampamento di Ventofreddo⟧ per completare la missione.", "Il ⟦Gahrron's Withering=Podere di Gahrron⟧ ospita l'ultimo calderone qui a ovest a cui dobbiamo accedere. Una volta ottenuto un campione della piaga che sputa fuori, potremo immettere i nostri reagenti nell'ambiente attraverso quattro recipienti diversi! Il Flagello avrà il suo bel da fare per tenerci lontani da tutti e quattro, anche con il potere di Kel'Thuzad alle spalle.", "Congratulazioni, {name}, hai sbloccato per noi l'ultimo calderone! L'alchimista Arbington saprà presto quali reagenti servono alla miscela di questo calderone.\n\nQuanto a te, sono certa che il comandante Valorfist vorrà ringraziarti di persona per l'aiuto che ci hai dato. Senza di te, la nostra lotta contro il Flagello sarebbe stata quasi impossibile. Grazie, <eroe/eroina>!", 0xb5ee8811, 0x8eb15622, 0x04933e62, 0xfc41e6cc, 0x23611b6c, "....." },
  [5228] = { "I calderoni del Flagello", "Parla con la sacerdotessa dell'ombra Vandis alla Granbarricata, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧.", "Nelle terre di quella che fu Lordaeron ci sono otto calderoni: quattro a ovest e altri quattro trincerati a est. Questi calderoni sputano veleni nell'aria, diffondendo la piaga in tutta la regione per conto del Flagello.\n\nIl potere negromantico di Kel'Thuzad è troppo forte per spegnere del tutto questi calderoni, ma crediamo di aver trovato un modo per volgerli a nostro vantaggio. La mia vice, la sacerdotessa dell'ombra Vandis, sarà il tuo riferimento per questo incarico; proseguirà lei con le istruzioni.", nil, "Dalle ombre ti porgo il mio saluto, <fratello/sorella> {race}. Sarò io a coordinare il nostro piano per sabotare i calderoni del Flagello.\n\nIl nostro obiettivo sarà cambiare la composizione della piaga prodotta dai calderoni in qualcosa che danneggi il Flagello. Per ottenere questo cambiamento dovrai assicurarti l'accesso a ciascuno dei quattro calderoni qui nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧.\n\nÈ giunto il momento che tu guidi l'assalto contro il Flagello, <eroe/eroina>.", 0xa319eb04, 0xd8bc2aad, 0xc83fd89e, nil, 0xbd4a0dd4, "...m.", nil, nil, nil, nil, 0xaf72b061 },
  [5229] = { "Obiettivo: ⟦Felstone Field=Campo di Vilpietra⟧", "Raggiungi il ⟦Felstone Field=Campo di Vilpietra⟧, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧, per trovare e sconfiggere il Cauldron Lord che vi si trova. Potrebbe avere una chiave che apre l'accesso al calderone. Devi avere con te la ⟦Empty Felstone Field Bottle=Bottiglia del Campo di Vilpietra Vuota⟧ per prelevare un campione dei veleni usati nel calderone.", "Dei quattro calderoni nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧, quello del ⟦Felstone Field=Campo di Vilpietra⟧ potrebbe essere il più facile da raggiungere. Il Flagello vi ha piazzato truppe meno esperte, anche se non vanno sottovalutate.\n\nVa' al ⟦Felstone Field=Campo di Vilpietra⟧, proprio a est di qui e a nord-ovest di Andorhal, e affronta il signore del calderone che si trova lì. Ha addosso una chiave che apre l'accesso al calderone. Una volta aperto, usa questa bottiglia per prelevare un campione delle tossine del calderone; ci servirà per studiarlo e sviluppare un antidoto.", "Un pannello d'accesso al calderone rimane saldamente chiuso. Per aprirlo dovrai trovare la chiave.", "La chiave presa al signore del calderone Bilemaw apre perfettamente il pannello d'accesso, anche se scompare dopo che l'hai usata. Pensi comunque di poter aprire il pannello anche senza chiave, ora. Dal pannello aperto esce un fetore nauseabondo, mentre una miscela sconosciuta di sostanze concentrate turbina dentro il calderone.\n\nC'è un piccolo rubinetto sotto cui la bottiglia entra abbastanza bene, e ti permette di prelevare un campione per la sacerdotessa dell'ombra Vandis, alla Granbarricata.", 0x92061966, 0x1dcb8d00, 0x96d41740, 0x19857230, 0xee093d43, "....." },
  [5230] = { "Ritorno alla Granbarricata", "Porta la ⟦Filled Felstone Field Bottle=Bottiglia del Campo di Vilpietra Piena⟧ alla sacerdotessa dell'ombra Vandis, alla Granbarricata, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧.", "Riempi la bottiglia con abbastanza intruglio velenoso del calderone da avere un campione adatto allo studio.\n\nCon il veleno in mano, è ora di tornare dalla sacerdotessa dell'ombra Vandis alla Granbarricata per completare la missione.", "Bentornat<o/a> nella relativa sicurezza della Granbarricata, {name}. Che progressi hai da riferire sui calderoni?", "Ben fatto, {name}: allo speziale Dithers basterà pochissimo tempo per analizzarlo e mettere a punto un antidoto da introdurre nel calderone. Se riusciremo a pomparne abbastanza nell'aria, potremmo indebolire tutto il Flagello presente qui.\n\nSarà senza dubbio un'impresa lunga; dovremo colpire di continuo questi calderoni e introdurre i nostri reagenti nella loro miscela. Ma se riusciremo a tenere il ritmo, avremo un enorme vantaggio sul Flagello quando verrà il momento della battaglia!", 0x45c54db8, 0x1aa51cd7, 0xfdfaed2b, 0x4c0d32d7, 0xa1c30348, "....." },
  [5231] = { "Obiettivo: Lacrime di Dalson", "Raggiungi le Lacrime di Dalson, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧, per trovare e sconfiggere il Cauldron Lord che vi si trova, e usa la sua chiave per accedere al calderone. Devi avere con te la ⟦Empty Dalson's Tears Bottle=Bottiglia di Lacrime di Dalson Vuota⟧ per prelevare un campione dei veleni usati nel calderone.", "Uno dei calderoni della piaga si trova nel campo di una vecchia fattoria, che oggi chiamano Lacrime di Dalson. Oggi non si verseranno lacrime, {class}: dobbiamo colpire questo calderone e riuscire ad accedervi!\n\nVa' alle Lacrime di Dalson, quasi esattamente a nord di Andorhal, ed elimina il signore del calderone che si trova lì. Dovrebbe avere una chiave, come l'ultimo, che ti permetterà di entrare nelle viscere del calderone. Usa questa bottiglia per prelevare un campione dall'interno del calderone; ogni calderone usa una sua miscela di tossine.", "Un pannello d'accesso al calderone rimane saldamente chiuso. Per aprirlo dovrai trovare la chiave.", "La chiave scheletrica trovata sul signore del calderone scivola facilmente in una serratura e poi scompare, dandoti accesso permanente al calderone. Icori densi e viscosi pulsano attraverso tubi contorti nella struttura sottostante del calderone.\n\nC'è un piccolo rubinetto sotto cui la bottiglia entra abbastanza bene, e ti permette di prelevare un campione per la sacerdotessa dell'ombra Vandis, alla Granbarricata.", 0xd56b9979, 0x0f3a6108, 0x13261da4, 0x19857230, 0x1c2a06c6, "....." },
  [5232] = { "Ritorno alla Granbarricata", "Porta la ⟦Filled Dalson's Tears Bottle=Bottiglia di Lacrime di Dalson Piena⟧ alla sacerdotessa dell'ombra Vandis, alla Granbarricata, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧.", "Riempi con cura la bottiglia con abbastanza icore del calderone da avere un campione che ritieni di dimensioni adeguate.\n\nCon il veleno in mano, è ora di tornare dalla sacerdotessa dell'ombra Vandis alla Granbarricata per completare la missione.", "Sappiamo che ogni calderone usa una diversa miscela di reagenti per generare la sua tossina portatrice di piaga; allo stesso modo, sappiamo che dovremo sviluppare un agente neutralizzante diverso per ciascun calderone. Il tuo campione delle Lacrime di Dalson sarà la chiave per capire quali reagenti specifici richiede quel calderone.", "Ah, qui c'è materiale in abbondanza da studiare. Ben fatto, {name}!\n\nPer ora, il prossimo passo spetta a noi. Dovremo stilare un elenco di reagenti che, combinati con ciò che è già nel calderone, agiscano da antidoto.\n\nL'unico modo per introdurlo è mettere i reagenti direttamente nel calderone. Lo speziale Dithers avrà altre informazioni in merito, quindi parla con lui il prima possibile.", 0x45c54db8, 0xf93a1fff, 0x5d6b63ef, 0xdcb81fc2, 0xab0cf46a, "....." },
  [5233] = { "Obiettivo: Campo Putrido", "Raggiungi il Campo Putrido, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧, per trovare e sconfiggere il Cauldron Lord che vi si trova, e usa la sua chiave per accedere al calderone. Devi avere con te la ⟦Empty Writhing Haunt Bottle=Bottiglia del Campo Putrido Vuota⟧ per prelevare un campione dei veleni usati nel calderone.", "Due calderoni sono stati aperti con successo; anche se potrai accedervi quando vorrai, vogliamo comunque aprire gli altri due che restano. Così avremo tutti più modi per introdurre l'agente neutralizzante!\n\nStavolta colpirai il calderone del Campo Putrido. Si trova quasi esattamente a est di Andorhal, piuttosto vicino alle mura in rovina della città; anche stavolta elimina il signore del calderone che si trova lì per prendergli la chiave. Usa questa bottiglia per prelevare il campione dal calderone.\n\nBuona caccia, {name}!", "Un pannello d'accesso al calderone rimane saldamente chiuso. Per aprirlo dovrai trovare la chiave.", "La chiave del signore del calderone apre il pannello d'accesso di questo calderone e poi scompare, proprio come le altre chiavi dei calderoni che hai affrontato prima. Una sostanza dall'odore putrido ribolle violentemente sotto la piattaforma del calderone.\n\nC'è un piccolo rubinetto sotto cui la bottiglia entra abbastanza bene, e ti permette di prelevare un campione per la sacerdotessa dell'ombra Vandis, alla Granbarricata.", 0x6f80571e, 0x1fc4daf4, 0xb8c56557, 0x19857230, 0x4cff0616, "....." },
  [5234] = { "Ritorno alla Granbarricata", "Porta la ⟦Filled Writhing Haunt Bottle=Bottiglia del Campo Putrido Piena⟧ alla sacerdotessa dell'ombra Vandis, alla ⟦The Bulwark=Granbarricata⟧, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧.", "Riempi con delicatezza la bottiglia vuota; un campione della sostanza ripugnante che ribolle sotto la piattaforma del calderone ora ondeggia avanti e indietro nel fragile contenitore di vetro.\n\nCon il veleno in mano, è ora di tornare dalla sacerdotessa dell'ombra Vandis alla Granbarricata per completare la missione.", "Una volta analizzato con successo il campione prelevato dal calderone del Campo Putrido, avremo una terza via per scagliare un devastante agente neutralizzante contro il Flagello!", "Un'altra missione eseguita alla perfezione, {name}! Così abbiamo tre calderoni da rivolgere contro il Flagello. Se il dominio negromantico di Kel'Thuzad su queste terre non fosse forte come lo è ora, oserei dire che li avresti spenti del tutto!\n\nLo speziale Dithers avrà un rapporto su ciò che servirà a questo calderone, come agli altri calderoni sovvertiti, per diffondere il nostro agente neutralizzante contro la piaga. Detto questo, è giunto il momento di portare sotto il nostro controllo l'ultimo calderone dell'ovest!", 0x45c54db8, 0x7e17ab7e, 0x691909b9, 0x463535af, 0xe45f216f, "....." },
  [5235] = { "Obiettivo: ⟦Gahrron's Withering=Podere di Gahrron⟧", "Va' al ⟦Gahrron's Withering=Podere di Gahrron⟧, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧, per trovare e sconfiggere il Cauldron Lord che vi si trova, e usa la sua chiave per accedere al calderone. Devi avere con te la ⟦Empty Gahrron's Withering Bottle=Bottiglia del Podere di Gahrron Vuota⟧ per prelevare un campione dei veleni usati nel calderone.", "L'ultimo calderone rimasto si trova in una fattoria che oggi chiamano ⟦Gahrron's Withering=Podere di Gahrron⟧. È sorvegliato da alcuni dei servitori più temibili del Flagello: per la precisione, spettri e fantasmi. Non vanno presi alla leggera, {name}.\n\nIl ⟦Gahrron's Withering=Podere di Gahrron⟧ è molto a est della Granbarricata, vicino a dove iniziano le ⟦Eastern Plaguelands=Terre Infette Orientali⟧; anche qui, elimina il signore del calderone che si trova lì per prendergli la chiave. Ecco la tua bottiglia per il campione, vuota; riportamela piena. Che le ombre ti avvolgano e ti proteggano in questa pericolosa missione, {class}.", "Un pannello d'accesso al calderone rimane saldamente chiuso. Per aprirlo dovrai trovare la chiave.", "La chiave del signore del calderone Soulwrath si disintegra appena tocca la serratura del pannello d'accesso alla base della piattaforma del calderone. Dall'interno si sente un leggero sferragliare, e il pannello si spalanca rivelando altre tossine viscose nella struttura del calderone.\n\nC'è un piccolo rubinetto sotto cui la bottiglia entra abbastanza bene, e ti permette di prelevare un campione per la sacerdotessa dell'ombra Vandis, alla Granbarricata.", 0xbd246940, 0x48ca8f98, 0x159fedea, 0x19857230, 0xe47b642b, "....." },
  [5236] = { "Ritorno alla Granbarricata", "Porta la ⟦Filled Gahrron's Withering Bottle=Bottiglia del Podere di Gahrron Piena⟧ alla sacerdotessa dell'ombra Vandis alla Granbarricata, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧.", "Chiudi con cura il rubinetto del pannello di controllo, osservando gli icori putridi del calderone gocciolare nella bottiglia vuota.\n\nCon il veleno in mano, è ora di tornare dalla sacerdotessa dell'ombra Vandis alla Granbarricata per completare la missione.", "Il ⟦Gahrron's Withering=Podere di Gahrron⟧ ospita l'ultimo calderone qui a ovest a cui dobbiamo ottenere l'accesso. Una volta ottenuto un campione della piaga di quel calderone, potremo immettere i nostri reagenti nell'ambiente attraverso quattro recipienti diversi! Il Flagello avrà il suo bel da fare per tenerci lontani da tutti e quattro, anche con il potere di Kel'Thuzad alle spalle.", "Congratulazioni, {name}, hai sbloccato per noi l'ultimo calderone! Lo speziale Dithers saprà presto quali reagenti servono alla miscela di questo calderone.\n\nQuanto a te, sono certa che l'alto esecutore Derrington vorrà ringraziarti di persona per l'aiuto che ci hai dato. Senza di te, la nostra lotta contro il Flagello sarebbe stata quasi impossibile. Ti ringrazio, potente {class}.", 0x45c54db8, 0x8394b611, 0x740b59b6, 0xb5a5a86c, 0x484e1603, "....." },
  [5237] = { "Missione compiuta!", nil, nil, nil, "{name}, la riuscita riconversione dei calderoni è una vittoria straordinaria per noi!\n\n<Il comandante si schiarisce la voce e comincia a tuonare.>\n\nChe tutti i presenti ascoltino: per i servigi resi al Regno di ⟦Stormwind=Roccavento⟧ e all'⟦Alliance=Alleanza⟧ ben oltre il proprio dovere (di fronte a probabilità schiaccianti e pericoli incredibili, aggiungerei), consegno a {name} questo dono e <gli/le> porgo la nostra eterna gratitudine come <vero/vera> <eroe/eroina> dell'⟦Alliance=Alleanza⟧. Evviva, dico io!", 0x48e07c4f, nil, nil, nil, 0x3f13bcd4, ".mmm.", nil, nil, nil, nil, 0x4417209a },
  [5238] = { "Missione compiuta!", nil, nil, nil, "{name}, la riuscita riconversione dei calderoni è una vittoria straordinaria per noi!\n\n<L'alto esecutore si schiarisce la voce e comincia a tuonare.>\n\nChe tutti i presenti ascoltino: per i servigi resi ai Reietti e all'⟦Horde=Orda⟧ intera ben oltre ogni aspettativa (di fronte a probabilità schiaccianti e pericoli incredibili, aggiungerei), consegno a {name} questo dono e <gli/le> porgo la nostra eterna gratitudine come <vero/vera> <eroe/eroina> dell'⟦Horde=Orda⟧. Urrà!", 0x48e07c4f, nil, nil, nil, 0x39fafac6, ".mmm.", nil, nil, nil, nil, 0xc5dc7c2f },
  [5241] = { "Zio Carlin", "Trova Carlin Redpath.", "A volte, di notte, sento piangere mio zio Carlin. Sembra lontano, verso est.\n\nSpero che non pianga per me! {name}, troveresti mio zio per dirgli che sto bene?\n\nSe lo trovi, digli che lo aspetto e che voglio sentire la storia che mi raccontava sempre... quella dei conigli e della marmellata di bacche! È così divertente!", nil, "Hai visto Pamela? È viva?\n\nÈ morta? No! Oh, Pamela! Perché il tuo spirito soffre ancora in questo mondo? Perché tu sei morta, mentre la sorte tiene in vita me? Prenderei il tuo posto all'istante, e vagherei per il ⟦Darrowshire=Borgo di Darrow⟧ morto, un fantasma solitario!\n\nAh, ma questa notizia non può cambiare il destino. Grazie, {name}. Ora il mio dovere, il mio dovere di vendetta, brucia più che mai.", 0xb32159b5, 0x6db66850, 0xdaa2b5cb, nil, 0xaa9535cb, "...m." },
  [5242] = { "Un colpo finale", "Uccidi Moora e Salia e porta la ⟦Shadow Lord Fel'dan's Head=Testa del Signore dell'Ombra Fel'dan⟧ a Greta Mosshoof, nel ⟦Felwood=Vilbosco⟧.", "Purtroppo vedo che l'unico modo per fermare questa minaccia al ⟦Felwood=Vilbosco⟧ è un attacco frontale. Non ci sono altre vie per entrare nell'⟦Shadow Hold=Eremo delle Ombre⟧, e non ho modo di teletrasportarti all'interno. La strada dritta fino in fondo è l'unica via... e so anche chi dovresti cercare. Si chiama Fel'dan... il signore dell'ombra Fel'dan. È il mortale che comanda laggiù... è la testa del serpente. Uccidi lui e le due succubi al suo servizio e torna da me. È Fel'dan a stringere patti con la Legione. Va fermato.", "Senza Fel'dan, il ⟦Shadow Council=Concilio dell'Ombra⟧ perderà, si spera, la sua guida e comincerà a dilaniarsi. I suoi membri lotteranno tra loro per il controllo e accumuleranno risorse per i piani futuri. Sarà il momento giusto per annientare loro e i loro schiavi demoniaci.", "Sia lodata la Madre Terra, {name}! Grazie! È davvero un gran giorno!\n\nCon questo colpo alla sua gerarchia, il ⟦Shadow Council=Concilio dell'Ombra⟧ faticherà a tornare ai livelli di potere di un tempo. Oggi hai fatto una grande cosa!", 0x715aa831, 0xe88b2237, 0x279f369a, 0xe2ec25f5, 0x8ad810c1, "....." },
  [5243] = { "Le dimore del sacro", "Raggiungi Stratholme, a nord. Cerca nelle casse di rifornimenti sparse per la città e recupera 5 ⟦Stratholme Holy Water=Acqua Santa di Stratholme⟧. Torna da Leonid Barthalomew il Reverito quando avrai raccolto abbastanza fluido benedetto.", "Considero la mia non morte una malattia, {race}. Un male che richiede soltanto una cura; eppure è anche una grande benedizione per l'⟦Argent Dawn=Alba d'Argento⟧. Quale strumento migliore per abbattere gli infedeli del Flagello, se non i non morti stessi?\n\nI miei colleghi mi riveriscono per i sacrifici che ho compiuto, ma gli onori per me non significano nulla.\n\nSe ti interessa aiutare l'⟦Argent Dawn=Alba d'Argento⟧, un lavoro posso offrirtelo.\n\nAvventurati a Stratholme e recupera la nostra scorta di acqua santa. Cerca nelle casse di rifornimenti.", "Fai attenzione: non tutte le casse di rifornimenti saranno sopravvissute alla distruzione della città. Il Flagello non osa toccare l'acqua, ma di certo l'acqua santa non impedirà le infestazioni di parassiti.", "Ben fatto, {race}. Hai dimostrato che, pur essendo tollerante con gli altri, non ti fermerai davanti a nulla pur di distruggere i servitori di Kel'Thuzad.", 0x7afa4fb5, 0xcc65272a, 0xe916eb65, 0x964cf564, 0x32cba1e6, "....." },
  [5244] = { "Le ⟦The Ruins of Kel'Theril=Rovine di Kel'Theril⟧", "Parla con Jaron Stoneshaper al ⟦Starfall Village=Padiglione Pioggia di Stelle⟧.", "La storia di Kel'Theril è quella di una razza maledetta, legata al luogo in cui tentò uno sciagurato rituale...\n\nGli Alti Nobili che troverai laggiù rubarono un tempo un artefatto sacro, convinti di poterne assorbire il potere e diventare ancora più potenti. Nel tentativo, la reliquia andò in frantumi in un'enorme esplosione che scagliò i pezzi sotto il ghiaccio del lago...\n\nParla con Jaron Stoneshaper se vuoi saperne di più; è stato da quelle parti di recente e può raccontarti altro.", nil, "Beh, certo, posso dirti di più su Kel'Theril. Bada, non sono uno storico, ma posso raccontarti ciò che ho visto laggiù...", 0x72a68b2c, 0x30581a76, 0x8305ca6f, nil, 0xb7174f8c, "...m." },
  [5245] = { "Spiriti inquieti di Kel'Theril", "Usa il ⟦Jaron's Pick=Piccone di Jaron⟧ per trovare i quattro frammenti della ⟦Highborne Relic=Reliquia degli Alti Nobili⟧. Portali ad Aurora Skycaller, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧.", "Gli spiriti degli Alti Nobili sono creature infelici, questo è certo. Cercano ancora i pezzi proprio della cosa che li ha condannati per sempre a Kel'Theril: la reliquia rubata.\n\nSe ti interessa tanto, prendi il mio piccone e va' a sud, al lago, e vedi se riesci a recuperarne i pezzi dal ghiaccio.\n\nIo non posso dirti niente di ciò che troverai, ma conosco qualcuno che potrebbe... Aurora Skycaller: vive vicino alla ⟦Northpass Tower=Torre Passo Nord⟧, nella parte settentrionale delle ⟦Eastern Plaguelands=Terre Infette Orientali⟧.", "Perché sei venut<o/a> qui?", "Il passato degli alti elfi è qualcosa di cui non desidero parlare, {name}. Ti prego, mi addolora pensare a tutto ciò che è accaduto... e al fatto che non c'è modo di rimediare.", 0x59488fa1, 0x2d763bfa, 0xc5c65ece, 0x485a68cd, 0x24475225, "....." },
  [5246] = { "Frammenti del passato", "Trova gli ⟦Sacred Highborne Writings=Scritti Sacri degli Alti Nobili⟧ nel ⟦Temple of Zin-Malor=Tempio di Zin-Malor⟧, ad Azshara, e portali ad Aurora Skycaller, vicino alla ⟦Northpass Tower=Torre Passo Nord⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧.", "Non mi ero resa conto... Perdona le mie parole insensibili, {class}.\n\nNon desidero soffermarmi sugli errori dei miei antenati, ma se la tua richiesta è davvero sincera, ti aiuterò.\n\n<Aurora esamina i frammenti.>\n\nCredo che questo sia il ⟦Crystal of Zin-Malor=Cristallo di Zin-Malor⟧, un artefatto capace di contenere e controllare potenti forze arcane. Avrebbe potuto essere usato a fin di bene, ma le intenzioni malvagie di chi lo rubò lo mandarono in frantumi.\n\nVa' al ⟦Temple of Zin-Malor=Tempio di Zin-Malor⟧, ad Azshara: posso solo sperare che il libro sia ancora lì.", "Solo nelle pagine degli scritti sacri potrò capire se sono in grado di aiutarti o no...", "Queste pagine sono rimaste intatte per moltissimi anni...", 0x27ceb4bb, 0x7f781651, 0x8b4619f9, 0x1e46fcd2, 0x1017a873, "....." },
  [5247] = { "Frammenti del passato", "Porta un ⟦Enchanted Thorium Bar=Lingotto di Torio Incantato⟧, 5 ⟦Crystal Restore=Guarigione del Cristallo⟧ e una ⟦Vial of Dire Water=Fiala d'Acqua Infausta⟧ ad Aurora Skycaller, vicino alla ⟦Northpass Tower=Torre Passo Nord⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧.", "Potrò aiutarti, se ricreare il manufatto è davvero ciò che desideri.\n\nPer saldare di nuovo i pezzi mi serviranno oggetti con forti proprietà magiche. Un lingotto di torio incantato e cinque Guarigioni del Cristallo... Dovrai anche raccogliere dell'acqua da un luogo che può sembrare improbabile... Trova la pozza infausta lungo l'Eldreth Row, a ⟦Dire Maul=Maglio Infausto⟧, nel Feralas, e riempi questa fiala.\n\nMentre sei via, cercherò di ricavare da queste pagine le conoscenze che mi servono per riparare i danni subiti dalla reliquia.", "La reliquia va affidata solo alle mani più degne di fiducia. Non deve essere rubata di nuovo...", "Con questi elementi posso fondere insieme i frammenti... e, spero, riportarli a ciò che erano un tempo.", 0x27ceb4bb, 0x4c6ff390, 0x4e3bcc04, 0xaf7eee29, 0xb2bf6926, "....." },
  [5248] = { "Tormentati dal passato", "Porta il ⟦Crystal of Zin-Malor=Cristallo di Zin-Malor⟧ al ⟦Lake Kel'Theril=Lago Kel'Theril⟧, a ⟦Winterspring=Fontefredda⟧, e trova uno spirito degli Alti Nobili disposto a parlarti.", "{name}, piango per ciò che è accaduto in passato. Come questo cristallo, gli elfi, come razza, sono andati in frantumi. Non so se i pezzi verranno mai riuniti di nuovo in uno solo, ma il mio dolore si è alleviato potendoti aiutare in questo piccolo compito.\n\nNon dobbiamo dimenticare il passato, {name}...\n\nTi prego, riporta il ⟦Crystal of Zin-Malor=Cristallo di Zin-Malor⟧ al ⟦Lake Kel'Theril=Lago Kel'Theril⟧. Devi trovare uno spirito degli Alti Nobili che riconosca l'errore commesso tanto tempo fa. Mostra allo spirito che abbiamo rimesso le cose a posto.", "Maledettiiii... Per sempreeee...", "Ti preeego, lasciaaami...", 0xa94fcf42, 0x50bb5fb9, 0xce237f63, 0x80ad8577, 0xabfe6023, "....." },
  [5249] = { "A ⟦Winterspring=Fontefredda⟧!", "Trova il ⟦Starfall Village=Padiglione Pioggia di Stelle⟧, a ⟦Winterspring=Fontefredda⟧, e parla con Wynd Nightchaser.", "A ⟦Winterspring=Fontefredda⟧, a nord di qui, ci sono molte antiche rovine elfiche. È una terra aspra, ma custodisce molti segreti e luoghi da esplorare.\n\nCon tutto il lavoro che ho qui nel ⟦Felwood=Vilbosco⟧, non ho avuto occasione di andare a ⟦Winterspring=Fontefredda⟧. Ma non c'è motivo per cui non debba andarci tu!\n\nQuando sei lì, cerca Wynd Nightchaser. Passa quasi tutto il tempo al ⟦Starfall Village=Padiglione Pioggia di Stelle⟧ e conosce bene la zona.", nil, "Sei amic<o/a> di Ivy Leafrunner? Piacere di conoscerti, {name}.", 0x21f29268, 0xb58824fe, 0x1884e677, nil, 0xf988d04b, "...m." },
  [5250] = { "Pioggia di Stelle", "Trova Pioggia di Stelle, a ⟦Winterspring=Fontefredda⟧, e parla con Wynd Nightchaser.", "A ⟦Winterspring=Fontefredda⟧, a nord del ⟦Felwood=Vilbosco⟧, ci sono molte antiche rovine elfiche. È una terra aspra, ma custodisce molti segreti e luoghi da esplorare.\n\nI miei studi qui mi tengono così occupato che da tempo non ho occasione di andare a ⟦Winterspring=Fontefredda⟧. Ma non c'è motivo per cui tu non debba andarci a studiare le rovine.\n\nQuando sei lì, cerca Wynd Nightchaser. Passa quasi tutto il tempo a Pioggia di Stelle e conosce bene la zona.\n\nDigli che sei tra i miei allievi...", nil, "Sei tra gli allievi di Daryn Lightwind? Piacere di conoscerti, {name}.", 0xc6c6cea4, 0x9b1efe0a, 0xaff8bd19, nil, 0x4a9ac80d, "...m." },
  [5251] = { "L'archivista", "Raggiungi Stratholme e trova Archivist Galford della ⟦Scarlet Crusade=Crociata Scarlatta⟧. Distruggilo e brucia lo Scarlet Archive.", "Qualunque cosa portata all'estremo è un pericolo per il nostro mondo, {name}. Prendi per esempio la ⟦Scarlet Crusade=Crociata Scarlatta⟧. Credi che il loro cieco fanatismo serva un bene superiore? Quanti innocenti hanno distrutto in nome della Luce?\n\nBlasfemi, tutti quanti!\n\nUno in particolare, però, mi interessa: l'archivista Galford di Stratholme, un uomo che veglia sui documenti più preziosi della Crociata. Distruggilo e brucia i suoi archivi! Se ci riesci, torna da me e sarai ricompensat<o/a>.", "Ricorda, {name}: dobbiamo essere tolleranti, ma saldi nelle nostre convinzioni!", "Eccezionale, {name}! Anni di informazioni, perduti! La ⟦Scarlet Crusade=Crociata Scarlatta⟧ sentirà di certo questo colpo nelle prossime settimane.", 0x7ba79c30, 0x8207dc1a, 0x58e34892, 0x2a558b5c, 0x6aa5a518, "....." },
  [5252] = { "⟦Highborne=Alti Nobili⟧ pentiti", "Parla con Wynd Nightchaser al ⟦Starfall Village=Padiglione Pioggia di Stelle⟧ e chiedi qual è il posto giusto per il ⟦Crystal of Zin-Malor=Cristallo di Zin-Malor⟧.", "Il... il cristallo...\n\nGli Alti Nobili qui sono offuscati dalla loro stessa miseeeria...\n\nIl mio dolorrrre è grande, ma riconosco l'errorrrre di ciò che accadde tanto tempo fa. Anche se non c'è moooodo di cambiare il passato, ora sono in paaaace sapendo che hai recuperato il cristallo di Zin-Malor...\n\nDeeevi restituirlo...\n\nDeeeve essere restituuuito.", "È passato un po' di tempo da quando sei partit<o/a>, {name}. Com'è andata?", "È... quello che penso?", 0x9dd30815, 0xb93b2362, 0x45f52999, 0xf5d97136, 0xbed1d8bc, "....." },
  [5253] = { "Il ⟦Crystal of Zin-Malor=Cristallo di Zin-Malor⟧", "Consegna il ⟦Crystal of Zin-Malor=Cristallo di Zin-Malor⟧ all'arcidruido Fandral Staghelm, a Darnassus.", "Davvero notevole, {name}.\n\nIl cristallo di Zin-Malor non potrà mai essere riportato al tempio che, come sai, giace in rovina. Ma credo che il tuo sforzo per rimediare al male del passato non debba restare senza ricompensa.\n\nCerca l'arcidruido Fandral Staghelm a Darnassus e portagli il cristallo, {name}. Deve stare nelle mani di chi non ne abuserà. A quanto pare, solo un pugno dei più potenti incantatori sarebbe in grado di controllare un simile potere.", "Sì, {race}?", "Ho sentito parlare del ⟦Crystal of Zin-Malor=Cristallo di Zin-Malor⟧: chi lo usa ottiene un incredibile potere arcano, ma solo se ne è davvero degno. Mi colpisce che tu non solo abbia recuperato il cristallo, ma che conosca anche i tuoi limiti e non abbia tentato di usarlo.\n\nGrazie per avermelo portato, {name}. Lo terremo al sicuro, e possano gli spiriti maledetti che un tempo custodivano il cristallo frantumato trovare finalmente pace.", 0xf4d24de4, 0x0d193f8b, 0xc6214ed0, 0x98b629a5, 0xc4680ce0, "....." },
  [5261] = { nil, "Parla con Eagan Peltskinner.", "Eagan Peltskinner cerca qualcuno che vada a caccia di lupi per lui. È una buona notizia, perché ultimamente nella ⟦Northshire Valley=Valle della Contea del Nord⟧ si vedono molti più lupi.\n\nSe ti interessa, parla con Eagan. È sul lato dell'abbazia, a sinistra.", nil, "È vero. Cerco qualcuno che vada a caccia di lupi per me! Sei tu quella persona?", 0x798f9e22, 0x1419ddfe, 0x80800b5d, nil, 0x8ef5cba7, "e..m." },
  [5262] = { "La verità crolla addosso", "Porta la ⟦Head of Balnazzar=Testa di Balnazzar⟧ al duca Nicholas Zverenhoff, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧.", "Cerchi di raccogliere i pensieri mentre la polvere si posa nella sala. Ripensi agli eventi appena accaduti e ancora non riesci a comprendere la gravità della situazione.\n\nIl Gran Crociato della ⟦Scarlet Crusade=Crociata Scarlatta⟧, un demone? E non un demone qualunque, ma il fratello di Varimathras, arcisignore di ⟦Undercity=Sepulcra⟧?\n\nRiponi con cura nella sacca la testa mozzata del signore del terrore. Di certo nessuno crederebbe al tuo racconto senza una prova.\n\nIl duca Nicholas Zverenhoff deve saperlo subito!", "Cos'hai lì, {name}?", "Che cosa significherà per la Crociata? Possibile che sia stata sotto il controllo di questo demone? Che abbia fatto, senza saperlo, da pedina a un male più grande?", 0xdf0dc93f, 0xc0a29039, 0x72ee28db, 0x421c38bd, 0x6b42c078, "....." },
  [5263] = { "Oltre ogni limite", "Avventurati a Stratholme e distruggi Baron Rivendare. Prendi la sua testa e torna dal duca Nicholas Zverenhoff.", "Dimostri un'attitudine naturale per la distruzione, e sai eseguire gli ordini. È raro vedere le due cose insieme. Comincio a pensare che potresti essere un ottimo strumento della giustizia divina.\n\n<Zverenhoff congiunge le mani davanti al viso.>\n\nIl tirapiedi di Kel'Thuzad regna su Stratholme. Dimostrami di essere un campione, il mio campione. Distruggi il barone Rivendare e torna da me con la sua testa.", "Il barone ha ucciso più persone di quante tu ne abbia probabilmente viste in tutta la tua vita.", "Sono passati molti anni da quando ho accolto un campione nelle nostre file. Sei <il/la> prim<o/a> da anni a cui viene concessa udienza con lord Maxwell.", 0xac2caf3c, 0xb6da1920, 0x268218ec, 0x44c81fad, 0xf37aa225, "....." },
  [5264] = { nil, "Parla con lord Maxwell Tyrosus. Si trova all'interno della chiesa.", "Sto per concederti un grande onore, {name}.\n\nLord Maxwell desidera ricompensarti per il servizio reso all'⟦Argent Dawn=Alba d'Argento⟧!\n\nSono anni che Maxwell non concede udienza a degli estranei.", nil, "Hai dimostrato di meritare la nostra alleanza, {name}. Raccoglierai i frutti della tua salda dedizione.", 0x1364f0fb, 0x99ff2cfe, 0x5a4af27e, nil, 0xa162c931, "e..m." },
  [5265] = { "L'Argent Hold", "Apri l'Argent Hold e reclama la tua ricompensa.", "Per anni l'Argent Hold è rimasto chiuso. Nessuno è mai stato degno di entrarvi e prenderne il potere dell'⟦Argent Dawn=Alba d'Argento⟧, fino a oggi.\n\nOra l'Argent Hold è aperto per te, {name}.", nil, "Accidenti...", 0xd610942f, 0xfe201250, 0xc61acfd7, nil, 0x3ff71786, "...m." },
  [5281] = { "Le anime inquiete", "Trova Egan. Sai soltanto che l'ultima volta è stato visto nei dintorni di Stratholme.", "C'è chi morì tragicamente nella caduta di Stratholme. Molti si tolsero la vita, scegliendo di gettarsi tra le innumerevoli fiamme della città in rovina piuttosto che diventare parte del Flagello.\n\nOra vagano per le strade di Stratholme come spiriti inquieti.\n\nDobbiamo aiutarli, {name}!\n\nHo un collaboratore di nome Egan che sta facendo un lavoro miracoloso con fantasmi e anime. Cercalo. Si aggira nella parte orientale delle ⟦Plaguelands=Terre Infette⟧, vicino a Stratholme, per collaudare le sue invenzioni.", nil, "Alla fine Alen ha trovato qualcuno abbastanza coraggioso, eh?", 0xc6ed1aa3, 0x2da086ce, 0x5c19473a, nil, 0x60ee9488, "...m." },
  [5282] = { "Le anime inquiete", "Usa il ⟦Egan's Blaster=Fucile di Egan⟧ sui cittadini fantasma e spettrali di Stratholme. Quando le anime inquiete si liberano dai loro gusci spettrali, usa di nuovo il fucile: saranno libere!\n\nLibera 15 Restless Soul e torna da Egan.", "Traggo la mia forza, la volontà di continuare a vivere e respirare, dall'odio assoluto che provo per il Flagello e per tutto ciò che ha fatto. Non sono però un fanatico. Ci sono quelli, come la ⟦Scarlet Crusade=Crociata Scarlatta⟧, che distruggerebbero i non morti innocenti piuttosto che concedere loro un briciolo di compassione.\n\nIl che mi porta a questo: il mio fucile. Libererà dalle catene le anime tormentate di Stratholme.\n\nUsalo sui fantasmi che infestano le strade saccheggiate. Libera le loro anime.", "La compassione è ciò che ci distingue dagli animali, {name}. Ricordalo...", "<Egan si asciuga una lacrima.>\n\nHai visto mia madre, {name}? L'hai liberata?\n\nSei un fulgido esempio di bontà. Per il disturbo...", 0xc6ed1aa3, 0x6dcd1525, 0x0700bb9e, 0x4b975f5c, 0x940134a9, "....." },
  [5283] = { "L'arte del Fabbro d'Armature", "Per diventare Fabbro d'Armature, devi creare i seguenti oggetti e portarli a Grumnus: 4 Elmo di Mithril Decorato, 2 ⟦Ornate Mithril Boots=Stivali di Mithril Decorati⟧, 1 ⟦Ornate Mithril Breastplate=Pettorale Corazzato di Mithril Decorato⟧.", "Allora hai fatto la scelta furba.\n\nTra me e il vecchio Ironus qui non corre buon sangue. Quel buono a nulla di fabbricante di giocattoli lo sa bene chi sono i veri artigiani da 'ste parti.\n\nLe guerre davvero grandi si vincono con una buona difesa. Quando arriva il momento, nessun attacco ti tirerà fuori dai guai.\n\nBene, mettiamoci al lavoro. Tutto quel che devi fare è dimostrarmi che hai del talento grezzo. Dopodiché ti strapperò di dosso le impurità che ti restano e ti plasmerò in un Fabbro d'Armature. Lo sai fare il mithril decorato, eh?", "Ah, non c'è niente come una bella abbronzatura da forgia. Chi ce l'ha davvero bella lo riconosci dai segni del grembiule.", "Ci siamo, {name}. Dopo questo non si torna più indietro. Non è troppo tardi per diventare un fabbricante di giocattoli, ehm, un Fabbro d'Armi.\n\nConfido che farai la scelta giusta.", 0xc822f11d, 0x0ba86dff, 0x0d0704a7, 0x8f8d67b9, 0x7c6f74a3, "....." },
  [5284] = { "La via del Fabbro d'Armi", "Per diventare Fabbro d'Armi, devi creare i seguenti oggetti e portarli a Ironus: 4 Spadone d'Acciaio Lunare, 4 Ascia Massiva di Ferro, 2 Ascia Pesante di Mithril e 2 Grossa Mazza Nera.", "Da Fabbro d'Armi scoprirai che il più delle volte eroi e avventurieri verranno da te per l'equipaggiamento. A volte il lavoro è insopportabile, ma le ricchezze ripagano ampiamente il mal di schiena e i polmoni pieni di cenere.\n\nEh sì, {name}, sono i Fabbri d'Armi ad avere tutto l'oro!\n\nSe vuoi unirti a noi, dovrai dimostrarmi che sai farmi guadagnare una moneta d'argento o due... volevo dire, dimostrarmi che hai la stoffa per essere <quello/quella> a cui tutti si rivolgono quando serve un'arma di qualità superiore. Al lavoro!", "<Ironus è impegnato a impilare monete d'oro in ordinate pilette.>", "Era ora! Ho dei clienti che aspettano.\n\nDammi quella roba e fa' attenzione. Stai per muovere il primo passo nella tua carriera di Fabbro d'Armi.", 0x7b932606, 0x9df7d17f, 0xf74bbea6, 0xc129794c, 0xe8985a2b, ".....", nil, nil, 0xe475450f, nil, nil },
  [5301] = { "L'arte del Fabbro d'Armature", "Per diventare Fabbro d'Armature, devi creare i seguenti oggetti e portarli a Okothos: 4 Elmo di Mithril Decorato, 2 ⟦Ornate Mithril Boots=Stivali di Mithril Decorati⟧, 1 ⟦Ornate Mithril Breastplate=Pettorale Corazzato di Mithril Decorato⟧.", "Soddisfazione. È ciò che traggo dal martello e dall'incudine. Vedere un fiero guerriero dell'⟦Horde=Orda⟧ protetto dal mio acciaio mi ricorda cosa significa essere vivi. È una dipendenza a cui non oserò mai rinunciare, {name}.\n\nNon posso concederti questa soddisfazione, solo metterti sul sentiero. Come ogni impresa della vita, la via del Fabbro d'Armature è un viaggio.\n\nSe desideri essere <uno/una> dei pochi eletti, ti basta chiedere e ti addestrerò; ma prima dovrai portare a termine un compito.", "Batterò l'acciaio finché non mi verrà tolto anche l'ultimo respiro.", "Questo è l'ultimo passo prima di iniziare la tua nuova carriera di Fabbro d'Armature, {name}. Se vuoi tirarti indietro, questa è la tua ultima occasione. Altrimenti, preparati a una vita di gloria.", 0xc822f11d, 0x03793938, 0xbb62d1b9, 0x989da10a, 0x94984e4c, "....." },
  [5302] = { "La via del Fabbro d'Armi", "Per diventare Fabbro d'Armi, devi creare i seguenti oggetti e portarli a Borgosh: 4 Spadone d'Acciaio Lunare, 4 Ascia Massiva di Ferro, 2 Ascia Pesante di Mithril e 2 Grossa Mazza Nera.", "Un giorno creerò un martello leggendario. Un martello degno di un Capoguerra!\n\nÈ l'opera della mia vita, {name}. La mia passione. Vedo che hai il potenziale per stare tra noi, per essere <uno/una> di noi: un Fabbro d'Armi. Io posso aiutarti a sfruttare quel potenziale.\n\nTi basta portare a termine un compito semplice. Semplice per qualcuno con la tua eccezionale abilità.", "Per la gloria dell'⟦Horde=Orda⟧!", "Questo è l'ultimo passo prima di iniziare la tua nuova carriera di Fabbro d'Armi, {name}. Se vuoi tirarti indietro, questa è la tua ultima occasione. Altrimenti, preparati a essere divorat<o/a> dalla conoscenza!", 0x7b932606, 0xf37e0ec1, 0x7ccbe88d, 0xedc97f2e, 0x106d2037, "....." },
  [5305] = { "Dolce Serenità", "Raggiungi Stratholme e uccidi il Crimson Hammersmith. Recupera il ⟦Crimson Hammersmith's Apron=Grembiule Cremisi di Battimartello⟧ e torna da Lilith.", "Entro le mura dello Scarlet Bastion si trova la dolce Serenità. Il Crimson Hammersmith ne custodisce il progetto a costo della vita. Sconfiggilo e portami il suo grembiule. In cambio ti addestrerò a diventare Fabbro di Martelli.\n\nSappi questo: una volta scelta la via del Fabbro di Martelli, le vie del Fabbro di Spade e del Fabbro d'Asce non saranno più disponibili.", "Il suo grembiule! Dov'è?", "Che tu possa sfondare molti crani, {name}!", 0xbb043493, 0x4bc1109d, 0x17c0f069, 0xd7f14b8a, 0x5d742ffe, "....." },
  [5306] = { "La pietra del serpente della cacciatrice dell'ombra", "Raggiungi i ⟦Blackrock Spire=Bastioni di Roccianera⟧ e uccidi Shadow Hunter Vosh'gajin. Recupera la ⟦Vosh'gajin's Snakestone=Pietra del Serpente di Vosh'gajin⟧ e torna da Kilram.", "Non farti ingannare dalla sua bellezza, {class}. La cacciatrice dell'ombra Vosh'gajin è letale e squilibrata.\n\n<Kilram indica la cicatrice sul suo viso.>\n\nSì, me l'ha fatta lei: una carezza d'amore, l'ha chiamata.\n\nÈ finalmente giunto il momento della vendetta.\n\nTroverai Vosh'gajin nei ⟦Blackrock Spire=Bastioni di Roccianera⟧. Uccidila e torna da me con la sua pietra del serpente. Fallo e ti insegnerò le vie del Fabbro d'Asce.", "La leggenda dice che basta usare una volta la pietra del serpente di Vosh'gajin per mantenere un'ascia affilata come un rasoio per 1000 anni!", "La conoscenza è potere!", 0xc974996f, 0x50e0f33e, 0xc050115a, 0x64eab699, 0x048a33e4, "....." },
  [5307] = { "Corruzione", "Trova il Black Guard Swordsmith a Stratholme e distruggilo. Recupera il ⟦Insignia of the Black Guard=Fregio delle Guardie Nere⟧ e torna da Seril Scourgebane.", "Se sono brusco con te, c'è un motivo. I progetti per forgiare la grande lama Corruzione sono stati rubati dalle Guardie Nere, le unità scheletriche d'élite del barone Rivendare.\n\nSì, il barone Rivendare di Stratholme.\n\nIl fabbro di spade delle Guardie Nere ora custodisce quei progetti con la sua... non vita.\n\nUccidilo, riportami la prova dell'impresa e ti addestrerò nelle vie del Fabbro di Spade.", "Hai forse dimenticato il compito che ti è stato affidato, {name}?", "Dovrebbe essere ovvio che la spada è sempre la scelta migliore.", 0x99ec2eb2, 0x7570bf3f, 0x12378b72, 0xfe7aba2d, 0xa91d13af, "....." },
  [5321] = { "Il dormiente si è svegliato", "Scorta Kerlonian Evershade verso sud lungo la strada fino a Liladris Moonriver, per ritrovare la sua borsa a ⟦Darkshore=Rivafosca⟧.", "Ero diretto all'⟦Maestra's Post=Accampamento di Maestra⟧ per incontrare Liladris Moonriver, ma ho deciso di fermarmi qui per un sonnellino. Da quando mi sono risvegliato dal Sogno di Smeraldo ho sempre tanto sonno...\n\n<sbadiglia>\n\nE non riesco a trovare le mie cose da nessuna parte! Ti dispiacerebbe aiutarmi a ritrovarle?\n\nSo che l'⟦Maestra's Post=Accampamento di Maestra⟧ è a sud di qui, lungo la strada di ⟦Ashenvale=Valtetra⟧. Venivo da quella parte...\n\nUn'ultima cosa: potrei addormentarmi, quindi se dovessi svegliarmi, usa il mio corno. Lo trovi nel forziere qui.", "Kerlonian è arrivato?", "Oh, sono così felice che Kerlonian ce l'abbia fatta! E di sicuro lo troverò addormentato da qualche parte qui intorno, vero?\n\nGrazie per avergli mostrato la strada, {name}.", 0xaa562d09, 0x0598ad83, 0xf9beb9c8, 0x5a42fe8b, 0x57f32af8, "....." },
  [5341] = { "Il patrimonio della famiglia Barov", "Avventurati a Scholomance e recupera il patrimonio della famiglia Barov. Il patrimonio è composto da quattro atti: l'⟦The Deed to Caer Darrow=Atto di Caer Darrow⟧, l'⟦The Deed to Brill=Atto di Brill⟧, l'⟦The Deed to Tarren Mill=Atto di Mulino di Tarren⟧ e l'⟦The Deed to Southshore=Atto di Riva del Sud⟧. Torna da Alexi Barov quando avrai portato a termine il compito.", "A Scholomance giace il patrimonio della famiglia Barov. Io, Alexi Barov, sono uno degli ultimi due eredi rimasti della casata Barov. L'altro è mio fratello Weldon.\n\nWeldon, quel miserabile codardo, fuggì durante la guerra e così conservò la sua inutile esistenza di umano.\n\nOra cerca gli atti per poter reclamare il patrimonio per sé. Recupera gli atti prima di mio fratello e ti renderò ricc<o/a> oltre i tuoi sogni più sfrenati!", "Chinati in mia presenza, {race}. Dopotutto io sono un nobile, e tu <un/una> contadin<o/a> senza un soldo.", "Ottimo lavoro, {race}. Ora, a mettere al sicuro la mia eredità...", 0x3f8c2d6a, 0x778324c3, 0x2ae2fc6c, 0x1af3f7b7, 0xaf1c7186, "....." },
  [5342] = { "L'ultimo Barov", "Raggiungi l'⟦Chillwind Camp=Accampamento di Ventofreddo⟧, territorio dell'⟦Alliance=Alleanza⟧, e assassina Weldon Barov. Prendi la sua testa e torna da Alexi Barov.\n\nFai attenzione: probabilmente Weldon sarà ben protetto da quella feccia dell'⟦Alliance=Alleanza⟧.", "Naturalmente, finché mio fratello è vivo, potrebbe sorgere qualche contesa su chi sia il principale beneficiario del patrimonio di famiglia. Non può essere.\n\nSpero che la gentaglia come te non disdegni un piccolo omicidio a sangue freddo.\n\nÈ un compito semplice, e mi aspetto che tu lo porti a termine; sempre che tu voglia la tua ricompensa.\n\nWeldon se ne sta sotto la protezione dell'⟦Alliance=Alleanza⟧ all'⟦Chillwind Camp=Accampamento di Ventofreddo⟧, a est. Uccidilo e riportami la sua testa.\n\n<Alexi sbadiglia.>\n\nE ora sbrigati.", "Assicura il mio patrimonio e avrai la tua parte del bottino.", "Magnifico! Ora solo io possiedo il potere e il patrimonio della casata Barov!\n\n<Alexi ti lancia una grossa borsa.>\n\nE tieniti il resto, sudicio animale.", 0xd587dffb, 0x1d98604b, 0x40697ac8, 0xd7805028, 0xaf7ed43d, "....." },
  [5343] = { "Il patrimonio della famiglia Barov", "Avventurati a Scholomance e recupera il patrimonio della famiglia Barov. Il patrimonio è composto da quattro atti: l'⟦The Deed to Caer Darrow=Atto di Caer Darrow⟧, l'⟦The Deed to Brill=Atto di Brill⟧, l'⟦The Deed to Tarren Mill=Atto di Mulino di Tarren⟧ e l'⟦The Deed to Southshore=Atto di Riva del Sud⟧. Torna da Weldon Barov quando avrai portato a termine il compito.", "Il mio caro fratello Alexi. Che sciocco sono stato a risparmiargli la vita. Ho guardato in faccia il nemico, uno dei non morti, e l'ho lasciato vivere.\n\n<Weldon sputa.>\n\nOra cerca la MIA eredità. Questo non deve accadere, punto e basta.\n\nTrova gli atti della mia famiglia prima che quel verme schifoso ci metta sopra le sue mani ossute, e ti ricompenserò con immense ricchezze. Si trovano tra le rovine di Scholomance. Sbrigati!", "Assicura il mio futuro e io assicurerò il tuo.", "Devo chiederti un ultimo compito, {name}.", 0x3f8c2d6a, 0x62fcd15e, 0xa8d67690, 0xfce3d6b8, 0x4579e737, "....." },
  [5344] = { "L'ultimo Barov", "Raggiungi la Granbarricata, territorio dell'⟦Horde=Orda⟧, e assassina Alexi Barov. Prendi la sua testa e torna da Weldon Barov.\n\nFai attenzione: probabilmente Alexi sarà ben protetto da quella lordura dell'⟦Horde=Orda⟧.", "Recuperati gli atti, resta una sola cosa da fare. Alexi deve morire. Con lui morto, non dovrò mai più temere che una banda di mercenari senza scrupoli venga a cercare la mia testa.\n\nÈ un compito semplice. Alexi si nasconde sotto la protezione dell'⟦Horde=Orda⟧, alla Granbarricata.\n\nNo, non mi aspetto che tu ti avvicini e lo uccida e basta: voglio la sua testa! Come la otterrai... beh, quella parte spetta a te. Un comportamento del genere è al di sotto di chi ha ricevuto la mia nobile educazione.", "Vuoi essere pagat<o/a>, o no?", "Che giorno glorioso! Finalmente la piaga della casata Barov è stata eliminata e il mio patrimonio è al sicuro!\n\nPrendi questo e sparisci dalla mia vista, villano.", 0xd587dffb, 0xc4780c72, 0x91978771, 0xcd631cdc, 0xf688396f, "....." },
  [5361] = { "Albero genealogico", "Consegna il ⟦Cliffwatcher Longhorn Report=Rapporto del Guardiacolli Corno Lungo⟧ a Nataka Longhorn al ⟦Ghost Walker Post=Presidio delle Ombre⟧, in ⟦Desolace=Desolanda⟧.", "Mio fratello Nataka è di stanza al ⟦Ghost Walker Post=Presidio delle Ombre⟧, laggiù in ⟦Desolace=Desolanda⟧. Vorrei chiederti... potresti consegnargli questo rapporto da parte mia? È passato un anno dall'ultima volta che gli ho scritto, da allora c'è stata un'insolita attività dei centauri e deve esserne informato.\n\nRaggiungi le Vette di ⟦Stonetalon=Petrartiglio⟧ a nord del ⟦Crossroads=Crocevia⟧, poi dirigiti a ovest nella ⟦Charred Vale=Valle Bruciata⟧. Da lì prosegui a sud verso ⟦Desolace=Desolanda⟧; lì troverai una strada che porta a sud fino al ⟦Ghost Walker Post=Presidio delle Ombre⟧.", "Che notizie hai, {class}? Ah, un messaggio di mio fratello, dici? Be', allora dammi il rapporto!", "Non so che legame tu abbia con mio fratello, ma pare che si fidi di te, {class}.\n\nSono Nataka Longhorn e ti do il benvenuto al ⟦Ghost Walker Post=Presidio delle Ombre⟧: abbiamo molto bisogno di <un/una> {class}! Parla con gli altri, forse qui c'è bisogno di te.", 0x75bbe09a, 0x851bfa05, 0x91bf7cbe, 0xde674e8b, 0xffb232f7, "....." },
  [5381] = { "La ⟦Hand of Iruxos=Mano di Iruxos⟧", "Recupera la ⟦Demon Box=Scatola Demoniaca⟧ dalla ⟦Thunder Axe Fortress=Fortezza Ascia del Tuono⟧ e riportala, insieme al ⟦Demon Pick=Piccone Demoniaco⟧, a Taiga Wisemane a ⟦Shadowprey Village=Predombra⟧.", "Le ⟦Burning Blade=Lame Ardenti⟧ possiedono la ⟦Demon Box=Scatola Demoniaca⟧. Al suo interno si trova la potente ⟦Hand of Iruxos=Mano di Iruxos⟧. Le ⟦Burning Blade=Lame Ardenti⟧ la usano per aprire portali demoniaci alla ⟦Mannoroc Coven=Congrega di Mannoroc⟧. Dobbiamo fermare l'ondata di demoni che entra nel nostro mondo, {name}!\n\nUsa questo Piccone Demoniaco sul cristallo rosso nella ⟦Thunder Axe Fortress=Fortezza Ascia del Tuono⟧ per accedere alla ⟦Demon Box=Scatola Demoniaca⟧.", "{name}, hai la ⟦Demon Box=Scatola Demoniaca⟧?", "Ah, la ⟦Demon Box=Scatola Demoniaca⟧. Dammela, {class}, e la aprirò... rivelandoti così la ⟦Hand of Iruxos=Mano di Iruxos⟧.", 0xd85b8727, 0xbcfb110b, 0x04495abb, 0x3e8e7805, 0x7e8cdab2, "....." },
  [5382] = { "Il dottor Theolen Krastinov, il Macellaio", "Trova Doctor Theolen Krastinov a Scholomance. Distruggilo, poi brucia i Remains of Eva Sarkhoff e i Remains of Lucien Sarkhoff. Torna da Eva Sarkhoff quando il compito sarà portato a termine.", "Krastinov è responsabile della morte di migliaia di persone. Deve essere punito, bisogna fare giustizia.\n\nTrovalo e infliggigli l'agonia che ha inflitto a innumerevoli innocenti. Quando sarà distrutto, brucia i nostri resti. Riducili in cenere, {name}.", "Il ⟦The Butcher=Macellaio⟧ va fermato!", "Sento il mio spirito guarire, {name}. Hai reso un grande servizio a me e a mio marito, ma sono certa che ci sia altro da fare.", 0xd336bb57, 0x9d7ac22d, 0x56eccba7, 0x2431a358, 0x810a97d6, "....." },
  [5383] = { "La ⟦Krastinov's Bag of Horrors=Borsa degli Orrori di Krastinov⟧", "Porta la Borsa degli Orrori a Eva Sarkhoff, a Caer Darrow.", "Apri la borsa e scopri diversi strumenti di tortura. Tra l'armamentario, un oggetto strano attira la tua attenzione: una fiala di sangue, ancora calda al tatto.\n\nPensi che i Sarkhoff potrebbero essere interessati alla tua scoperta.", nil, nil, 0xc11cac70, 0xdaf3716e, 0x4c9e8ccd, nil, nil, "...mm" },
  [5384] = { "Kirtonos l'Araldo", "Torna a Scholomance con il Blood of Innocents. Trova il portico e metti il Blood of Innocents nel braciere. Kirtonos verrà a banchettare con la tua anima.\n\nCombatti con valore, non cedere di un passo! Distruggi Kirtonos e torna da Eva Sarkhoff.", "Ci siamo, {name}.\n\n<Eva indica la fiala dentro la borsa.>\n\nIl sangue degli innocenti. Il sangue più puro, usato per placare il padrone di Krastinov.\n\nÈ con questo sangue che Kirtonos può essere evocato. È con questo sangue, dunque, che Kirtonos deve essere distrutto.\n\nPorta il sangue sul portico. Ponilo sul braciere. Kirtonos verrà: non può resistere. Quando apparirà, scatena su di lui la furia e l'ira di mille morti innocenti.\n\nSe ci riuscirai, otterrai molto più della nostra gratitudine.", "Fai attenzione, Kirtonos è un combattente esperto.", "Con la morte di Kirtonos si chiude un capitolo dell'orribile storia di Scholomance. C'è però altro da fare. Anche altri, qui, ora sanno delle tue imprese coraggiose. Prendi questo, {name}. È un frammento della nostra stessa essenza. Ti permetterà di comunicare con le altre anime perdute di Caer Darrow.", 0x85ddd998, 0xf02984ed, 0x63de25cc, 0xfb2dedfa, 0x1e8a60da, "....." },
  [5385] = { "I ⟦Remains of Trey Lightforge=Resti di Trey Forgialuce⟧", "Riporta i ⟦Remains of Trey Lightforge=Resti di Trey Forgialuce⟧ a Jessir Moonbow, a ⟦Felwood=Vilbosco⟧.", "Raccogli il sacco con cura e ti prepari a tornare da Jessir Moonbow, al confine tra ⟦Felwood=Vilbosco⟧ e ⟦Ashenvale=Valtetra⟧. Speri che al paladino vengano resi i giusti onori, una volta consegnati i suoi resti ai suoi amici.", "Com'è andata a Jaedenar, {name}?", "Ce l'hai fatta! Sia lodata Elune, e qualunque potere tu veneri, {name}. Oggi hai compiuto un gesto onorevole e nobile. Sono certo che Arko'narin sarà felice che tu non solo abbia trovato il tempo di salvarla, ma anche di uccidere la creatura che ha torturato uno dei suoi migliori amici.\n\nVorrei poter fare di più per te, ma ti prego, prendi questo.", 0x90368ba7, 0x6d8aa087, 0x124f7288, 0xce9d5820, 0x62e2ed22, "....." },
  [5386] = { "Il pescato del giorno", "Parla con Jinar'Zillen a ⟦Shadowprey Village=Predombra⟧, poi porta 2 Pesce Ventrerosso a Nataka Longhorn.", "Qui al ⟦Ghost Walker Post=Presidio delle Ombre⟧ manca da tempo il profumo del pesce cotto. I troll di ⟦Shadowprey Village=Predombra⟧ sono i migliori a pescare... ma purtroppo, con tutte le attività dei centauri, ho poco tempo per andare dai troll. Mmh...\n\nFammi un favore e va' fino a ⟦Shadowprey Village=Predombra⟧. Parla con il pescatore del posto, Jinar'Zillen, e riportami il mio preferito, il pesce Ventrerosso. La strada a sud di qui ti porterà a ovest, fino al villaggio troll.", "Mi formicola lo zoccolo e mi viene l'acquolina in bocca quando penso al pesce Ventrerosso fritto... Ne hai un po' con te?", "Sei la mia salvezza, {name}! Questi pesci Ventrerosso sembrano quasi abbastanza buoni da mangiarli crudi.\n\n<Nataka comincia a sbavare.>\n\nEcco qua: scegli uno di questi oggetti come pagamento per il pesce.", 0x08798148, 0xbfcef53c, 0x7d13a9e3, 0x565d4e36, 0xf4003637, "....." },
  [5401] = { "⟦Argent Dawn Commission=Distintivo dell'Alba d'Argento⟧", nil, nil, nil, "Tutti coloro che combattono il male per conto dell'⟦Argent Dawn=Alba d'Argento⟧ devono indossare il nostro distintivo. Indossarlo ti darà diritto a reclamare le ricompense che i nostri intendenti hanno da offrire.\n\nFinché porterai il distintivo, potrai ottenere Pietre del Flagello dai servitori del Flagello uccisi: sono insegne che a volte portano con sé. Procurati queste insegne e portamele. Per ogni serie che consegnerai, riceverai il nostro segno d'eroismo: l'⟦Argent Dawn Valor Token=Emblema del Valore dell'Alba d'Argento⟧.\n\nCompi il tuo destino, {class}: unisciti oggi stesso alla lotta!", 0x1122fda4, nil, nil, nil, 0x33c0d9c1, ".mmm." },
  [5405] = { "⟦Argent Dawn Commission=Distintivo dell'Alba d'Argento⟧", nil, nil, nil, "Tutti coloro che combattono il male per conto dell'⟦Argent Dawn=Alba d'Argento⟧ devono indossare il nostro distintivo. Indossarlo ti darà diritto a reclamare le ricompense che i nostri intendenti hanno da offrire.\n\nFinché porterai il distintivo, potrai ottenere Pietre del Flagello dai servitori del Flagello uccisi: sono insegne che a volte portano con sé. Procurati queste insegne e portamele. Per ogni serie che consegnerai, riceverai il nostro segno d'eroismo: l'⟦Argent Dawn Valor Token=Emblema del Valore dell'Alba d'Argento⟧.\n\nCompi il tuo destino, {class}: unisciti oggi stesso alla lotta!", 0x1122fda4, nil, nil, nil, 0x33c0d9c1, ".mmm." },
  [5441] = { "Peoni pigri", "Usa il ⟦Foreman's Blackjack=Manganello del Caposquadra⟧ sui Lazy Peon quando dormono. Sveglia 5 peoni, poi riporta il ⟦Foreman's Blackjack=Manganello del Caposquadra⟧ al caposquadra Thazz'ril nella ⟦Valley of Trials=Valle delle Sfide⟧.", "Maledetti peoni! Lavorano sodo per raccogliere legname dagli alberi della valle, ma schiacciano sempre un pisolino! Mi serve qualcuno che mi aiuti a tenerli in riga.\n\nSembri <il/la> {race} giust<o/a> per questo compito. Ecco, prendi questo manganello e usalo su tutti i peoni pigri che trovi a dormire sul lavoro. Una bella botta e torneranno subito al lavoro! Riportami il manganello quando hai finito.\n\nSchifosi peoni fannulloni...", "Buoni a nulla, pigri...\n\nEh? Hai il mio manganello? Hai beccato qualche peone che dormiva sul lavoro?!", "Bene, bene. Magari la prossima volta ci penseranno due volte prima di fare i fannulloni! Grazie per l'aiuto!", 0x066b4dc8, 0x0e9a3950, 0x5204e085, 0x7ba6faf0, 0x403f028b, "....." },
  [5461] = { "L'umano, Ras Frostwhisper", "Raggiungi gli ⟦Arathi Highlands=Altopiani d'Arathi⟧, tra le rovine di Stromgarde. Cerca a Stromgarde un ⟦Keepsake of Remembrance=Grimorio della Rimembranza⟧. Se trovi un oggetto del genere, riportalo al magistrato Marduke.", "I non morti temono la vita proprio come i vivi temono la morte. Non è insolito che un non morto senziente distrugga ogni traccia della sua vita precedente dopo la trasformazione.\n\nPurtroppo, per creare un manufatto capace di riportare Ras Frostwhisper allo stato mortale, ci serve un pegno dei suoi anni tra i vivi.\n\nDevi avventurarti nella città in rovina di Stromgarde, la patria di Frostwhisper, e cercare un oggetto del genere. Che la fortuna ti accompagni, {name}.", "Un Grimorio della Rimembranza è una scoperta rara, {name}.", "Dubitavo che un oggetto del genere potesse esistere. Questo apre senz'altro un'opportunità incredibile, che non dobbiamo sprecare.\n\nPreparati, {name}, perché ciò che sto per chiederti ti porterà nelle profondità dell'inferno.", 0x725cb6ce, 0xa0f64578, 0xf5fbe9d1, 0xf96f05b9, 0x2a862c05, "....." },
  [5462] = { "Il morente, Ras Frostwhisper", "Raggiungi la Cappella della Luce, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧, e cerca Leonid Barthalomew il Reverito. Mostragli il ⟦Keepsake of Remembrance=Grimorio della Rimembranza⟧ e raccontagli tutto ciò che hai scoperto.", "Su un suolo contaminato, il pegno deve essere sintonizzato.\n\nSi dice che sia stato a Stratholme che Frostwhisper si arrese al Re dei Lich. Su quel suolo insanguinato diede la vita, liberamente e con uno scopo, per diventare uno di coloro che non muoiono.\n\nÈ quel suolo che bisogna trovare.\n\nC'è qualcuno, un non morto dissidente del Flagello, liberato dalla Regina delle Banshee ma fedele alla causa dell'⟦Argent Dawn=Alba d'Argento⟧. Trovalo: Leonid Barthalomew il Reverito. Forse ne sa di più. Cerca la Cappella della Luce, {name}.", "Non fare domande di cui non vuoi conoscere le risposte.", "<Leonid esamina il pegno.>\n\nIl tuo dilemma risveglia ricordi che speravo non riaffiorassero mai.", 0x1d8e2a3d, 0x9ac8a12d, 0xd52673b1, 0xfc4fa87f, 0x68a55fa4, "....." },
  [5463] = { nil, "Raggiungi Stratholme e trova Menethil's Gift. Posa il ⟦Keepsake of Remembrance=Grimorio della Rimembranza⟧ sul suolo profano.", "Vidi l'umano Ras Frostwhisper promettere la sua anima immortale al Re dei Lich. Si portò il pugnale alla gola e, sorridendo, si tagliò da un orecchio all'altro. Il suo corpo crollò dentro i confini del pentagramma. Il Re dei Lich si chinò sul mago caduto e con un solo gesto nacque Ras Frostwhisper il lich.\n\n<Leonid fissa il terreno e poi alza lo sguardo su di te.>\n\nSì, {race}, ricordo. Ciò che cerchi ha un nome: Menethil's Gift. Il suolo benedetto dal Re dei Lich, terra santa per il Flagello.", "La zona attorno a Menethil's Gift è straordinariamente fredda.", "Posi il pegno sul suolo contaminato.", 0x07faaca7, 0x12bcf3f2, 0x04b9599d, 0xddaadd82, 0x8a0ae085, "e...." },
  [5464] = { nil, "Porta il ⟦Soulbound Keepsake=Pegno Vincolato⟧ a Leonid Barthalomew, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧.", "L'anima del caduto si aggrappa a ciò che rappresenta la sua vita passata e trasforma l'oggetto in un pegno vincolato. Raccogli l'oggetto e lo riponi nella sacca.", "<Leonid rabbrividisce.>", "Come l'anima si è aggrappata al pegno, così si aggrapperà alla forma fisica di Ras Frostwhisper.", 0x07faaca7, 0x495cca65, 0x05eeb523, 0xbb86ab9a, 0xca81a204, "e...." },
  [5465] = { "Il ⟦Soulbound Keepsake=Pegno Vincolato⟧", "Torna dal magistrato Marduke a Caer Darrow. Mostragli il ⟦Soulbound Keepsake=Pegno Vincolato⟧.", "Torna da Marduke con il pegno, {name}. Ti spiegherà come usarlo.", "Hai compiuto l'impossibile?", "Ero certo che ti saresti unit<o/a> a me come un altro spirito sventurato.", 0x602959cb, 0x94d112db, 0x42e159c7, 0x98d8ddc5, 0x7b4d9f54, "....." },
  [5466] = { "Il lich, Ras Frostwhisper", "Trova Ras Frostwhisper a Scholomance. Quando l'avrai trovato, usa il ⟦Soulbound Keepsake=Pegno Vincolato⟧ sul suo volto di non morto. Se riuscirai a riportarlo allo stato mortale, abbattilo e recupera la ⟦Human Head of Ras Frostwhisper=Testa Umana di Ras Soffiogelo⟧. Riporta la testa al magistrato Marduke.", "Resta un solo compito, {name}. Affronta il lich, Ras Frostwhisper, nella sua tana.\n\nUsa il potere del pegno contro la bestia, e sii implacabile! Sopporta i colpi che la bestia, dimenandosi, di certo ti scaglierà addosso. Non cedere al dolore!\n\nQuando il rituale sarà completo, Ras tornerà mortale. È in quel momento che dovrà essere ucciso. Abbattilo e prendi la sua testa umana.", "Porti il peso di diecimila anime inquiete, {name}.", "Diecimila anime gridano all'unisono, {name}! Hai inferto un colpo mortale al Flagello e ai suoi padroni.", 0xe16ff4fd, 0xf3ab1755, 0x8037676e, 0xf7db9910, 0x202c3397, "....." },
  [5481] = { "L'incarico di Gordo", "Raccogli 3 ⟦Gloom Weed=Erba Tenebrosa⟧ e consegnale all'apprendista speziale Holland, nel cimitero di Brill.", "Padrone vuole erbe. Noi ha mani grosse e non bravi a raccogliere. Tu aiuta noi e noi non fa male a te. Noi serve erba tenebrosa. Tante erbe qui intorno e vicino a strada.\n\nQuando tu ha erba tenebrosa tu porta a Padrone Holland in cimitero di Brill.", "Dov'è quell'inutile abominio? O hai quello che mi serve, o faresti meglio a tornare là fuori a cercarlo.", "Cos'è questa? Erba tenebrosa?! Non so che farmene dell'erba tenebrosa! Quell'ammasso di carne senza cervello se ne sta là fuori a raccogliere margherite e a convincere la Signora sa quanti sprovveduti come te a fare lo stesso. Senza offesa.\n\nE va bene, ormai sei qui ed è questo che conta. Visto che non mi metterò a spiegare le cose a quell'abominio, che ne dici di raccogliere tu quello che mi serve davvero... l'erba funesta!", 0x96395a4e, 0xb936c9b6, 0x6ed41602, 0x7b54f2f7, 0x6ac66def, "....." },
  [5482] = { "⟦Doom Weed=Erba del Fato⟧", "Raccogli 10 ⟦Doom Weed=Erba del Fato⟧ e consegnale allo speziale apprendista Holland.", "Quindi capisci in che situazione mi trovo, {name}. Quella cosa là fuori raccoglie le erbe sbagliate! Se mi procuri ciò che mi serve, ne varrà la pena. Riportami abbastanza Erba del Fato e ti darò una ricompensa adeguata.\n\nA quanto ne so, amano infestare la flora vicino alla fossa comune, a nord del cimitero di Brill. Sbrigati, e fai attenzione agli gnoll della zona.", "Spero che sia una cosa importante. Confido che tu abbia tutta l'Erba del Fato che mi serve?", "Ah, la mia Erba del Fato. Eccellente!\n\n<Lo speziale apprendista Holland si sfrega le mani avidamente.>\n\nMi torneranno molto utili. Oggi hai reso a me, ehm, alla Dama, un ottimo servizio, {name}. Come promesso, ecco la ricompensa che meriti.", 0xba531ee7, 0x953d45bb, 0xba6bedd2, 0xee8731ae, 0xb65d1bca, "....." },
  [5501] = { "Il collezionista di ossa", "Porta 10 Osso di Kodo dal ⟦Kodo Graveyard=Cimitero dei Kodo⟧ a Bibbly F'utzbuckle al ⟦Kormek's Hut=Capanno di Kormek⟧.", "Qui siamo seduti su una miniera d'oro, te lo dico io: una miniera d'oro! Le ossa di kodo cambieranno il mondo per sempre... Ho clienti che ci fanno mobili, strumenti musicali e perfino polvere esplosiva.\n\nC'è una carovana che passa a ritirare le mie ossa di kodo e poi le vende a ⟦Shadowprey Village=Predombra⟧. Se vai al Cimitero dei Kodo, a sud di qui, e mi porti dieci ossa di kodo, ti darò qualcosa in cambio. Affare fatto?", "Hai le ossa? La carovana arriverà da un momento all'altro. Mi servono solo altre dieci ossa di kodo per toccare il record della mia carriera. Il record della mia carriera, te lo dico io!", "Ah, che bello! Le mie ossa!\n\nNon vedo l'ora che i tizi a casa vedano la mia faccia sulla copertina di Goblin'preneur. Sarò il goblin più ricco del mondo... e pensare che il mio insegnante di educazione fisica diceva che non sarei mai diventato nessuno!", 0xa1177fd1, 0x6c4f8089, 0x73788e03, 0xf2c18490, 0xf47c7c14, "....." },
  [5502] = { "Un tutore dell'⟦Horde=Orda⟧", "Riporta il tuo protetto all'orfanotrofio di Orgrimmar consegnando il ⟦Orcish Orphan Whistle=Fischietto dell'Orfano Orco⟧ alla matrona degli orfani Battlewail, nella ⟦Valley of Honor=Valle dell'Onore⟧.", "Sei stat<o/a> così gentile con me, {name}. Non avrei mai pensato di divertirmi così tanto durante la Children's Week. Grazie. Non sarò triste per quello che mi è successo: i miei genitori mi dicevano sempre di superare qualsiasi cosa brutta capiti. Sarò un eroe... proprio come te.\n\nMi dispiace dirlo, ma è ora che torni a casa. Torniamo indietro e dirò alla matrona che persona fantastica sei!", "È un piacere rivederti, {name}. Ti sei occupat<o/a> dei compiti che ti sei offert<o/a> di svolgere durante la Children's Week?", "Che gli spiriti ti benedicano, {name}. Hai fatto per Grunth più di quanto la maggior parte della gente penserebbe mai di fare per lui. Grazie: sei l'esempio perfetto di cosa significhi essere un eroe dell'⟦Horde=Orda⟧.\n\nTi prego, se trovi il tempo, torna a trovarci. So che a Grunth farebbe piacere, e anche a me.\n\nGrunth si è divertito tantissimo con te, {name}. Voleva regalarti uno dei suoi animaletti preferiti perché ti ricordi di lui.", 0xfc045e42, 0x994306c0, 0xe237b3e0, 0xfd180aa5, 0x56ea92c2, "....." },
  [5503] = { "⟦Argent Dawn Commission=Distintivo dell'Alba d'Argento⟧", nil, nil, nil, "Tutti coloro che combattono il male per conto dell'⟦Argent Dawn=Alba d'Argento⟧ devono indossare il nostro distintivo. Indossarlo ti darà diritto a reclamare le ricompense che i nostri intendenti hanno da offrire.\n\nFinché porterai il distintivo, potrai ottenere Pietre del Flagello dai servitori del Flagello uccisi: sono insegne che a volte portano con sé. Procurati queste insegne e portamele. Per ogni serie che consegnerai, riceverai il nostro segno d'eroismo: l'⟦Argent Dawn Valor Token=Emblema del Valore dell'Alba d'Argento⟧.\n\nCompi il tuo destino, {class}: unisciti oggi stesso alla lotta!", 0x1122fda4, nil, nil, nil, 0x754f7807, ".mmm." },
  [5504] = { "I Ripari dell'Alba", "Porta 10 Emblema del Valore dell'⟦Argent Dawn=Alba d'Argento⟧ a Hasana, quartiermastro della Granbarricata, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧.", "Il tuo servizio all'⟦Argent Dawn=Alba d'Argento⟧ merita un encomio, {name}. Sei davvero reverit<o/a> tra noi. Mi è stato concesso di mettere a tua disposizione per l'acquisto uno degli oggetti più preziosi dell'Alba: i nostri ripari di resistenza alla magia.\n\nApplicando un riparo al tuo spallaccio attuale aumenterai la tua resistenza ai poteri della magia in uno di cinque modi possibili. Come segno di costante dedizione alla nostra causa, chiedo non meno di dieci dei nostri emblemi del valore in cambio dell'accesso a questi ripari.", "Ah, nobile {class}! Hai portato gli emblemi del valore che ti sono stati chiesti? Quando me li consegnerai, metterò a tua disposizione per l'acquisto i nostri vari ripari.", "Eccezionale: il tuo tributo all'Alba è stato debitamente registrato, {name}. Fatto questo, è un piacere mettere a tua disposizione per l'acquisto i nostri ripari. Finché manterrai il tuo attuale rango presso di noi, potrai acquistare questi ripari da qualunque quartiermastro autorizzato dell'⟦Argent Dawn=Alba d'Argento⟧.\n\nPer l'Alba, <fratello/sorella> mi<o/a>!", 0xb4b72c15, 0xb6bfb5a2, 0x2745a134, 0xaa8f1881, 0x152a39f1, "....." },
  [5505] = { "La chiave di Scholomance", nil, nil, nil, "Ecco qui, {name}: la Chiave Universale completa. Sono quanto più certo si possa essere che questa chiave ti permetterà di entrare a Scholomance. C'è un solo modo per esserne assolutamente sicuri, però. Non perdere tempo e provala, dico io.\n\nBuona fortuna, potente <eroe/eroina>. Che tu possa continuare a portare la luce nelle tenebre!", 0x5fcf7b72, nil, nil, nil, 0x779e067f, ".mmm." },
  [5507] = { "I Ripari dell'Alba", "Porta 10 Emblema del Valore dell'⟦Argent Dawn=Alba d'Argento⟧ a Lightspark, quartiermastro dell'⟦Chillwind Camp=Accampamento di Ventofreddo⟧, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧.", "Il tuo servizio all'⟦Argent Dawn=Alba d'Argento⟧ merita un encomio, {name}. Sei davvero reverit<o/a> tra noi. Mi è stato concesso di mettere a tua disposizione per l'acquisto uno degli oggetti più preziosi dell'Alba: i nostri ripari di resistenza alla magia.\n\nApplicando un riparo al tuo spallaccio attuale aumenterai la tua resistenza ai poteri della magia in uno di cinque modi possibili. Come segno di costante dedizione alla nostra causa, chiedo non meno di dieci dei nostri emblemi del valore in cambio dell'accesso a questi ripari.", "Ah, nobile {class}! Hai portato gli emblemi del valore che ti sono stati chiesti? Quando me li consegnerai, metterò a tua disposizione per l'acquisto i nostri vari ripari.", "Eccezionale: il tuo tributo all'Alba è stato debitamente registrato, {name}. Fatto questo, è un piacere mettere a tua disposizione per l'acquisto i nostri ripari. Finché manterrai il tuo attuale rango presso di noi, potrai acquistare questi ripari da qualunque quartiermastro autorizzato dell'⟦Argent Dawn=Alba d'Argento⟧.\n\nPer l'Alba, <fratello/sorella> mi<o/a>!", 0xb4b72c15, 0x477ea26c, 0x2745a134, 0xaa8f1881, 0x152a39f1, "....." },
  [5511] = { "La chiave di Scholomance", nil, nil, nil, "Ecco qui, {name}: la Chiave Universale completa. Sono quanto più certo si possa essere che questa chiave ti permetterà di entrare a Scholomance. C'è un solo modo per esserne assolutamente sicuri, però. Non perdere tempo e provala, dico io.\n\nBuona fortuna, potente <eroe/eroina>. Che le tue vittorie continuino a portarti fama e potere mentre devasti Scholomance!", 0x5fcf7b72, nil, nil, nil, 0x1e97a381, ".mmm." },
  [5513] = { "I Ripari dell'Alba", "Porta 10 Emblema del Valore dell'⟦Argent Dawn=Alba d'Argento⟧ al quartiermastro Breechlock alla ⟦Light's Hope Chapel=Cappella della Luce⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧.", "Il tuo servizio all'⟦Argent Dawn=Alba d'Argento⟧ merita un encomio, {name}. Sei davvero reverit<o/a> tra noi. Mi è stato concesso di mettere a tua disposizione per l'acquisto uno degli oggetti più preziosi dell'Alba: i nostri ripari di resistenza alla magia.\n\nApplicando un riparo al tuo spallaccio attuale aumenterai la tua resistenza ai poteri della magia in uno di cinque modi possibili. Come segno di costante dedizione alla nostra causa, chiedo non meno di dieci dei nostri emblemi del valore in cambio dell'accesso a questi ripari.", "Ah, nobile {class}! Hai portato gli emblemi del valore che ti sono stati chiesti? Quando me li consegnerai, metterò a tua disposizione per l'acquisto i nostri vari ripari.", "Eccezionale: il tuo tributo all'Alba è stato debitamente registrato, {name}. Fatto questo, è un piacere mettere a tua disposizione per l'acquisto i nostri ripari. Finché manterrai il tuo attuale rango presso di noi, potrai acquistare questi ripari da qualunque quartiermastro autorizzato dell'⟦Argent Dawn=Alba d'Argento⟧.\n\nPer l'Alba, <fratello/sorella> mi<o/a>!", 0xb4b72c15, 0xd9bf0407, 0x2745a134, 0xaa8f1881, 0x152a39f1, "....." },
  [5514] = { "Stampo fa rima con...", "Porta i ⟦Imbued Skeletal Fragments=Frammenti Scheletrici Infusi⟧ e 15 monete d'oro a Krinkle Goodsteel, a ⟦Gadgetzan=Meccania⟧.", "Il goblin con cui devi parlare è Krinkle Goodsteel. Vende i suoi servigi al miglior offerente a ⟦Gadgetzan=Meccania⟧, nel deserto di Tanaris. Probabilmente è l'unico in grado di fabbricare lo stampo che ci serve, e i suoi servigi non costano poco. Ora ti chiediamo di mettere mano al portafoglio e pagare qualunque cifra chieda.\n\nSono uno speziale, non un banchiere. Se avessi dell'oro in giro, di certo non sarei qui.\n\nMi sa che ho detto ad alta voce la parte da non dire. Di nuovo. Ops.\n\n⟦Gadgetzan=Meccania⟧ ti aspetta! Buona fortuna!", "Sì, so chi sei e so perché sei qui. Dithers mi ha avvisato prima che arrivassi. Veniamo all'affare, che ne dici?\n\nHo uno stampo che puoi usare per la chiave universale, ma ti costerà: quindici monete d'oro, in anticipo, niente trattative. Metterò io i frammenti scheletrici nello stampo, e ti insegnerò anche a forgiare l'asta della chiave senza sapere nulla di forgiatura... il tutto gratis, per giunta.\n\nChi dice che i mercenari non fanno prezzi competitivi?", "Dithers aveva detto che avresti portato la merce, ed eccola qui! Un patto è un patto: lascia che metta i frammenti nello stampo per te.\n\nDithers li ha già infusi? Ottimo... altrimenti ti sarebbe toccato un lungo viaggio fino alla Granbarricata.", 0x64e41d76, 0x98c261fc, 0xca78de6e, 0xaa1c6644, 0x191c6e4a, "....." },
  [5515] = { "La ⟦Krastinov's Bag of Horrors=Borsa degli Orrori di Krastinov⟧", "Trova Jandice Barov a Scholomance e distruggila. Recupera dal suo cadavere la ⟦Krastinov's Bag of Horrors=Borsa degli Orrori di Krastinov⟧. Riporta la borsa a Eva Sarkhoff.", "Ci hai tolto un gran peso dal cuore, {name}, ma il tuo compito non è ancora finito. Il padrone di Krastinov, Kirtonos, è ancora vivo.\n\nPrima di poter affrontare Kirtonos, però, devi trovare un modo per evocarlo.\n\nSi dice che sia Jandice Barov a portare il sangue degli innocenti da Krastinov a Kirtonos.\n\nTrovala nelle catacombe sommerse di Scholomance e abbattila. Riporta qualunque indizio tu riesca a trovare.", "<Eva appare e scompare alla vista.>", "La Borsa degli Orrori!", 0xc11cac70, 0x0fb10777, 0x0ffd8fa0, 0xe847782c, 0xe4f2af76, "....." },
  [5517] = { "Il ⟦Chromatic Mantle of the Dawn=Riparo dell'Alba Cromatico⟧", "Porta 25 Emblema del Valore dell'⟦Argent Dawn=Alba d'Argento⟧ al quartiermastro Breechlock alla ⟦Light's Hope Chapel=Cappella della Luce⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧.", "<Fratello/Sorella> {name}, le tue imprese per conto dell'⟦Argent Dawn=Alba d'Argento⟧ sono troppo numerose per essere raccontate con facilità. Come giusto tributo, ti cederò uno dei nostri speciali Ripari dell'Alba Cromatici, una versione che protegge chi lo indossa da tutte le forme di magia a cui si può resistere, contemporaneamente. I Ripari dell'Alba Cromatici sono riservati soltanto ai più potenti tra gli eroi dell'Alba!\n\nPortami venticinque emblemi del valore come segno di tributo e ti darò il migliore di tutti i nostri ripari.", "Salute, potente <sacerdote/sacerdotessa>! Hai portato gli emblemi del valore che ti ho chiesto? Quando me li consegnerai, ti darò il tuo ⟦Chromatic Mantle of the Dawn=Riparo dell'Alba Cromatico⟧.", "Davvero notevole, {name}: il ⟦Chromatic Mantle of the Dawn=Riparo dell'Alba Cromatico⟧ ora è tuo!\n\nFinché manterrai il rango di Osannato presso l'⟦Argent Dawn=Alba d'Argento⟧, potrai acquistare altri Ripari dell'Alba Cromatici. Te li metterà subito a disposizione uno qualsiasi dei quartiermastri dell'Alba.", 0x89e9f7f2, 0xf647bdac, 0xedd992a2, 0x9947aee6, 0xbeb472bb, ".....", nil, nil, 0x4e45f79f, nil, nil },
  [5518] = { "Il ⟦Gordok Ogre Suit=Completo da Ogre Gordok⟧", "Porta 4 Rotolo di Telarunica, 8 ⟦Rugged Leather=Cuoio Duro⟧, 2 Filo Runico e il ⟦Ogre Tannin=Colorante Ogre⟧ a Knot Thimblejack. Al momento è incatenato nell'ala Gordok di ⟦Dire Maul=Maglio Infausto⟧.", "Se hai intenzione di affrontare il re di questa topaia, e credo proprio che sia quello che farai, dovrai superare il capitano Kromcrush. Certo, puoi superarlo ammazzandolo. Ma forse ti conviene lasciarlo in vita.\n\nCome, chiedi? Da quando sono qui, credo di aver capito come fare un costume da ogre che duri quanto basta per fregare questi zucconi. L'unico problema è la stabilità: dieci minuti al massimo. Portami quello che mi serve e te ne faccio uno. Tanto non vado da nessuna parte...", "Il ⟦Ogre Tannin=Colorante Ogre⟧ è probabilmente la cosa più difficile da trovare tra quelle che mi servono per il costume: credo che ne abbiano un po' al piano di sopra? Difficile dirlo, visto che questa palla al piede non mi rende facile muovermi...\n\nComunque, portami quello che mi serve e ti preparo un costume da ogre che farà credere al capitano Kromcrush che sei uno dei suoi.", "Sì, questo funzionerà. Basta infilare qui, rimboccare qui... eh eh, funzionerà alla perfezione! <Un ampio sorriso illumina il volto del goblin incatenato.>\n\nEcco fatto, sei a posto. Ricorda: non è l'oggetto più solido del mondo. Avrai dieci minuti di utilizzo prima che vada a pezzi, e poi non ingannerai più nessuno! Prova a usarlo appena prima di avvicinarti a lui, e ricorda... gli farà credere soltanto che TU sei un alleato, non i tuoi compagni di gruppo!", 0x7c7bbee3, 0xb8de906e, 0xf4901290, 0xb459423a, 0xb1e0632f, "....." },
  [5521] = { "Il ⟦Chromatic Mantle of the Dawn=Riparo dell'Alba Cromatico⟧", "Porta 25 Emblema del Valore dell'⟦Argent Dawn=Alba d'Argento⟧ a Lightspark, quartiermastro dell'⟦Chillwind Camp=Accampamento di Ventofreddo⟧, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧.", "<Fratello/Sorella> {name}, le tue imprese per conto dell'⟦Argent Dawn=Alba d'Argento⟧ sono troppo numerose per essere raccontate con facilità. Come giusto tributo, ti cederò uno dei nostri speciali Ripari dell'Alba Cromatici, una versione che protegge chi lo indossa da tutte le forme di magia a cui si può resistere, contemporaneamente. I Ripari dell'Alba Cromatici sono riservati soltanto ai più potenti tra gli eroi dell'Alba!\n\nPortami venticinque emblemi del valore come segno di tributo e ti darò il migliore di tutti i nostri ripari.", "Salute, potente {class}! Hai portato gli emblemi del valore che ti ho chiesto? Quando me li consegnerai, ti darò il tuo ⟦Chromatic Mantle of the Dawn=Riparo dell'Alba Cromatico⟧.", "Davvero notevole, {name}: il ⟦Chromatic Mantle of the Dawn=Riparo dell'Alba Cromatico⟧ ora è tuo!\n\nFinché manterrai il rango di Osannato presso l'⟦Argent Dawn=Alba d'Argento⟧, potrai acquistare altri Ripari dell'Alba Cromatici. Te li metterà subito a disposizione uno qualsiasi dei quartiermastri dell'Alba.", 0x89e9f7f2, 0x25f95bef, 0xedd992a2, 0xe017510a, 0xbeb472bb, ".....", nil, nil, 0x4e45f79f, nil, nil },
  [5522] = { nil, "Porta le ⟦Frozen Eggs=Uova Congelate⟧ a Leonid Barthalomew, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧.", "Ho ricevuto un messaggio dal mio padrone, Vectus. Beh, il messaggio non era proprio di Vectus... era di un certo Leonid Barthalomew. Non conosco Leonid, ma lui conosceva il mio padrone, e nessuno conosce il mio padrone se lui non lo permette.\n\nLeonid dice che Vectus vuole le uova di drago. Vuole che sia tu a consegnargliele alla ⟦Light's Hope Chapel=Cappella della Luce⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧.\n\nChe offesa! Perché tu? Vectus non si fida di me? Oh, lascia perdere... prendi le uova e di' a Leonid che ho fatto quello che il nostro padrone ha ordinato.", "Sei tu quell<o/a> che combina guai nei ⟦Blackrock Spire=Bastioni di Roccianera⟧, vero? Hai quello che ti ho chiesto?", "Ah, molto bene. Non conosci il potere malvagio per cui hai lavorato, ma ora conoscerai la verità. E non temere: non sono un servitore di quel padrone. Sono Leonid Barthalomew, noto come «il Reverito» ai miei confratelli dell'⟦Argent Dawn=Alba d'Argento⟧.\n\nHo ingannato Tinkee perché mandasse te e le uova di drago da me. Ed è un bene che il mio inganno sia riuscito, perché se queste uova fossero giunte a destinazione, un grande potere sarebbe caduto nelle mani del nemico.", 0x14b273d7, 0x88c9c397, 0xffad81a7, 0x18b4c1b5, 0x080f2e56, "e...." },
  [5524] = { "Il ⟦Chromatic Mantle of the Dawn=Riparo dell'Alba Cromatico⟧", "Porta 25 Emblema del Valore dell'⟦Argent Dawn=Alba d'Argento⟧ a Hasana, quartiermastro della Granbarricata, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧.", "<Fratello/Sorella> {name}, le tue imprese per conto dell'⟦Argent Dawn=Alba d'Argento⟧ sono troppo numerose per essere raccontate con facilità. Come giusto tributo, ti cederò uno dei nostri speciali Ripari dell'Alba Cromatici, una versione che protegge chi lo indossa da tutte le forme di magia a cui si può resistere, contemporaneamente. I Ripari dell'Alba Cromatici sono riservati soltanto ai più potenti tra gli eroi dell'Alba!\n\nPortami venticinque emblemi del valore come segno di tributo e ti darò il migliore di tutti i nostri ripari.", "Salute, potente {class}! Hai portato gli emblemi del valore che ti ho chiesto? Quando me li consegnerai, ti darò il tuo ⟦Chromatic Mantle of the Dawn=Riparo dell'Alba Cromatico⟧.", "Davvero notevole, {name}: il ⟦Chromatic Mantle of the Dawn=Riparo dell'Alba Cromatico⟧ ora è tuo!\n\nFinché manterrai il rango di Osannato presso l'⟦Argent Dawn=Alba d'Argento⟧, potrai acquistare altri Ripari dell'Alba Cromatici. Te li metterà subito a disposizione uno qualsiasi dei quartiermastri dell'Alba.", 0x89e9f7f2, 0x5dabc57e, 0xedd992a2, 0xe017510a, 0xbeb472bb, ".....", nil, nil, 0x4e45f79f, nil, nil },
  [5525] = { "Libera Knot!", nil, nil, "Si chiama ⟦Gordok Shackle Key=Chiave delle Catene di Gordok⟧... beh, almeno così continuano a chiamarla questi «ciccioni allegri». Credo che possa averla uno qualsiasi degli ogre, ma non sono sicuro che ce l'abbia qualcuno in particolare. Forse le guardie hanno più probabilità di averne una...\n\nMa di che parlo? Ce l'hai già, vero?! È quella lì??!", "Tu: al primo posto. Tutti gli altri: al secondo o più giù. Oh, grazie per avermi liberato!\n\nLo sapevo che la mia vita era destinata a qualcosa di più che fare da antipasto a un ogre!", 0x64c5142b, nil, nil, 0x1e7a9da3, 0xd66be950, ".mm.." },
  [5526] = { "Frammenti di Vil Vite", "Trova la Vil Vite a ⟦Dire Maul=Maglio Infausto⟧ e prendine un frammento. Con ogni probabilità potrai procurartene uno solo con la morte di Alzzin the Wildshaper. Usa il ⟦Reliquary of Purity=Reliquiario della Purezza⟧ per sigillarvi dentro al sicuro il frammento e portalo a Rabine Saturna, a ⟦Nighthaven=Nottequieta⟧, ⟦Moonglade=Radaluna⟧.", "Ora la tua conoscenza di Eldre'Thalas, ⟦Dire Maul=Maglio Infausto⟧, a Feralas, tornerà utile, {name}. È nella parte orientale della città in rovina che Alzzin the Wildshaper ha imposto il suo dominio corrotto. Recati laggiù al più presto e affronta qualunque sfida ti attenda.\n\nIl Fruit of Fertility, ora corrotto nella Vil Vite, dovrebbe trovarsi vicino ad Alzzin. Quando cadrà, cattura tutta l'essenza della Vil Vite che puoi. Sigillala nel Reliquiario e portamela.\n\nBuona fortuna, e che la velocità di Cenarius sia con te.", "Con il ⟦Sealed Reliquary of Purity=Reliquiario della Purezza Sigillato⟧ in nostro possesso, sarà possibile non solo eliminare dal mondo una minaccia corruttrice, ma anche studiarla sotto la nostra attenta sorveglianza. Forse riusciremo perfino a escogitare nuovi modi per combattere la piaga della corruzione che da sempre minaccia Azeroth.\n\nSo che Milli non l'avrebbe voluto in nessun altro modo...", "È fatta, valoros<o/a> {class}, e con questo il ⟦Cenarion Circle=Circolo Cenariano⟧ è in debito con te. Anche se la guerra è tutt'altro che finita, abbiamo vinto una grande battaglia contro chi vorrebbe la nostra rovina.\n\nTi prego, accetta questo come segno della nostra eterna gratitudine. Sappi che qui sarai sempre accolt<o/a> come un eroe del ⟦Cenarion Circle=Circolo Cenariano⟧ per la tua grande impresa, {name}. Grazie.", 0xc529120d, 0xbcbf4d83, 0x558aeb85, 0x10072c8b, 0x41482f0f, "....." },
  [5527] = { "Un ⟦Reliquary of Purity=Reliquiario della Purezza⟧", "Raggiungi ⟦Silithus=Silitus⟧ e cerca un ⟦Reliquary of Purity=Reliquiario della Purezza⟧ tra le rovine di ⟦Southwind Village=Vento del Sud⟧. Se riesci a trovarlo, portalo a Rabine Saturna, a ⟦Nighthaven=Nottequieta⟧, ⟦Moonglade=Radaluna⟧.", "Il primo passo è trovare un contenitore capace di custodire una sostanza estremamente corruttibile senza che chi lo maneggia ne subisca gli effetti nocivi. Conosco un solo tipo di dispositivo che potrebbe contenere qualcosa di immondo come la Vil Vite: un ⟦Reliquary of Purity=Reliquiario della Purezza⟧.\n\nNel profondo della landa desolata di ⟦Silithus=Silitus⟧ si trovano i resti del villaggio degli elfi della notte noto come Vento del Sud. So che uno si trovava lì molti, molti anni fa. Se vogliamo riuscirci, ho bisogno che tu setacci quelle rovine nella speranza di recuperarlo.", "Un ⟦Reliquary of Purity=Reliquiario della Purezza⟧ è un manufatto unico nel suo genere. Ne furono creati pochissimi, e si pensava che quasi tutti fossero andati perduti nel tempo.\n\nAmmetto di sapere già da un po' di quello di Vento del Sud. A dire il vero, con i crescenti disordini a ⟦Silithus=Silitus⟧, pensavo di mantenere i nostri segreti tali: un segreto. Frugare e curiosare avrebbe solo destato i sospetti dei nostri nemici.\n\nAhimè, il tempo dell'inerzia è finito, specialmente con la situazione a Eldre'Thalas.", "Davvero, sei pien<o/a> di risorse come molti dicono. Il ⟦Cenarion Circle=Circolo Cenariano⟧ è fortunato ad averti al suo servizio.\n\nCon il Reliquiario di nuovo nelle nostre mani, la mia mente è tranquilla. Mi sento più a mio agio nel chiederti non solo di affrontare un demone malvagio, ma anche di riportare nel frattempo un oggetto pericoloso...", 0x981c408b, 0x70105b2e, 0x93f71390, 0x39eb133a, 0xe4f96df3, "....." },
  [5528] = { "L'assaggio dei Gordok", nil, nil, nil, "Tu ora grande capo, quindi tu avere assaggio gratis di mie birre migliori! Queste bevande ti pompano E ti danno bella sbronza! Queste sono quelle buone, capo... tu prova e poi dici a Kreeg!", 0xd6c83438, nil, nil, nil, 0xab0267f0, ".mmm." },
  [5529] = { "Draghetti appestati", "Uccidi 20 Plagued Hatchling, poi torna da Betina Bigglezink alla ⟦Light's Hope Chapel=Cappella della Luce⟧.", "L'⟦Argent Dawn=Alba d'Argento⟧ ha appena scoperto che il Flagello sta creando un proprio stormo di draghi appestati! Dobbiamo fermarlo: se il Flagello riuscirà a mettere insieme una forza di draghi, dilagherà per Azeroth senza che nessuno possa fermarlo!\n\nI suoi negromanti allevano draghi appestati a Scholomance, in mezzo al ⟦Darrowmere Lake=Lago Darrowmere⟧.\n\nVa' a Scholomance e uccidi quanti più draghetti puoi... prima che crescano!", "Va' a Scholomance, {name}. Elimina quei draghetti appestati prima che crescano!", "Ben fatto, {name}! Ci vorrà molto tempo prima che riescano ad allevare un'altra covata di draghi.\n\n...Almeno, lo spero!", 0x3fc48153, 0x8bb59385, 0x8920582f, 0xf2479aae, 0xe2d0cdfb, "....." },
  [5531] = { nil, "Porta le ⟦Frozen Eggs=Uova Congelate⟧ a Betina Bigglezink.", "Le uova che hai portato sarebbero servite agli esperimenti del Flagello per creare uno stormo di draghi appestati. Queste uova congelate di drago nero sarebbero state preziosissime per i loro studi e avrebbero di certo accelerato i loro piani.\n\nOra è giunto il momento di porre fine alle loro ricerche.\n\nPorta le uova congelate a Betina Bigglezink, qui fuori. È molto esperta di scienza e alchimia e ha creato un'arma che possiamo usare contro il Flagello. Con il tuo aiuto, infliggeremo loro un duro colpo.", "Ciao, {name}! Ho sentito che sei qui con delle uova di drago? Be', vediamole!", "Eccole! E in un contenitore così carino. La misura perfetta!\n\nTerremo queste uova in un posto sicuro per poterle studiare più tardi, ma adesso ci serve quella cosa in cui le hai portate.\n\nHo creato un congegno con un uso molto specifico: distruggere gli studiosi non morti di Scholomance. Studiano i draghi nel tentativo di creare uno stormo di draghi appestati, e dobbiamo fermare i loro progressi.\n\nHo chiamato il congegno Trappola della Luce dell'Alba perché... non sono sicura che funzioni!\n\nLo scopriresti per noi?", 0x30d1cbfe, 0x6bca54e4, 0xdc0387b4, 0x77631291, 0xa2c1f1e1, "e...." },
  [5533] = { nil, "Parla con l'alchimista Arbington alla ⟦Chillwind Point=Gola di Ventofreddo⟧, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧.", "Sull'isola di Caer Darrow sorge Scholomance, un turpe centro della negromanzia e del male del Flagello. Il nostro nemico vi dimora e compie indicibili atti di depravazione su vittime ignare... o almeno, così supponiamo. Una porta sbarra il passaggio e, per quanto ci proviamo, non c'è modo di entrare senza la chiave giusta.\n\nL'alchimista Arbington conosce bene Scholomance e ha un'idea su come ottenere una chiave. Hai dimostrato il tuo valore, e ora affido a te questo compito. Parlagli della faccenda.", nil, "Ben <trovato/trovata>, {class}. Ho dedicato buona parte dei miei studi recenti a Scholomance, e credo di conoscere un modo con cui puoi procurarti una chiave... una che ti permetta di superare la porta d'ingresso.\n\nPosso solo immaginare quali orrori si vedano là dentro, {name}. A volte non so proprio come facciate, voi eroi...", 0xae1cd677, 0x8ba34863, 0xf80116ef, nil, 0xc04c0f0c, "e..m." },
  [5534] = { "L'equipaggiamento \"scomparso\" di Kim'jael", "Trova la ⟦Some Rune=Runa di Some⟧ che i naga custodiscono nelle ⟦Ruins of Eldarath=Rovine di Eldarath⟧ e riportala a Kim'jael, ad Azshara.", "Cosa?! Cosa?!\n\nNon ti è bastato? Lo sai quanto costano quegli esplosivi? Si vendono a... oh, lascia perdere. E va bene, vuoi fare soldi veri? Perché gli affari funzionano così: dimostri di essere un dipendente prezioso e poi vieni ricompensato a dovere, dopo aver tenuto duro per un po'.\n\nSe sei un dipendente \"prezioso\", allora fai un salto alle ⟦Ruins of Eldarath=Rovine di Eldarath⟧ e trovami una runa che quegli elfi del sangue stavano cercando. A quanto pare ce l'hanno i naga.", "Allora, {name}? Dov'è la runa? Sei <un/una> buon<o/a> dipendente, vero? Sei qui per aiutare?\n\nNon farmi ripensare al compenso che abbiamo concordato. Cosa? Oh, non abbiamo concordato niente? Oh, magnifico... allora prenditi pure il tuo tempo, ma sappi che sarà molto meno se ci metti tanto.", "Ah ah! Meraviglioso!\n\nScoprirò di sicuro a cosa serve e perché la magus Rimtori (è quella vacca che mi ha assunto) la voleva. Ah! Adesso vi ho fregato, puzzolenti elfi del sangue! Kim'jael! Ah! Gli insegnerò io chi sono i topi!\n\nHai fatto un buon lavoro, {name}. Grazie mille. Ecco, prendi queste monete e sparisci: ho delle cose da capire.", 0xf766ac57, 0xfefdfba8, 0x3651b51e, 0xfc701bc7, 0xfd93df7c, "....." },
  [5535] = { "Spiriti inquieti", "Distruggi 6 Highborne Apparition e 6 Highborne Lichling, poi torna da Loh'atu, ad Azshara.", "Tanto tempo fa, gli ⟦Highborne=Alti Nobili⟧ erano tra i più potenti studiosi dell'arcano che gli elfi della notte avessero mai avuto. La corruzione che accompagna studi del genere causò gravi danni alla società degli elfi della notte e colpì duramente tutta Azeroth... come certo saprai bene.\n\nHo promesso alle ⟦Sentinels=Sentinelle⟧ che avrei liberato gli spiriti dai loro legami mortali, man mano che li avessi trovati. Se farai lo stesso, sono certo di poterti ricompensare in qualche modo.\n\nGli spiriti infestano il ⟦Shadowsong Shrine=Santuario dei Cantombroso⟧, a nord-est di qui.", "Come procede la tua ricerca degli spiriti degli ⟦Highborne=Alti Nobili⟧, {class}?\n\nMolti eventi hanno causato grandi sofferenze a tutte le razze di Azeroth, ma per qualche motivo questi spiriti sembrano un flagello per tutti i popoli. Forse è il loro desiderio incessante di magia arcana: un simile desiderio è un presagio della Legione Infuocata, e sappiamo dove può portare.", "Ben fatto, {class}. Grazie del tuo aiuto. Gli spiriti hanno trovato pace, e le minacce attirate dal loro desiderio dell'arcano si sono attenuate.\n\nSono certo che entrambe le parti del conflitto che devasta Azeroth vedranno che tu sei al di sopra di queste cose.", 0xe4e4cb2a, 0x3df7c3ac, 0x049d9101, 0x263ff8de, 0x8d913bdf, "....." },
  [5536] = { "Una terra piena d'odio", "Uccidi 6 Haldarr Satyr, 2 Haldarr Trickster e 2 Haldarr Felsworn, poi torna da Loh'atu, al confine con ⟦Ashenvale=Valtetra⟧.", "I satiri, un aspetto deforme e malvagio degli elfi della notte, ora infestano le terre sacre un tempo percorse da Cenarius. Non posso parlare a nome degli elfi della notte riguardo a tutte le atrocità commesse da quelle creature demoniache, ma ho giurato alla Madre Terra di aiutare gli elfi a liberare la terra da una simile piaga.\n\nSono certo che daresti prova di te stess<o/a> se mi aiutassi a purgarla da loro.\n\nA nord-est di qui troverai il clan Haldarr. Torna da me dopo esserti misurat<o/a> con la loro potenza.", "Come procede la tua battaglia contro i satiri, {class}?\n\nSono forti quanto pensavi? Più forti? O forse non erano nulla di fronte alla tua potenza.", "Ben fatto, {class}. Vedo che non sei solo abile, ma anche astut<o/a>. Sconfiggere simili creature è la prova della tua fedeltà ai precetti della Madre Terra, anche se non la riconosci come tua divinità. Lei è in tutte le cose di questo mondo e oltre. I suoi occhi, uno scuro e uno chiaro, attraversano i cieli, sempre rivolti verso di noi.\n\nTi prego, accetta questa piccola somma in segno di riconoscenza per ciò che hai fatto.", 0xa3964943, 0x14431d9c, 0x2bfad3c5, 0xe837c9b8, 0xc130540a, "....." },
  [5537] = { "⟦Skeletal Fragments=Frammenti Scheletrici⟧", "Porta 15 ⟦Skeletal Fragments=Frammenti Scheletrici⟧ all'alchimista Arbington, alla ⟦Chillwind Point=Gola di Ventofreddo⟧, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧.", "La chiave di Scholomance si chiama Chiave Universale. Va forgiata con i resti di uno scheletro, anzi di parecchi, e temprata in uno stampo adatto con i metalli più resistenti che esistano. A farla funzionare davvero sarà il sigillo di potere di un essere capace per natura di aprire il portale di Scholomance.\n\nMa andiamo con ordine, {name}. Per forgiare la chiave ci servono frammenti scheletrici. Gli scheletri dentro Andorhal dovrebbero darci ciò che ci serve, ma anche quelli fuori dalle mura potrebbero andare bene.", "Per quanto suoni macabro, ci servirà una buona scorta di frammenti scheletrici adatti per lo strato esterno della chiave. Non per niente la chiamano Chiave Universale, sai.", "Questi andranno bene, {name}! Ora tocca a me: darò loro una tempra adatta, che gli permetta di resistere all'intenso processo di forgiatura che dovranno affrontare.\n\nIl prossimo passo sarà procurarsi uno stampo adatto per la chiave. Conosco un fabbro goblin a Tanaris che in passato ha realizzato stampi per oggetti altrettanto macabri. Lavora per chi lavorano di solito i goblin: il miglior offerente.", 0x9baabfac, 0xdbeb024a, 0x83a68ed3, 0x6cb2156e, 0x9f83db8b, "....." },
  [5538] = { "Stampo fa rima con...", "Porta i ⟦Imbued Skeletal Fragments=Frammenti Scheletrici Infusi⟧ e 15 monete d'oro a Krinkle Goodsteel, a ⟦Gadgetzan=Meccania⟧.", "Il goblin con cui devi parlare è Krinkle Goodsteel. Vende i suoi servigi al miglior offerente a ⟦Gadgetzan=Meccania⟧, nel deserto di Tanaris. Probabilmente è l'unico in grado di fabbricare lo stampo che ci serve, e i suoi servigi non costano poco. Ora ti chiediamo di mettere mano al portafoglio e pagare qualunque cifra chieda.\n\nSono un alchimista, non un banchiere. Se avessi dell'oro in giro, di certo non sarei qui.\n\nMi sa che ho detto ad alta voce la parte da non dire. Di nuovo. Ops.\n\n⟦Gadgetzan=Meccania⟧ ti aspetta! Buona fortuna!", "Sì, so chi sei e so perché sei qui. Arbington mi ha avvisato prima che arrivassi. Veniamo all'affare, che ne dici?\n\nHo uno stampo che puoi usare per la chiave universale, ma ti costerà: quindici monete d'oro, in anticipo, niente trattative. Metterò io i frammenti scheletrici nello stampo, e ti insegnerò anche a forgiare l'asta della chiave senza sapere nulla di forgiatura... il tutto gratis, per giunta.\n\nChi dice che i mercenari non fanno prezzi competitivi?", "Arbington aveva detto che avresti portato la merce, ed eccola qui! Un patto è un patto: lascia che metta i frammenti nello stampo per te.\n\nArbington li ha già infusi? Ottimo... altrimenti ti sarebbe toccato un lungo viaggio fino alla ⟦Chillwind Point=Gola di Ventofreddo⟧.", 0x64e41d76, 0x98c261fc, 0x76618973, 0x9deea60d, 0x9299c917, "....." },
  [5541] = { "Munizioni per Rumbleshot", "Porta le ⟦Rumbleshot's Ammo=Munizioni di Granzuffa⟧ a Hegnar Rumbleshot nel Dun Morogh.", "Hegnar Rumbleshot vende armi da fuoco lungo la strada per ⟦Anvilmar=Forgiamara⟧. Fucilieri e squadre di mortai passano molto tempo a esercitarsi vicino al suo negozio, e lui ha sempre bisogno di munizioni fresche.\n\nMa... l'ultima cassa di munizioni che gli ho mandato si è persa per strada. Il mio corriere dice che era accampato vicino alla Tana Selvaggia quando i wendigo l'hanno messo in fuga... e quello sciocco ha lasciato lì le munizioni di Rumbleshot!\n\n{name}, puoi recuperare quelle munizioni e portarle a Rumbleshot? Le sta aspettando e sono sicuro che è quasi a secco.", "Spero che tu non sia qui per le munizioni, perché le ho quasi finite!", "Ottimo, altre munizioni! Il carico del vecchio Loslor è finalmente arrivato! Le munizioni saranno anche in ritardo, ma come diceva sempre mio nonno: meglio tardi che mai!\n\nGrazie mille, {name}. Ho già dei clienti che non vedono l'ora di avere questa roba!", 0x6bdee02c, 0x4a7a3e42, 0x0214773d, 0x38170153, 0xa9ceafda, "....." },
  [5542] = { "Cani demoniaci", "Uccidi 20 Plaguehound Runt, 5 Plaguehound e 5 Frenzied Plaguehound. Torna da Tirion Fordring quando avrai finito.", "Se intendi restare qui, ti chiedo soltanto di guadagnarti il pane. Abbiamo molte seccature a cui farebbe bene un po' di «disciplina».\n\nPuoi cominciare con i Plaguehound e i loro cuccioli.\n\nNon posso offrirti molto in cambio, ma se ci riesci ti sono garantiti un pasto caldo e un po' di conversazione.", "Non avere pietà dei cani demoniaci, {race}. Sono abomini!", "Ben fatto, {name}. Vieni. Riposa. Mangiamo e parliamo dei giorni ormai lontani!", 0x74a3977e, 0x8d8e746a, 0xde0718df, 0xa091d5c2, 0x87ef13e0, "....." },
  [5543] = { "Cieli tinti di sangue", "Uccidi 30 Plaguebat e torna da Tirion Fordring.", "Guai a chi si avventura sconsideratamente nelle ⟦Plaguelands=Terre Infette⟧. Ogni sorta di abominio abita questi boschi: dai fanatici della ⟦Scarlet Crusade=Crociata Scarlatta⟧, che uccidono chiunque non porti il marchio della Crociata, all'assassino Flagello, che cerca solo di ingrossare le proprie file con altri non morti.\n\nPersino gli animali sono diventati bestie voraci e mangiatrici di uomini. Ti chiedo di distruggere quelle che colpiscono dal cielo: i Plaguebat.", "Non sottovalutare quei parassiti alati, {race}. La Piaga ha dato loro poteri soprannaturali.", "Sei un fulgido esempio di rettitudine, {race}! Era da tanto che non sentivo il sangue degli eroi scorrermi nelle vene. I tuoi atti di coraggio sono di grande conforto!", 0x1e870c8b, 0x2d4ec643, 0xc7740ef1, 0x830618bf, 0xd5aab03d, "....." },
  [5544] = { "Scorte di larve", "Cerca i Carrion Grub e i Carrion Devourer della regione. Uccidili e raccogline la carne. Torna da Tirion Fordring quando avrai raccolto 15 Trancio di Verme Carogna.", "Le mie scorte di cibo si stanno esaurendo, {race}. Mi vergogno ad ammetterlo, ma potrei non avere abbastanza da dividere con te.\n\nAiuteresti un vecchio in un compito semplice? Da queste parti, le uniche bestie risparmiate dalle devastazioni della Piaga sono i vermi carogna. Anche se piuttosto insipida, la carne dei vermi si conserva facilmente per mesi. Me ne serviranno diverse centinaia di libbre per rifornirmi per l'inverno che arriva!", "Imparerai a sopportarne il sapore, {race}.", "Che la Luce vegli su di te! Sii benedett<o/a>, giovane.", 0x6445813c, 0xbba0530c, 0x3dc9e55f, 0xadfc7a15, 0x0ac9cf94, "....." },
  [5545] = { "Un fascio di guai", "Porta 8 Ciocco di Legno a Raelen, al ⟦Eastvale Logging Camp=Campo di Taglio di Vallevante⟧.", "Ho un bel problema tra le mani. Ho una scadenza imminente per un ordine di legname e il tempo sta per finire. I lupi e gli orsi a nord di qui hanno fatto scappare i miei operai dai fasci di legna che avevano già tagliato.\n\nHo già chiesto al vicesceriffo Rainer di sistemare gli animali, ma mi serve qualcuno che vada a raccogliere la legna per me. Se riuscissi a raccogliermi otto fasci di legna, forse ce la farei a rispettare la scadenza.", "La scadenza non si allontana, {class}. Ti prego, sbrigati a raccogliere quei fasci di legna.", "Ottimo! Grazie a te, dovrei riuscire a completare l'ordine in tempo. Per dimostrarti la mia gratitudine, vorrei offrirti qualche moneta come ricompensa per il disturbo.\n\nGrazie e addio.", 0x014730dc, 0xa7c51bc1, 0x3cba4cdf, 0x1f6b6abf, 0x45f9cae3, "....." },
  [5561] = { "Il raduno dei kodo", "Riporta cinque Tamed Kodo e il ⟦Kodo Kombobulator=Kodoambulatore⟧ a Smeed Scrabblescrew all'⟦Scrabblescrew's Camp=Accampamento di Torcivite⟧.", "Bibbly crede di essere l'unico goblin di ⟦Desolace=Desolanda⟧ che sa fare soldi. Be', l'unica carovana abbastanza coraggiosa da attraversare queste terre conta su di me. Da quando ho imparato a ringiovanire e controllare i kodo vecchi e morenti con il mio Kodoambulatore, i proprietari della carovana, Cork e Rigger, e io siamo diventati soci.\n\nPrendi il Kodoambulatore e usalo su qualsiasi kodo antico, vecchio o morente: darà alla bestia una scossa che la trasformerà in un kodo addomesticato e la costringerà a seguirti. Quando avrai addomesticato un kodo, riportamelo.", "La carovana arriverà a breve; hai i cinque nuovi kodo addomesticati che ti avevo chiesto?", "<Smeed Scrabblescrew comincia a contare.>\n\nTre, quattro e cinque... eccellente, chiedo cinque kodo addomesticati e ottengo cinque kodo addomesticati... diventerò ricco... sì, ricchissimo! Spero di vedere la faccia verde di Bibbly quando saprà del mio successo!", 0x04bb1caf, 0xd279a8c8, 0x6b6406ad, 0x132725c5, 0x6e31573b, "....." },
  [5581] = { "I portali della Legione", "Esilia 6 portali alla ⟦Mannoroc Coven=Congrega di Mannoroc⟧ e torna da Taiga Wisemane a ⟦Shadowprey Village=Predombra⟧.", "Ecco: la ⟦Hand of Iruxos=Mano di Iruxos⟧. Uno spettacolo davvero raccapricciante.\n\nDevi averla con te se vuoi esiliare i portali demoniaci della ⟦Mannoroc Coven=Congrega di Mannoroc⟧... ed è proprio ciò che ora ti chiedo di fare. La minaccia dei demoni cresce, e dobbiamo chiudere questi portali per arginare l'ondata di demoni verso questo mondo. Buona fortuna, {name}... e attenzione ai guardiani dei portali.", "Hai esiliato i portali demoniaci alla ⟦Mannoroc Coven=Congrega di Mannoroc⟧?", "Meriti un encomio, {name}. Il tuo impegno è stato di grande aiuto nella lotta contro la minaccia dei demoni, e grazie a te tutta Azeroth è più sicura.", 0x67992a9e, 0x90813dc1, 0x935957b4, 0xe50d445b, 0x43ae0b56, "....." },
  [5601] = { "La sorella Pamela", "Trova Pamela Redpath al ⟦Darrowshire=Borgo di Darrow⟧.", "Sono fuggita da Lordaeron durante la grande guerra, e ho avuto la fortuna di scappare prima che il Flagello travolgesse la mia patria e la trasformasse in un incubo appestato! Io sono stata fortunata, ma la mia famiglia no. Temo che siano stati tutti uccisi nella battaglia del ⟦Darrowshire=Borgo di Darrow⟧.\n\nIl ⟦Darrowshire=Borgo di Darrow⟧ è un villaggio dei Regni Orientali, adagiato tra le colline meridionali di quelle che ora sono le ⟦Eastern Plaguelands=Terre Infette Orientali⟧. Andrai laggiù a cercare la mia famiglia? Mi mancano tanto, soprattutto la mia sorellina Pamela.\n\nTi prego, trovala per me!", nil, "Dov'è mia sorella Jessica? È andata via tanto tempo fa, quando ero solo una bambina piccola. Ha pianto tanto quando è partita. Non so perché piangeva! Forse era caduta e aveva sbattuto il dito del piede.\n\nQuando Jessica era qui giocavamo, ballavamo e raccoglievamo bei fiori intorno a casa. E a volte ci nascondevamo quando vedevamo papà tornare a casa, poi saltavamo fuori e gli facevamo una sorpresa!\n\nTorna, Jessica! Se torni tu, forse tornerà anche papà, e potremo giocare di nuovo tutti insieme...", 0xffb691bd, 0xa62eeff1, 0x24f8b115, nil, 0x81dbba27, "...m." },
  [5621] = { "Le vesti della luna", "Trova la sentinella Shaya e cura le sue ferite con Lesser Heal (Grado 2). Poi concedile ⟦Power Word: Fortitude=Parola del Potere: Fermezza⟧ e torna da Laurna Morninglight a Dolanaar.", "Ho bisogno del tuo aiuto, {name}. Devo restare qui ad addestrare gli altri studenti, ma tu puoi aiutare una delle nostre sentinelle ferite, appena a sud di Dolanaar. È stata ferita mentre pattugliava la città e le farebbe comodo il nostro aiuto. Si chiama Shaya.\n\nQuando la trovi, cura le sue ferite e poi rafforza il suo corpo con i tuoi incantesimi. Così, se si troverà nei guai, sarà protetta più a lungo. Torna qui da me dopo aver compiuto il tuo dovere verso Elune.", "I nostri incantesimi di rafforzamento sono molto potenti, Delor. Permettono ai nostri compagni di sopportare più ferite da ogni tipo di attacco e di sopravvivere in situazioni in cui normalmente cadrebbero. Ma non è nulla in confronto alla nostra capacità di guarire. Non esistono guaritori più grandi di un sacerdote: ricordatelo bene. Il tuo potere da solo può facilmente cambiare le sorti di una battaglia.", "Hai fatto bene e hai servito Elune. Per questo ti ringrazio.\n\nTi prego, prendi questa tonaca come segno della mia gratitudine. Significa che ti sei guadagnat<o/a> il tuo posto nel nostro ordine. Se vuoi, indossala con orgoglio ma, in ogni caso, ti riconosceremo sempre come <uno/una> dei nostri.\n\nVa' con Elune, {name}, e grazie.", 0x73f2ce3b, 0x26c8717b, 0xf5680a7c, 0xdd03baf4, 0xb864207f, "....." },
  [5622] = { "Nelle grazie di Elune", "Parla con Laurna Morninglight a Teldrassil.", "{name}, quando avrai finito i tuoi affari qui a ⟦Shadowglen=Vallombra⟧ dovrai recarti a Dolanaar. Lì troverai Laurna Morninglight. Ti istruirà ancora nelle vie di Elune, e sarà da lei che otterrai le tue prime vesti, segno del tuo rango di <sacerdote/sacerdotessa> di Elune.\n\nAbbi cura di te, e che tu sia protett<o/a> nei tuoi viaggi.", nil, "Sono felice di vedere che Shanda ti ha mandato da me, {name}. Insegnare ai giovani sacerdoti le vie di Elune mi dà grande soddisfazione.", 0x1f581c9a, 0x7edc7e4a, 0xe180ecac, nil, 0xfc0c1954, "...m.", nil, nil, 0xa4f739a2, nil, nil },
  [5623] = { "Nelle grazie della Luce", "Parla con la sacerdotessa Josetta nella ⟦Elwynn Forest=Foresta di Elwynn⟧.", "Ben ritrovat<o/a>, giovane <sacerdote/sacerdotessa>. È giunto il momento che tu impari di più sulla nostra religione. Dopo aver portato a termine i compiti che hai qui nella ⟦Northshire=Contea del Nord⟧, cerca la sacerdotessa Josetta a ⟦Goldshire=Borgodoro⟧. Ha altro da insegnarti e ha sentito che stai diventando forte nelle vie della Luce. Non vede l'ora di continuare a istruirti.", nil, "Sono lieta che tu sia arrivat<o/a>, {name}. Abbiamo molto di cui parlare riguardo al tuo futuro e al tuo sentiero nella Luce.", 0xd5e3412d, 0xf024d04d, 0xfb192887, nil, 0x0ffe1fdc, "...m.", nil, nil, 0xc820e603, nil, nil },
  [5624] = { "Le vesti della Luce", "Trova la guardia Roberts e cura le sue ferite con Lesser Heal (Grado 2). Poi concedigli ⟦Power Word: Fortitude=Parola del Potere: Fermezza⟧ e torna dalla sacerdotessa Josetta a ⟦Goldshire=Borgodoro⟧.", "Di solito propongo una piccola sfida ai seguaci della Luce per mettere alla prova la loro abilità. Voglio vedere se sono degni di indossare le loro prime tonache, segno che la chiesa approva apertamente <il/la> <sacerdote/sacerdotessa> e <lo/la> sostiene.\n\nMa questa volta la situazione è un po' diversa. Un cittadino di Borgodoro ha visto una guardia ferita vicino al lago a est di qui. Si chiama Roberts. Trovalo, curalo, rafforza il suo corpo e torna qui. Se riesci a farlo per me, considererò superata la tua prova.", "Come forse hai già imparato, le nostre magie curative sono vitali per la sopravvivenza della nostra gente in questi tempi difficili, specialmente per gli avventurieri e gli eroi che prendono le armi e la magia per respingere tante minacce diverse.\n\nFaresti bene a ricordare sempre quanto sia importante quest'abilità. Questa, unita a Fermezza, rende i tuoi compagni molto più capaci in battaglia, perché potranno resistere a un numero maggiore di colpi.\n\nNon permettere a nessuno di sminuire la potenza delle tue magie.", "Eccellente, {name}. Con una guardia in salute in più là fuori ad aiutare la città, saremo molto più al sicuro. Mi fa piacere vedere che stai già imparando a usare le tue abilità con saggezza. Se in qualsiasi momento ti senti pront<o/a> per altro addestramento, torna pure da me. Ma per ora prendi questa tonaca. Farà sapere agli altri che sei <uno/una> dei nostri. Se non vuoi indossarla, va bene. Più avanti ci saranno altre prove, e per quelle questa tonaca non è necessaria.", 0x42e1e67f, 0xd5d19b32, 0x701bafd9, 0xe1f1d1b3, 0xb57951a7, ".....", nil, nil, 0x1e24900e, nil, nil },
  [5625] = { "Le vesti della Luce", "Trova il montanaro Dolf e cura le sue ferite con Lesser Heal (Grado 2). Poi concedigli ⟦Power Word: Fortitude=Parola del Potere: Fermezza⟧ e torna da Maxan Anvol a Kharanos.", "Di solito è più o meno a questo punto che uno del tuo potere viene messo alla prova, per vedere se è degno di indossare le tonache che ne indicano il posto nella chiesa. Ma a dirla tutta, ho faccende più urgenti a cui pensare. Un cittadino di Kharanos è appena passato di qui e mi ha parlato di un montanaro ferito appena fuori città, a sud: si chiama Dolf.\n\nTu curi Dolf e gli dai Fermezza, e io considero conclusa la tua prova. Che ne dici?", "Hai già trovato Dolf, {name}?\n\nProbabilmente l'hai già imparato, ma la nostra capacità di guarire è molto utile. Non solo possiamo prenderci cura dei feriti, ma siamo vitali per la sopravvivenza di tutti quegli aspiranti eroi là fuori che cercano di farsi un nome. Con Fermezza ad aumentare i colpi che si possono sopportare e la nostra magia curativa a tenerli in vita, non c'è niente che non possiamo superare!", "Eccellente, {name}. Con una guardia in salute in più là fuori ad aiutare la città, saremo molto più al sicuro. Mi fa piacere vedere che stai già imparando a usare le tue abilità con saggezza. Se in qualsiasi momento ti senti pront<o/a> per altro addestramento, torna pure da me. Ma per ora prendi questa tonaca. Farà sapere agli altri che sei <uno/una> dei nostri. Se non vuoi indossarla, va bene. Più avanti ci saranno altre prove, e per quelle questa tonaca non è necessaria.", 0x42e1e67f, 0x4324dd9b, 0x0d9a711f, 0x0425d788, 0xb57951a7, "....." },
  [5626] = { "Nelle grazie della Luce", "Parla con Maxan Anvol a Dun Morogh.", "Ehi! {name}! Hai un minuto?!\n\nOrmai segui la Luce da abbastanza tempo da doverti presentare a Maxan Anvol, a Kharanos. Ti insegnerà di più sul sentiero che segui e, se ti dimostrerai degn<o/a>, ti darà la tua prima tonaca, segno del tuo rango di <sacerdote/sacerdotessa>.\n\nE ora muoviti! Appena hai finito qui, passa per il tunnel: ti starà aspettando.", nil, "Oh, allora ti ha mandato Branstock, eh? Bene, bene! Ha ragione, è proprio ora che tu faccia un passo molto più grande nella Luce. Ti formerà il carattere e ti renderà più forte... ed è questo che ti servirà più di ogni altra cosa: forza del corpo... forza della volontà.", 0xd5e3412d, 0x5cf188e4, 0x84b16634, nil, 0x77d8d926, "...m.", nil, nil, 0xb689446c, nil, nil },
  [5627] = { "Stelle di Elune", nil, nil, nil, "Hai dimostrato di essere degn<o/a> dell'attenzione di Elune, {name}. Se ti senti pront<o/a>, mi piacerebbe molto insegnarti uno dei suoi incantesimi riservati al nostro popolo.", 0x8a355ee6, nil, nil, nil, 0x6f78fed8, ".mmm." },
  [5628] = { "Ritorno a casa", "Parla con la sacerdotessa Alathea a Darnassus.", "Ah, sì, salve, {name}? Sono felice che tu ti sia fermat<o/a> a parlare un momento. Sei molto lontan<o/a> da casa per essere così giovane: ammiro tanta ambizione. Vorrei aver trovato, da giovane, il coraggio di viaggiare per il mondo.\n\nNon molto tempo fa è passata di qui una sacerdotessa del tuo ordine che ti cercava. Ha detto che era molto urgente che tornassi al ⟦Temple of the Moon=Tempio della Luna⟧ a Darnassus e parlassi con la sacerdotessa Alathea: aveva a che fare con il tuo addestramento. Se puoi, non indugerei troppo.", nil, "Splendido, sei tornat<o/a> a casa, {name}. A Tyrande e a me fa sempre piacere quando coloro che abbiamo addestrato partono per il mondo e tornano da noi sani e salvi. Come ti sono andate le cose? Elune benedice ancora i tuoi viaggi? Magari, dopo aver parlato della questione che ci preme, potresti raccontarmi qualcosa di più dei tuoi viaggi.", 0xab7568f5, 0x8f9be0c1, 0x8242adf0, nil, 0x8d04e540, "...m." },
  [5629] = { "Ritorno a casa", "Parla con la sacerdotessa Alathea a Darnassus.", "Di nuovo salve, {name}. So che sei <stato/stata> molto impegnat<o/a> ad aiutare la nostra gente, ma devi anche prenderti del tempo per te. La sacerdotessa Alathea ha mandato qualcuno a cercarti. Sembra che tu abbia attirato l'attenzione dei nostri anziani e che ti ritengano pront<o/a> per cose più grandi. Va' al ⟦Temple of the Moon=Tempio della Luna⟧ a Darnassus e cerca Alathea. Ti starà aspettando. Buona fortuna, ed Elune sia con te.", nil, "Splendido, sei tornat<o/a>, {name}. A Tyrande e a me fa sempre piacere quando coloro che abbiamo addestrato partono per il mondo e tornano da noi sani e salvi. Come ti sono andate le cose? Elune benedice ancora i tuoi viaggi? Magari, dopo aver parlato della questione che ci preme, potresti raccontarmi qualcosa di più dei tuoi viaggi.", 0xab7568f5, 0x8f9be0c1, 0xa8f3f5b8, nil, 0xcbab1194, "...m." },
  [5630] = { "Ritorno a casa", "Parla con la sacerdotessa Alathea a Darnassus.", "Salve, <ragazzo/ragazza>. Bello vederti viaggiare in lungo e in largo per terre lontane. Senza offesa, ma di solito molti della tua razza non sopportano bene questi climi freddi. Mi fa piacere vedere che sei fatt<o/a> di una pasta più dura.\n\nNon molto tempo fa è passata di qui una sacerdotessa della tua gente che ti cercava: ha detto qualcosa sul fatto che dovevi trovare una certa sacerdotessa Alathea nel ⟦Temple of the Moon=Tempio della Luna⟧, giù a Darnassus. Ha detto che era importante e che dovresti tornarci presto.", nil, "Splendido, sei tornat<o/a> a casa, {name}. A Tyrande e a me fa sempre piacere quando coloro che abbiamo addestrato partono per il mondo e tornano da noi sani e salvi. Come ti sono andate le cose? Elune benedice ancora i tuoi viaggi? Magari, dopo aver parlato della questione che ci preme, potresti raccontarmi qualcosa di più dei tuoi viaggi.", 0xab7568f5, 0x8f9be0c1, 0x3b3bfab4, nil, 0x8d04e540, "...m.", nil, nil, 0x25879782, nil, nil },
  [5631] = { "Ritorno a casa", "Parla con la sacerdotessa Alathea a Darnassus.", "Di recente una sacerdotessa è venuta nelle nostre sale a cercarti, giovane {race}. Ha detto di essere in missione per trovarti e che dovresti tornare al ⟦Temple of the Moon=Tempio della Luna⟧ a Darnassus il prima possibile. Quando arrivi, cerca una certa sacerdotessa Alathea: ti dirà di più.\n\nChe la Luce sia con te, {name}.", nil, "Splendido, sei tornat<o/a> a casa, {name}. A Tyrande e a me fa sempre piacere quando coloro che abbiamo addestrato partono per il mondo e tornano da noi sani e salvi. Come ti sono andate le cose? Elune benedice ancora i tuoi viaggi? Magari, dopo aver parlato della questione che ci preme, potresti raccontarmi qualcosa di più dei tuoi viaggi.", 0xab7568f5, 0x8f9be0c1, 0xbd0e6a0c, nil, 0x8d04e540, "...m." },
  [5632] = { "Ritorno a casa", "Parla con la sacerdotessa Alathea a Darnassus.", "Oh, sì, certo. Salve, {name}. Non molto tempo fa è passata di qui una messaggera del nostro ordine che ti cercava. Ha accennato a qualcosa di importante che sta accadendo a Darnassus e ha detto che dovresti tornare al ⟦Temple of the Moon=Tempio della Luna⟧ appena puoi. Quando arrivi, parla con la sacerdotessa Alathea. Credo che abbia a che fare con i tuoi ottimi progressi nelle nostre vie.\n\nTe lo ripeto: torna a Darnassus quando puoi.", nil, "Splendido, sei tornat<o/a> a casa, {name}. A Tyrande e a me fa sempre piacere quando coloro che abbiamo addestrato partono per il mondo e tornano da noi sani e salvi. Come ti sono andate le cose? Elune benedice ancora i tuoi viaggi? Magari, dopo aver parlato della questione che ci preme, potresti raccontarmi qualcosa di più dei tuoi viaggi.", 0xab7568f5, 0x8f9be0c1, 0x9052d2b7, nil, 0x8d04e540, "...m." },
  [5633] = { "Ritorno a casa", "Parla con la sacerdotessa Alathea a Darnassus.", "Salute, <ragazzo/ragazza>. Bello vederti qui nelle nostre grandi sale. Una benedizione su di te e sulla tua gente.\n\nMentre viaggiavi per le nostre terre, una sacerdotessa del tuo tempio è venuta qui a cercarti. Ha detto che dovevi tornare al ⟦Temple of the Moon=Tempio della Luna⟧ il prima possibile. Mi spiace non poterti dire di più, ma sembrava importante. Quando arrivi al tempio, parla con una certa sacerdotessa Alathea.", nil, "Splendido, sei tornat<o/a> a casa, {name}. A Tyrande e a me fa sempre piacere quando coloro che abbiamo addestrato partono per il mondo e tornano da noi sani e salvi. Come ti sono andate le cose? Elune benedice ancora i tuoi viaggi? Magari, dopo aver parlato della questione che ci preme, potresti raccontarmi qualcosa di più dei tuoi viaggi.", 0xab7568f5, 0x8f9be0c1, 0x23045fad, nil, 0x8d04e540, "...m.", nil, nil, 0xded29ca7, nil, nil },
  [5634] = { "⟦Desperate Prayer=Preghiera Disperata⟧", "Parla con il sommo sacerdote Rohan a ⟦Ironforge=Forgiardente⟧.", "Di recente un sacerdote è venuto nelle nostre sale a cercarti, giovane {race}. Ha detto di essere in missione per trovarti e che dovresti tornare alla Hall of Mysteries di ⟦Ironforge=Forgiardente⟧ il prima possibile. Quando arrivi, cerca il sommo sacerdote Rohan: ti dirà di più.\n\nChe la Luce sia con te, {name}.", nil, "Hai reso un grande servizio alla Luce diventando un esempio luminoso per chi viaggia in queste terre pericolose e oltre. Ti prego, accetta questa lezione come ringraziamento per tutto ciò che hai fatto.", 0x5e463cb3, 0x18755abb, 0x16d5e391, nil, 0x8e6ca817, "...m." },
  [5635] = { "⟦Desperate Prayer=Preghiera Disperata⟧", "Parla con il sommo sacerdote Rohan a ⟦Ironforge=Forgiardente⟧.", "Hai attirato l'attenzione dei nostri superiori, {name}. Ti chiedono di recarti alla Hall of Mysteries di ⟦Ironforge=Forgiardente⟧ il prima possibile. A quanto pare ritengono che tu abbia già dato prova di te e che sia pront<o/a> a proseguire il tuo addestramento. Quando arrivi, trova il sommo sacerdote Rohan. Saprà guidarti oltre. Buona fortuna, e che la Luce sia con te.", nil, "Mi fa piacere che tu sia arrivat<o/a>, {name}. Ci sono molte cose di cui dovremo discutere, ma ancora più importante è il tuo addestramento nelle vie della Luce.\n\nCi sono lezioni che tutti i servitori della Luce devono imparare. Se sei pront<o/a>, cominceremo subito a parlarne.", 0x5e463cb3, 0x18755abb, 0x87560e73, nil, 0xddc02048, "...m." },
  [5636] = { "⟦Desperate Prayer=Preghiera Disperata⟧", "Parla con il sommo sacerdote Rohan a ⟦Ironforge=Forgiardente⟧.", "Elune ti benedica, <buon/buona> {race}. Spero che la tua Luce ti trovi e ti protegga in questo giorno.\n\nUno dei tuoi sacerdoti è passato di qui non molto tempo fa a cercarti. Ha accennato al fatto che dovresti tornare il prima possibile alla Hall of Mysteries per parlare con il sommo sacerdote Rohan. Sembra che tu abbia fatto bene, per attirare tanta attenzione. Non resterei troppo qui: la tua gente ha bisogno di te.", nil, "Mi fa piacere che tu sia arrivat<o/a>, {name}. Ci sono molte cose di cui dovremo discutere, ma ancora più importante è il tuo addestramento nelle vie della Luce.\n\nCi sono lezioni che tutti i servitori della Luce devono imparare. Se sei pront<o/a>, cominceremo subito a parlarne.", 0x5e463cb3, 0x18755abb, 0x829d5d51, nil, 0xddc02048, "...m." },
  [5637] = { "⟦Desperate Prayer=Preghiera Disperata⟧", "Parla con il sommo sacerdote Rohan a ⟦Ironforge=Forgiardente⟧.", "È ora che tu vada a ⟦Stormwind=Roccavento⟧, {name}. Il sommo sacerdote Rohan, nella Hall of Mysteries, vuole parlarti. Dev'essere qualcosa di molto buono o di molto brutto se il sommo sacerdote ti vuole lì di persona, ma secondo me ti sei solo fatt<o/a> onore, ed è un bene che voglia parlarti.\n\nMa non perdere troppo tempo da queste parti. Io ci andrei il prima possibile.", nil, "Mi fa piacere che tu sia arrivat<o/a>, {name}. Ci sono molte cose di cui dovremo discutere, ma ancora più importante è il tuo addestramento nelle vie della Luce.\n\nCi sono lezioni che tutti i servitori della Luce devono imparare. Se sei pront<o/a>, cominceremo subito a parlarne.", 0x5e463cb3, 0x18755abb, 0x148eb4c2, nil, 0xddc02048, "...m." },
  [5638] = { "⟦Desperate Prayer=Preghiera Disperata⟧", "Parla con il sommo sacerdote Rohan a ⟦Ironforge=Forgiardente⟧.", "Poco fa uno dei vostri sacerdoti è venuto a cercarti, {race}. Ha detto che, se ti avessi visto, avrei dovuto indirizzarti verso la Hall of Mysteries. Ha detto che era molto importante, ma al tuo posto non mi preoccuperei troppo. Sembrava di buon umore... come se si trattasse di buone notizie. Al tuo posto, però, non tarderei ad andarci.\n\nChe Elune sia con te, nobile {race}.", nil, "Mi fa piacere che tu sia arrivat<o/a>, {name}. Ci sono molte cose di cui dovremo discutere, ma ancora più importante è il tuo addestramento nelle vie della Luce.\n\nCi sono lezioni che tutti i servitori della Luce devono imparare. Se sei pront<o/a>, cominceremo subito a parlarne.", 0x5e463cb3, 0x18755abb, 0xa819c88b, nil, 0xddc02048, "...m." },
  [5639] = { "⟦Desperate Prayer=Preghiera Disperata⟧", nil, nil, nil, "Mi fa piacere che tu sia arrivat<o/a>, {name}. Ci sono molte cose di cui dovremo discutere, ma ancora più importante è il tuo addestramento nelle vie della Luce.\n\nCi sono lezioni che tutti i servitori della Luce devono imparare. Se sei pront<o/a>, cominceremo subito a parlarne.", 0x5e463cb3, nil, nil, nil, 0xddc02048, ".mmm." },
  [5640] = { "⟦Desperate Prayer=Preghiera Disperata⟧", "Parla con il sommo sacerdote Rohan a ⟦Stormwind=Roccavento⟧.", "Sia lodata Elune, e sia lodata la tua Luce, {name}.\n\nIn questo periodo molti del nostro ordine apprendono abilità che riflettono la loro fede in Elune. Se non ricordo male, credo che lo stesso valga anche per il tuo ordine.\n\nQuando avrai concluso i tuoi affari a Darnassus, ti consiglio di cercare uno dei tuoi sommi sacerdoti per un ulteriore addestramento.", nil, "Mi fa piacere che tu sia arrivat<o/a>, {name}. Ci sono molte cose di cui dovremo discutere, ma ancora più importante è il tuo addestramento nelle vie della Luce.\n\nCi sono lezioni che tutti i servitori della Luce devono imparare. Se sei pront<o/a>, cominceremo subito a parlarne.", 0x5e463cb3, 0xa762cb1a, 0x62b6262b, nil, 0xddc02048, "...m." },
  [5641] = { nil, nil, nil, nil, "Hai la stoffa di un grande {class}, {name}. Continua così!\n\nHai già dimostrato di essere pront<o/a> alla battaglia. Forse è ora di insegnarti qualcosina in più.", 0xeabe5139, nil, nil, nil, 0xf71decf8, "emmm." },
  [5642] = { nil, "Parla con Ur'kyo a Orgrimmar.", "Sta succedendo qualcosa di importante a Orgrimmar, {name}.\n\nDi solito i messaggeri che passano di qui a cercare i sacerdoti troll se la prendono comoda. Stavolta sembravano molto più di fretta. Non attardarti troppo a ⟦Thunder Bluff=Picco del Tuono⟧. Fossi in te, tornerei alla ⟦Valley of Spirits=Valle degli Spiriti⟧ il prima possibile.", nil, "I tuoi riti arriveranno presto. Per ora ti insegno un incantesimo che ti sarà molto utile quando combatterai contro i tuoi nemici.", 0xcf44b409, 0x18d06dea, 0x1895999d, nil, 0xb615482e, "e..m." },
  [5643] = { nil, "Parla con Ur'kyo a Orgrimmar.", "Come molti dei nostri sacerdoti, anche la tua tribù ti sottopone a riti di passaggio. Spesso questi riti insegnano ai sacerdoti abilità speciali, vitali per la loro sopravvivenza. Sento che quel momento è giunto per te proprio ora. Devi tornare alla ⟦Valley of Spirits=Valle degli Spiriti⟧, a Orgrimmar, e parlare con Ur'kyo. Ciò che ti insegnerà potrebbe essere molto importante per il futuro.", nil, "I tuoi riti arriveranno presto. Per ora ti insegno un incantesimo che ti sarà molto utile quando combatterai contro i tuoi nemici.", 0xcf44b409, 0x18d06dea, 0x9bb6868b, nil, 0xb615482e, "e..m." },
  [5644] = { nil, "Parla con Aelthalyste a ⟦Undercity=Sepulcra⟧.", "Ah, è un giorno meraviglioso per te, {name}. Dalle lezioni che hai appreso vedo che è giunto il momento di rimandarti da Aelthalyste. Ci sono cose che solo lei può insegnarti, e anche allora, solo se ti dimostrerai degn<o/a>.\n\nNon ti rovinerò la sorpresa, ma ricordo quando ero un giovane sacerdote e imparavo cosa fosse il vero potere... il potere divino. Sì, bei tempi.\n\nTorna da Aelthalyste a ⟦Undercity=Sepulcra⟧, {name}. Ti aspetterà nel ⟦War Quarter=Quartiere della Guerra⟧.", nil, "Ti insegnerò Devouring Plague, se ti senti pront<o/a>, {name}. È un incantesimo di non poca potenza e ti aiuterà nelle battaglie che verranno. Esercitati: più avanti ci saranno delle prove.", 0x122ac7ca, 0x53641243, 0x1085ab93, nil, 0xec1eed23, "e..m." },
  [5645] = { nil, "Parla con il sommo sacerdote Rohan a ⟦Ironforge=Forgiardente⟧.", "{name}, il tuo sommo sacerdote Rohan vuole riceverti a ⟦Ironforge=Forgiardente⟧. Affrettati, mio forte amico: la tua prossima prova si avvicina in fretta. Vorrei poter assistere ai riti speciali della tua razza, ma il mio posto è qui. Che la Luce ti accompagni nei tuoi viaggi. Quando arriverai in città, Rohan dovrebbe essere ancora nel Mystic Ward. Ti aspetterà.", nil, "È un bene che tu sia venut<o/a>, {name}. La nostra razza è fiera e forte, ed è ora che tu impari non solo a esserlo, ma anche a suscitare questi sentimenti e questa fiducia negli altri. Sei pront<o/a>, <ragazzo/ragazza>?", 0xeabe5139, 0x18755abb, 0x7c851f5d, nil, 0x2f8ef86f, "e..m." },
  [5646] = { nil, "Parla con Aelthalyste a ⟦Undercity=Sepulcra⟧.", "Aelthalyste mostra gran rispetto alla nostra gente, che la rimanda da me per altro addestramento, e ora io faccio lo stesso con la sua tribù.\n\nTu torni a ⟦Undercity=Sepulcra⟧, {name}. Là, nel ⟦War Quarter=Quartiere della Guerra⟧, lei è pronta a insegnarti di più sulla tua gente e sulle sue usanze. Va' là, e non aspettare troppo.", nil, "Bene, sei tornat<o/a>, e appena in tempo. Abbiamo grandi cose di cui parlare, {name}. Le tue abilità stanno crescendo e dobbiamo assicurarci che tu sia pront<o/a>.", 0x122ac7ca, 0x53641243, 0xbaba2cb5, nil, 0x7346e69e, "e..m." },
  [5647] = { nil, "Parla con il sommo sacerdote Rohan a ⟦Ironforge=Forgiardente⟧.", "La tua razza è così forte, {name}. Siamo fieri di chiamarvi alleati. E a ogni tramonto tu e i tuoi simili vi avvicinate non solo alla scoperta delle vostre vere origini, ma anche alla certezza di essere sulla strada giusta in tante cose. Dev'essere una sensazione di trionfo.\n\nDa poco è arrivato un messaggio da ⟦Ironforge=Forgiardente⟧. Chiede che tu torni là e parli con il sommo sacerdote Rohan nel Mystic Ward. Io non lo farei aspettare. Che Elune guidi i tuoi viaggi.", nil, "Hai la stoffa di un grande {class}, {name}. Continua così!\n\n{name}, hai già dimostrato di essere pront<o/a> alla battaglia. Forse è ora di insegnarti qualcosina in più.", 0xeabe5139, 0x18755abb, 0x90bbdd69, nil, 0x3d1896c7, "e..m." },
  [5648] = { "Le vesti della spiritualità", "Trova la grunt Kor'ja e cura le sue ferite con Lesser Heal (Grado 2). Poi concedile ⟦Power Word: Fortitude=Parola del Potere: Fermezza⟧ e torna da Tai'jin a ⟦Razor Hill=Tranciacolle⟧.", "Tu sei pront<o/a> per la tua prima prova, {name}. A sud di ⟦Razor Hill=Tranciacolle⟧, appena fuori città, una delle nostre grunt è ferita: ha combattuto contro dei vecchi soldati di Proudmoore. Lei non sta tanto bene, e le farebbe molto bene se uno della nostra gente la aiuta. Trovala, il suo nome è Kor'ja, cura le sue ferite e dalle la benedizione dei nostri antenati.\n\nTu fai questo, e io penso che è prova sufficiente che sei pront<o/a> ad andare avanti nelle nostre vie.", "Quasi tutti pensano che è logico che le magie di guarigione sono potenti, ma pochi capiscono quanto potenti. Tu puoi tenere in vita molti che invece dovrebbero andare a incontrare i loro antenati. Questa magia di guarigione, unita al potere di Fermezza, è una combinazione di incantesimi molto potente. Tu ricorda questo. Serve a ogni tipo di gente: guerrieri, maghi e tutto quello che sta in mezzo.", "Bene, allora Kor'ja vive e torna a difendere la nostra città da quegli umani malvagi. Spesso vorrei ricordare i giorni di battaglia, quando il potere si mostrava nel combattimento ed erano spesso i saggi a distruggere quelli che contavano solo sulla loro forza.\n\nTu hai fatto bene con me, {name}. Tu prendi questa tonaca adesso. Forse aiuta, forse a te non importa, ma te la sei guadagnata e io sono fiero di chiamarti <fratello/sorella>.", 0x593c5783, 0x24940db1, 0xa91befae, 0xb96c37f7, 0xec880bcf, ".....", nil, nil, nil, nil, 0x54dfafd6 },
  [5649] = { "In favore della spiritualità", "Parla con Tai'jin, in Durotar.", "Sì, amico. La nostra gente si è unita all'⟦Horde=Orda⟧ perché è buona per noi. Loro leali, e ci insegnano tante cose su roba come l'onore. Ma le nostre vecchie usanze sono dure a morire. Gli orchi forse non approvano tutte le nostre tradizioni, ma questo non vuol dire che non possiamo continuare a praticarne qualcuna in segreto.\n\nTu lo sai, ed è per questo che ti mando da Tai'jin a ⟦Razor Hill=Tranciacolle⟧. Lei ti insegna di più sulla nostra storia. Lei ti insegna le vie della nostra tribù. Va' da lei quando sei pront<o/a>.", nil, "Ahh... così finalmente vieni da Tai'jin. Questo è buono.\n\nTu già sai che noi non siamo la stessa tribù che un tempo si è unita all'⟦Horde=Orda⟧. Noi siamo molto più forti ora. Noi più forti perché ci adattiamo: l'⟦Horde=Orda⟧ ci ha insegnato almeno questo. Noi non sconfiggiamo più i nemici per prendere forza da loro; ora prendiamo forza, e poi sconfiggiamo i nemici.\n\nLa differenza è sottile, ma tu imparerai. Tu vedrai. La tribù conta su di te per imparare queste cose.", 0xced31293, 0x4eafa33b, 0x93255826, nil, 0x1aa9d73f, "...m." },
  [5650] = { "Vesti dell'oscurità", "Trova la Guardia della Morte Kel e cura le sue ferite con Lesser Heal (Grado 2). Poi conferiscigli ⟦Power Word: Fortitude=Parola del Potere: Fermezza⟧ e torna dalla chierica oscura Beryl, a Brill.", "Il nostro potere viene dall'oscurità e dall'ombra, {name}, ma non è questo il tuo unico ruolo. Hai riconosciuto che conoscere le arti della guarigione ha il suo valore. È saggio. Ma prima di conoscere l'oscurità devi conoscere anche la luce. E per questo ho una prova per te.\n\nA nord del cimitero c'è una Guardia della Morte ferita: la Guardia della Morte Kel. Ci protegge dagli gnoll da tempo e ha bisogno di cure. Ma devi anche rinvigorire il suo corpo prima che possa tornare in servizio. Fai entrambe le cose con i tuoi incantesimi, poi torna da me.", "I nostri poteri ci rendono ideali per moltissime situazioni, {name}. Scoprirai però che, in ogni caso, la nostra capacità di curare le ferite e di aumentare i danni che i nostri compagni possono sopportare sarà sempre il talento più richiesto a nostra disposizione. Questo non deve scoraggiarti dal percorrere altre strade come {class}: puoi essere efficace in molti modi. Ma... se desideri davvero distruggere i tuoi nemici con l'energia magica, forse l'arcano fa più per te.", "Hai superato la mia prova con facilità. Bene.\n\nPresto sarai pront<o/a> ad assumerti più responsabilità, e quella strada ti porterà a poteri più oscuri: poteri che nessun {class} di un'altra razza possiede.\n\nPrendi questa veste come simbolo del tuo rango. Te la sei guadagnata. Se non vuoi indossarla, così sia: puoi farne ciò che vuoi. Io e altri come noi ti riconosceremo sempre per ciò che hai ottenuto nelle nostre file.", 0x0c6d0bd3, 0x723fbde5, 0xfaa3d69d, 0x6343c5d5, 0x458cdd4e, "....." },
  [5651] = { "In favore dell'Oscurità", "Parla con il Chierico Oscuro Beryl nelle ⟦Tirisfal Glades=Radure di Tirisfal⟧.", "Ci sono molte lezioni che i Reietti hanno imparato con l'esperienza, cose che alcune razze possono appena cominciare a comprendere. E anche se il nostro cammino si trova nell'oscurità, scoprirai che moltissime cose dipendono sia dalla luce sia dall'oscurità. Le tue lezioni ti insegneranno a usarle entrambe... e con discrezione. Ma ascolta le mie parole: non dimenticare mai che siamo stati forgiati nella corruzione e lasciati a marcire come tante carogne. L'Oscurità è la nostra casa.\n\nQuando sarai pront<o/a> a imparare di più, cerca il Chierico Oscuro Beryl a Brill.", nil, "Finalmente sei arrivat<o/a>. La sola fede non ti permetterà di superare le prove che ti attendono, giovane. Ti aiuteranno anche un po' di urgenza e di ambizione.", 0xe676d3d4, 0x47392945, 0xb16687db, nil, 0x3481d16c, "...m." },
  [5652] = { "⟦Hex of Weakness=Maleficio di Debolezza⟧", nil, nil, nil, "Faresti bene a prestare attenzione a questa lezione, giovane. Il ⟦Hex of Weakness=Maleficio di Debolezza⟧ ti sarà di grande aiuto in battaglia. Più avanti avrò altre prove per te, per farti crescere e dimostrare il tuo valore alla tribù.", 0x7764cf64, nil, nil, nil, 0x1c4616e4, ".mmm." },
  [5654] = { "⟦Hex of Weakness=Maleficio di Debolezza⟧", "Parla con Ur'kyo a Orgrimmar.", "È tempo che tu incontri Ur'kyo, {name}. Lui sta nella ⟦Valley of Spirits=Valle degli Spiriti⟧, nella città degli orchi. Va' là e parla con lui. È tempo che impari di più sulle antiche usanze della nostra gente. È tempo che tu venga accolt<o/a> nel cerchio e diventi <un/una> ver<o/a> <sacerdote/sacerdotessa> della nostra tribù.", nil, "Faresti bene a prestare attenzione a questa lezione, giovane. Il ⟦Hex of Weakness=Maleficio di Debolezza⟧ ti sarà di grande aiuto in battaglia. Più avanti avrò altre prove per te, per farti crescere e dimostrare il tuo valore alla tribù.", 0x7764cf64, 0x18d06dea, 0xd2e2bae7, nil, 0x1c4616e4, "...m." },
  [5655] = { "⟦Hex of Weakness=Maleficio di Debolezza⟧", "Parla con Ur'kyo a Orgrimmar.", "Io mandato qui per assicurarmi che tu non va troppo lontano da casa, {name}. Mi mandano per assicurarmi che tu torna a casa, perché Ur'kyo, il più grande dei nostri sacerdoti, vuole parlarti. Tu va' là. Tu va' nella ⟦Valley of Spirits=Valle degli Spiriti⟧, nella città degli orchi, e parla con Ur'kyo. Lui ti aspetta adesso.", nil, "Faresti bene a prestare attenzione a questa lezione, giovane. Il ⟦Hex of Weakness=Maleficio di Debolezza⟧ ti sarà di grande aiuto in battaglia. Più avanti avrò altre prove per te, per farti crescere e dimostrare il tuo valore alla tribù.", 0x7764cf64, 0x18d06dea, 0x16e5e011, nil, 0x1c4616e4, "...m." },
  [5656] = { "⟦Hex of Weakness=Maleficio di Debolezza⟧", "Parla con Ur'kyo a Orgrimmar.", "Il mio cuore immortale si scalda sempre nel vedere sacerdoti di ogni cultura girare per il mondo. Sapere che esiste un potere che non è arcano ed è ben alla nostra portata. Per questo è un onore per me rimandarti a casa, {name}.\n\nUr'kyo, il vostro grande sacerdote a Orgrimmar, ha chiesto di vederti. Lo troverai nella ⟦Valley of Spirits=Valle degli Spiriti⟧.", nil, "Faresti bene a prestare attenzione a questa lezione, giovane. Il ⟦Hex of Weakness=Maleficio di Debolezza⟧ ti sarà di grande aiuto in battaglia. Più avanti avrò altre prove per te, per farti crescere e dimostrare il tuo valore alla tribù.", 0x7764cf64, 0x18d06dea, 0xd7057125, nil, 0x1c4616e4, "...m." },
  [5657] = { "⟦Hex of Weakness=Maleficio di Debolezza⟧", "Parla con Ur'kyo a Orgrimmar.", "Casa. Torna a casa, giovane {race}.\n\nLa tua guida spirituale, Ur'kyo, ti prega di tornare da lui per parlare del cammino che percorri.\n\nVa' nella ⟦Valley of Spirits=Valle degli Spiriti⟧, nella grande città dell'⟦Horde=Orda⟧, Orgrimmar. Lì lo troverai.", nil, "Faresti bene a prestare attenzione a questa lezione, giovane. Il ⟦Hex of Weakness=Maleficio di Debolezza⟧ ti sarà di grande aiuto in battaglia. Più avanti avrò altre prove per te, per farti crescere e dimostrare il tuo valore alla tribù.", 0x7764cf64, 0x18d06dea, 0x62ef2561, nil, 0x1c4616e4, "...m." },
  [5658] = { nil, nil, nil, nil, "Ah, giovane {class}, sono lieto che tu sia tornat<o/a> qui. Vorrei insegnarti una lezione che faresti bene a non dimenticare. Sei <pronto/pronta>?", 0xdccff772, nil, nil, nil, 0xb566d701, "emmm." },
  [5659] = { nil, nil, nil, nil, "Ah, bene, è arrivato qualcun altro. Il tempo forse non conta per me, ma per te è essenziale. C'è molto che devi imparare e molto che desidero insegnarti. Devi solo dimostrare il tuo valore. Fallo, e sarai ricompensat<o/a> generosamente.", nil, nil, nil, nil, 0xb886b0c3, "mmmm." },
  [5660] = { nil, "Parla con Aelthalyste a ⟦Undercity=Sepulcra⟧.", "Tu stai lontano da casa, {class}. C'è bisogno di te laggiù, nella tua città sotto terra. La tua padrona, quella che voi chiamate Aelthalyste, ha bisogno che torni. Come per la mia tribù, ci sono cose che puoi imparare solo da lei. Non restare qui troppo a lungo. Dovresti andare al ⟦War Quarter=Quartiere della Guerra⟧ più veloce che uno zeppelin può portarti.", nil, "Ah, bene, è arrivato qualcun altro. Il tempo forse non conta per me, ma per te è essenziale. C'è molto che devi imparare e molto che desidero insegnarti. Devi solo dimostrare il tuo valore. Fallo, e sarai ricompensat<o/a> generosamente.", 0xdccff772, 0x53641243, 0xc634bef2, nil, 0xb886b0c3, "e..m." },
  [5661] = { nil, "Parla con Aelthalyste a ⟦Undercity=Sepulcra⟧.", "Tu stai lontano da casa qui al ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧, {name}. Io mandato qui a cercare sacerdoti della mia tribù da rimandare a parlare con i nostri capi, ma questo non vuol dire che io non posso aiutare anche te.\n\nHo sentito dire che lo spirito della tua somma sacerdotessa vuole che tutti i Reietti vanno da lei: ci sono cose che devi imparare.\n\nVa' a incontrare Aelthalyste nel ⟦War Quarter=Quartiere della Guerra⟧, in quella vostra città.", nil, "Ah, bene, è arrivato qualcun altro. Il tempo forse non conta per me, ma per te è essenziale. C'è molto che devi imparare e molto che desidero insegnarti. Devi solo dimostrare il tuo valore. Fallo, e sarai ricompensat<o/a> generosamente.", 0xdccff772, 0x53641243, 0xa906659b, nil, 0xb886b0c3, "e..m." },
  [5662] = { nil, "Parla con Aelthalyste a ⟦Undercity=Sepulcra⟧.", "Il mio rispetto a te e alla tua gente, {name}. Di solito istruisco solo quelli della mia tribù. Le tue lezioni vengono da Aelthalyste, nella città un tempo chiamata Lordaeron.\n\nDovresti tornare da lei se vuoi imparare le abilità che ti distinguono dalle altre fedi.\n\nVa' al ⟦War Quarter=Quartiere della Guerra⟧ di ⟦Undercity=Sepulcra⟧ e lì troverai la tua padrona.", nil, "Ah, bene, è arrivato qualcun altro. Il tempo forse non conta per me, ma per te è essenziale. C'è molto che devi imparare e molto che desidero insegnarti. Devi solo dimostrare il tuo valore. Fallo, e sarai ricompensat<o/a> generosamente.", 0xdccff772, 0x53641243, 0x5fc0308e, nil, 0xb886b0c3, "e..m." },
  [5663] = { nil, "Parla con Aelthalyste a ⟦Undercity=Sepulcra⟧.", "Aelthalyste ha mandato un messaggio a tutti i suoi sacerdoti. Dobbiamo indirizzare i più giovani del nostro ordine a ⟦Undercity=Sepulcra⟧ per un ulteriore addestramento. Se ti consideri davvero tra i nostri fedeli, dovresti tornarci anche tu.\n\nTroverai Aelthalyste nel ⟦War Quarter=Quartiere della Guerra⟧, nelle profondità di ⟦Undercity=Sepulcra⟧.", nil, "Ah, bene, è arrivato qualcun altro. Il tempo forse non conta per me, ma per te è essenziale. C'è molto che devi imparare e molto che desidero insegnarti. Devi solo dimostrare il tuo valore. Fallo, e sarai ricompensat<o/a> generosamente.", 0xdccff772, 0x53641243, 0xa2d072d4, nil, 0xb886b0c3, "e..m." },
  [5672] = { nil, nil, nil, nil, "Dedicandoti a Elune e al nostro popolo, hai raggiunto uno stato che non tutti noi riusciamo a raggiungere. Per tradizione, ora ti vengono insegnate abilità ancora più grandi in premio della tua devozione. Accetti?", 0x2e456277, nil, nil, nil, 0x8f606a4d, "emmm." },
  [5673] = { nil, "Parla con la sacerdotessa Alathea a Darnassus.", "Sai di poter accedere in qualsiasi momento a tutti i nostri istruttori, {name}, ma ci sono cose che non possiamo trasmetterti. Una di queste sono gli insegnamenti della tua dea Elune. Lei concede abilità speciali ai suoi fedeli e, se non sbaglio, è ora che tu torni a casa, al ⟦Temple of the Moon=Tempio della Luna⟧, per essere mess<o/a> alla prova.\n\nTorna là appena puoi e parla con la sacerdotessa Alathea.", nil, "Che Elune ti benedica per essere tornat<o/a> da noi così in fretta. Questo è un momento importante del tuo addestramento, e tutto il nostro ordine lo prende molto sul serio. Quando ti sarai riposat<o/a> dal viaggio, fammelo sapere, ti prego. Allora potremo parlare di come proseguire il tuo addestramento e di dove ti condurrà il tuo cammino.", 0x2e456277, 0x8f9be0c1, 0x8fb26a95, nil, 0xc3518a4a, "e..m." },
  [5674] = { nil, "Parla con la sacerdotessa Alathea a Darnassus.", "È giunto un giorno meraviglioso, {name}. Hai raggiunto l'età in cui i nostri <sacerdoti/sacerdotesse> vengono addestrati in abilità che solo gli elfi della notte conoscono. Ma non spetta a me addestrarti. Devi tornare al ⟦Temple of the Moon=Tempio della Luna⟧ e parlare con la sacerdotessa Alathea non appena avrai concluso i tuoi affari qui. Ti metterà alla prova per assicurarsi che tu sia pront<o/a>, e solo allora ti insegnerà Elune's Grace.", nil, "Dedicandoti a Elune e al nostro popolo, hai raggiunto uno stato che non tutti noi riusciamo a raggiungere. Per tradizione, ora ti vengono insegnate abilità ancora più grandi in premio della tua devozione. Accetti?", 0x2e456277, 0x8f9be0c1, 0xda81f573, nil, 0x8f606a4d, "e..m.", nil, nil, 0x22b130fc, nil, nil },
  [5675] = { nil, "Parla con la sacerdotessa Alathea a Darnassus.", "Il tempo stringe, <ragazzo/ragazza>. È ora che tu torni a casa, a Darnassus. La sacerdotessa Alathea ha mandato a dire che devi tornare là per l'addestramento. Pare che ti ritengano pront<o/a> a essere mess<o/a> alla prova, un po' come chi serve la Luce. Parti appena puoi. Nel messaggio Alathea diceva che ti aspetterà nel ⟦Temple of the Moon=Tempio della Luna⟧. Buona fortuna.", nil, "Che Elune ti benedica per essere tornat<o/a> da noi così in fretta. Questo è un momento importante del tuo addestramento, e tutto il nostro ordine lo prende molto sul serio. Quando ti sarai riposat<o/a> dal viaggio, fammelo sapere, ti prego. Allora potremo parlare di come proseguire il tuo addestramento e di dove ti condurrà il tuo cammino.", 0x2e456277, 0x8f9be0c1, 0x45deec4a, nil, 0xc3518a4a, "e..m.", nil, nil, 0x1de89d1d, nil, nil },
  [5676] = { nil, nil, nil, nil, "Siamo stati costretti ad apprendere alcune magie per proteggerci da quello che viene comunemente chiamato il nostro più grande nemico: l'arcano.\n\nTi insegnerò un incantesimo che ti aiuterà a difendere te stess<o/a> e i tuoi compagni da chi vorrebbe brandire un simile potere.", 0xa7b14275, nil, nil, nil, 0x34be78ad, "emmm." },
  [5677] = { nil, "Parla con la somma sacerdotessa Laurena a ⟦Stormwind=Roccavento⟧.", "Per quanto mi piacerebbe mostrarti i nostri insegnamenti speciali della Luce, non spetta a noi. Il tuo posto è a ⟦Stormwind=Roccavento⟧, tra la tua gente, {name}... per ora. Credimi, non intendo offenderti. Quando tornerai dalla somma sacerdotessa Laurena nella ⟦Cathedral of Light=Cattedrale della Luce⟧ capirai di cosa parlo: è giunto il momento che la tua razza ti prepari per il futuro, e che tu ti distingua da altri che seguono un cammino simile.", nil, "Ah, hai un tempismo perfetto, {name}. Cominciavo a chiedermi se tutti i miei messaggeri ce l'avessero fatta. Sono felice di vedere di sì, altrimenti scommetto che saresti ancora in giro per il mondo a imparare tutto sulle minacce che incombono sul nostro popolo.\n\nSei pront<o/a>? Pront<o/a> per altro addestramento, intendo. Il tuo potere cresce sempre più in fretta, e sento che sei pront<o/a> a imparare di più sulla nostra fede.", 0xa7b14275, 0x8de762b6, 0x3d8f5891, nil, 0xa244b6c1, "e..m." },
  [5678] = { nil, "Parla con la somma sacerdotessa Laurena a ⟦Stormwind=Roccavento⟧.", "È ora che tu torni a ⟦Stormwind=Roccavento⟧, giovane. I tuoi superiori ti hanno richiamato per altro addestramento. E anche se la cosa un po' mi turba, la tua razza e la mia sono alleate e non tradirei mai questo legame.\n\nNon voglio essere così reticente con te: la mia diffidenza verso le magie arcane, che siano di ispirazione divina o no, è ancora forte in me.\n\nCapirai di cosa parlo quando sarai tornat<o/a> alla tua ⟦Cathedral of Light=Cattedrale della Luce⟧. Parla con la somma sacerdotessa Laurena quando arrivi.", nil, "Ah, hai un tempismo perfetto, {name}. Cominciavo a chiedermi se tutti i miei messaggeri ce l'avessero fatta. Sono felice di vedere di sì, altrimenti scommetto che saresti ancora in giro per il mondo a imparare tutto sulle minacce che incombono sul nostro popolo.\n\nSei pront<o/a>? Pront<o/a> per altro addestramento, intendo. Il tuo potere cresce sempre più in fretta, e sento che sei pront<o/a> a imparare di più sulla nostra fede.", 0xa7b14275, 0x8de762b6, 0x4fe1c26d, nil, 0xa244b6c1, "e..m." },
  [5679] = { nil, nil, nil, nil, "Ti insegnerò Devouring Plague, se ti senti pront<o/a>, {name}. È un incantesimo di non poca potenza e ti aiuterà nelle battaglie che verranno. Esercitati: più avanti ci saranno delle prove.", 0x122ac7ca, nil, nil, nil, 0xec1eed23, "emmm." },
  [5680] = { nil, nil, nil, nil, "I tuoi riti arriveranno presto. Per ora ti insegno un incantesimo che ti sarà molto utile quando combatterai contro i tuoi nemici.", 0xcf44b409, nil, nil, nil, 0xb615482e, "emmm." },
  [5713] = { "Un colpo, un bersaglio", "Proteggi la sentinella Aynasha, poi parla con Onaeya all'⟦Maestra's Post=Accampamento di Maestra⟧, a ⟦Ashenvale=Valtetra⟧.", "Stavo andando ad Auberdine con un messaggio importante quando sono stata attaccata dal mezzorso Marosh e dai suoi segugi. Durante l'attacco sono stata avvelenata e ora riesco a malapena a reggermi in piedi. Posso preparare un antidoto, ma ci vorrà tempo prima che sia pronto.\n\nTi chiedo di difendermi finché non potrò applicare l'antidoto. Ti aiuterò con il mio arco come meglio posso.\n\nSe sopravviveremo, potrò consegnare il mio messaggio ad Auberdine, mentre tu parlerai con Onaeya all'⟦Maestra's Post=Accampamento di Maestra⟧ per informarla dell'accaduto.", "Hai visto la sentinella Aynasha sulla strada? È partita per una missione importante, ma non è ancora tornata.", "Porti notizie davvero gradite, {class}. È bello sapere che Aynasha è viva e sta bene grazie a te. Spero che accetterai una ricompensa per il tuo valore. Che Elune vegli su di te e illumini il tuo cammino.", 0xd9bcb0ad, 0xfd45a006, 0x550eea3f, 0xd79229bb, 0x5150e92b, "....." },
  [5721] = { "La battaglia del ⟦Darrowshire=Borgo di Darrow⟧", "Colloca il ⟦Relic Bundle=Mucchio di Reliquie⟧ nella piazza del ⟦Darrowshire=Borgo di Darrow⟧.\n\nImpedisci che Davil Lightfire muoia prima della morte di Horgus.\n\nImpedisci che il capitano Redpath muoia prima che compaia Redpath the Corrupted.\n\nSconfiggi Redpath the Corrupted.\n\nParla con lo spirito di Joseph Redpath quando compare nella piazza, poi parla con Pamela a casa sua.", "Ora, {name}, prenderai parte alla battaglia del ⟦Darrowshire=Borgo di Darrow⟧ e salverai Joseph Redpath.\n\nColloca questo mucchio di reliquie nella piazza del ⟦Darrowshire=Borgo di Darrow⟧ e gli spiriti del ⟦Darrowshire=Borgo di Darrow⟧ si risveglieranno. Unisciti alla loro battaglia e fa' in modo che accadano due cose: Davil deve sopravvivere fino alla morte di Horgus, e Redpath deve sopravvivere finché non verrà corrotto, per poi essere sconfitto.\n\nDopo che avrai sconfitto Redpath corrotto, il suo spirito sarà salvo. Parla con lui, poi torna da sua figlia Pamela.", "Credo di aver sentito dei fantasmi qui fuori. Mi sussurrano cose spaventose...", "La battaglia è finita! Ho sentito il mio papà sussurrarmi. Ha fatto scappare tutti i fantasmi e dice che sta tornando a casa! Sono così felice!\n\nHa detto anche che dovevo accoglierti se fossi venut<o/a> a casa nostra, così ho preparato il tè!\n\nSpero che ti piaccia con tanto zucchero!", 0x465f9818, 0xa130650b, 0x531b48de, 0x1af64862, 0x393b8b0b, "....." },
  [5722] = { "Alla ricerca della sacca perduta", "Cerca il cadavere di Maur Grimtotem nel ⟦Ragefire Chasm=Baratro di Fiamma Furente⟧ e frugalo in cerca di oggetti interessanti.", "I trogg non sono l'unica cosa che interessava a Magatha nel ⟦Ragefire Chasm=Baratro di Fiamma Furente⟧. Le è giunta voce che uno dei suoi servitori, un certo Maur Grimtotem, aveva trovato qualcosa di singolare nel Baratro, ma non ne è mai uscito per mostrarle cosa. Vorrebbe che si ritrovasse il corpo di Maur, se esiste ancora, e qualsiasi indizio di ciò che aveva trovato mentre cercava di parlare con i trogg.\n\nRiporta a Magatha qualsiasi oggetto interessante e sono sicuro che sarà molto generosa nel ricompensarti.\n\nTe lo ripeto: cerca il Baratro nelle zone più buie di Orgrimmar.", nil, "Il corpo sembra duramente percosso da mazze o pugni, ma gran parte dei vestiti e dell'equipaggiamento del cadavere sembra ancora al suo posto. Pare che ai trogg non importi granché delle ricchezze materiali.\n\nInizi a perquisire il corpo in cerca di qualcosa di interessante che possa aiutare Magatha.", 0xb20112ea, 0xdde6ef18, 0x2bfed261, nil, 0x30cabc23, "...m." },
  [5723] = { "Saggiare la forza del nemico", "Cerca il ⟦Ragefire Chasm=Baratro di Fiamma Furente⟧ a Orgrimmar, poi uccidi 8 Ragefire Trogg e 8 Ragefire Shaman prima di tornare da Rahauro, a ⟦Thunder Bluff=Picco del Tuono⟧.", "Sotto la città di Orgrimmar, delle tozze creature chiamate trogg hanno cominciato a risalire in superficie dalle profondità dei tunnel pieni di lava. Nella sua infinita benevolenza, Magatha ha cercato di fare pace con queste creature, ma loro si sono rivoltate contro i suoi diplomatici e li hanno uccisi. Magatha non tollererà un simile trattamento verso il popolo tauren, e ora considera queste creature una minaccia per tutta l'⟦Horde=Orda⟧.\n\nTi chiede di porre fine alla minaccia dei trogg prima che travolga l'⟦Horde=Orda⟧ dal basso. Trova il ⟦Ragefire Chasm=Baratro di Fiamma Furente⟧ e distruggili tutti.", "Come procede la ricerca del Baratro? E i trogg?\n\nNon possiamo permettere che la minaccia continui: se va avanti, colpirà solo i nostri fratelli orchi.", "Sono lieto di vedere che hai preso sul serio il compito di Magatha. Grazie, {name}. Sono sicuro che i trogg faranno più fatica a risalire in superficie, ora che il loro numero è tanto ridotto.\n\nForse in futuro potremo prenderci il tempo di capire da dove vengono queste creature e che cosa vogliono davvero.", 0xabeb706b, 0xe0fdd528, 0xc3e7179e, 0x14a45315, 0xbc9a5ddc, "....." },
  [5724] = { "La restituzione della sacca perduta", "Porta la ⟦Grimtotem Satchel=Sacca dei Totem Truce⟧ a Rahauro a ⟦Thunder Bluff=Picco del Tuono⟧.", "Trovi una sacca sotto il corpo del tauren. La stringe ancora forte tra le braccia, come se avesse cercato di proteggerla mentre i trogg lo attaccavano.\n\nTolta la sacca dalla sua presa ferrea, la riponi con il tuo equipaggiamento e ti prepari a uscire dai tunnel per tornare da Rahauro a ⟦Thunder Bluff=Picco del Tuono⟧.", "Sei riuscit<o/a> a trovare qualcosa, {name}? Qualsiasi indizio sul perché uno dei membri del suo clan sia dovuto morire inutilmente sarebbe utile.", "Eccellente, {name}. Grazie.\n\nMagatha mi ha detto che, se fossi riuscit<o/a> a trovare il suo compagno di clan, avrei dovuto darti questo. Ti prego, prendilo come ringraziamento.", 0x78c3b168, 0x25ce5d81, 0xd0331193, 0x28b9b726, 0xbb8bccf5, "....." },
  [5725] = { "Il potere di distruggere...", "Porta i libri ⟦Spells of Shadow=Incantesimi dell'Ombra⟧ e ⟦Incantations from the Nether=Incanti del Fatuo⟧ a Varimathras a ⟦Undercity=Sepulcra⟧.", "Come forse saprai, molti servitori della Legione elargiscono doni ai loro seguaci. Alcuni di questi doni, secondo la Dama Oscura, starebbero meglio nelle sue mani che in quelle di chi ha una visione... più limitata.\n\nUna setta del ⟦Shadow Council=Concilio dell'Ombra⟧ nascosta nelle caverne sotto Orgrimmar, nota come ⟦Searing Blade=Lama Rovente⟧, ne è un ottimo esempio. La Dama mi dice che alcuni membri della ⟦Searing Blade=Lama Rovente⟧ sono entrati in possesso di due potenti libri di incantesimi: vorrebbe \"prenderli in prestito\". Li recupererai per lei.", "Ci sono cento altri compiti che attendono la mia attenzione, {class}. Hai i libri?", "Bene, {class}. Hai servito bene la Dama Oscura. La tua costante perseveranza e la tua ambizione saranno di grande utilità ai sudditi della Dama. Torna da me in futuro. Forse avrò altri compiti per te che aiuteranno la Dama Oscura nei suoi tentativi di sopraffare il Re dei Lich e liberare completamente il Flagello.", 0x78248aca, 0x81a2cc99, 0x7d48c15d, 0x97d5fe7b, 0x24c68998, "....." },
  [5726] = { "Nemici nascosti", "Porta un ⟦Lieutenant's Insignia=Distintivo del Luogotenente⟧ a Thrall a Orgrimmar.", "Una cosa che non tollero sono i traditori tra noi, {name}. Ma sarei uno sciocco a scoprire le mie carte così presto: non basterebbe a estirpare la corruzione dalle nostre terre e farebbe solo peggiorare l'infezione.\n\nMa tu, giovane avventurier<o/a>, potresti andare dove i miei agenti non possono... potresti scoprire la verità... potresti trovare la vera testa della bestia.\n\nSe hai abbastanza coraggio, entra nella ⟦Skull Rock=Roccia del Teschio⟧, a est di Orgrimmar, prendi il distintivo da luogotenente a uno dei membri delle ⟦Burning Blade=Lame Ardenti⟧ che si trovano lì e torna da me.", "Hai già il distintivo, {name}?\n\nSarà uno strumento fondamentale per infiltrarci in quella che credo sia la più grande minaccia per l'⟦Horde=Orda⟧, e per trovare finalmente la pace nella nostra nuova casa.\n\nScoprirai quanto intricata possa essere la ragnatela che uomini e orchi sanno tessere quando li muovono l'avidità e il potere. I piani nascosti, la corruzione: tutto ti sarà chiaro. Ti ritroverai nel mezzo di una guerra di cui non hai mai sospettato l'esistenza.", "Bene, {name}! Siano lodati gli spiriti, forse sei tu <colui/colei> che finalmente metterà a tacere le mie paure più grandi! Chi sospetterebbe che qualcuno di così giovane e così coraggioso si leverebbe a difendere la nostra causa? Mi ricordi me stesso da giovane. Farò in modo che tu sia giustamente ricompensat<o/a> per i tuoi sforzi, se sopravviveremo entrambi alla tempesta in arrivo.\n\nMa ci sarà tempo più tardi per altre lodi. Non hai ancora compiuto nulla in confronto a ciò che dovrai affrontare... ma questo è un buon inizio.", 0x2986cf2d, 0xf540a6c4, 0xe4b83f85, 0x571977d8, 0x78e53150, "....." },
  [5727] = { "Nemici nascosti", "Porta il ⟦Lieutenant's Insignia=Distintivo del Luogotenente⟧ a Neeru Fireblade e parla con lui. Valuta se crede che tu sia un membro delle ⟦Burning Blade=Lame Ardenti⟧, poi torna da Thrall a Orgrimmar.", "Ora vediamo se questo distintivo che hai trovato valeva la fatica.\n\nIn città c'è uno stregone convinto di avere la mia fiducia. Non sa che io so dove sta la sua vera lealtà. In realtà è il capo delle ⟦Burning Blade=Lame Ardenti⟧. Ma non correre a combatterlo: ha uno scopo, e lo useremo contro i nostri nemici.\n\nPorta questo distintivo a lui, nella Cleft of Shadow qui a Orgrimmar, parlagli e vedi se crede che tu sia uno dei suoi, poi torna da me.", "Allora, {class}? Ha creduto al nostro stratagemma, o le cose vanno peggio di quanto avessi stimato?\n\nRenderti prezios<o/a> agli occhi di Neeru renderà molto più facile la nostra infiltrazione nel ⟦Shadow Council=Concilio dell'Ombra⟧. Avrà un sacco di informazioni che potremo usare per stanare chi vorrebbe distruggere tutto ciò che abbiamo costruito a Durotar.", "Eccellente! Davvero eccellente, {class}!\n\nCiò che hai fatto oggi è solo il primo passo verso fondamenta molto più ampie: fondamenta su cui costruiremo la distruzione del ⟦Shadow Council=Concilio dell'Ombra⟧, una volta per tutte.\n\nRaccontami tutto ciò che ha detto... e non tralasciare nemmeno una parola: potrebbe essere più importante di quanto immagini.", 0x2986cf2d, 0xe4533834, 0x24cbb4fb, 0xba3db556, 0xb0896349, "....." },
  [5728] = { "Nemici nascosti", "Uccidi Bazzalan e Jergosh the Invoker, poi torna da Thrall a Orgrimmar.", "Mmm, i capi della ⟦Searing Blade=Lama Rovente⟧... è questo che mi preoccupa di più. Se sono loro quelli che contano per Neeru, allora sono loro che dobbiamo colpire per primi. Questo satiro... Bazzalan, e l'altro di cui parlava Neeru (cos'era, uno stregone?) devono essere uccisi.\n\nTorna al Cleft of Shadow ed entra nel ⟦Ragefire Chasm=Baratro di Fiamma Furente⟧, {name}. Trova questi due capi della ⟦Searing Blade=Lama Rovente⟧ e uccidili. Ma fa' attenzione che Neeru non sappia che sei stat<o/a> tu. Devi conservare la tua identità di <uno/una> dei suoi <fratelli/sorelle> d'armi.", "Li hai già trovati, {name}? I capi della ⟦Searing Blade=Lama Rovente⟧.\n\nSapevo che il ⟦Shadow Council=Concilio dell'Ombra⟧ cercava di strapparmi Orgrimmar e tutta l'⟦Horde=Orda⟧, ma non mi ero reso conto di quanto in fretta fossero riusciti a infiltrarsi in città. Quante braccia ha questa bestia... possiamo tagliarle fino allo sfinimento, ma non saremo più avanti di quando abbiamo cominciato. Dovrò chiedere alle mie spie di raddoppiare gli sforzi.", "Sono lieto che tu sia tornat<o/a>, {name}. Alcuni dei miei fedeli mi hanno subito riferito che le caverne sotto Orgrimmar sono nel caos ora che i loro capi sono stati uccisi. Ho persino sentito dire che Neeru era più che agitato. Pare che abbiamo ammaccato la sua armatura. Non posso dire di esserne scontento... anche per una vittoria così piccola.", 0x2986cf2d, 0x26287695, 0x4c1cc792, 0xe00697f8, 0xa356a80b, ".....", nil, nil, 0x052ec95d, nil, nil },
  [5729] = { "Nemici nascosti", "Parla con Neeru Fireblade a Orgrimmar.", "Credo che il nostro prossimo passo debba essere metterti vicino a Neeru. Se è agitato come dicono i rapporti, potremmo ottenere due cose. Primo, potresti riuscire a sapere di più sul Consiglio, o almeno sulle ⟦Burning Blade=Lame Ardenti⟧; secondo, potrebbe cominciare a fidarsi di te abbastanza da chiederti di aiutarlo. Potrebbe benissimo vedere in te qualcuno in grado di colmare il vuoto, ora che parte dei capi è in subbuglio.\n\nTorna al Cleft e parla di nuovo con lui, ma non scoprirti troppo.", nil, "Che c'è?! Oh, sei tu, {class}... ti chiedo scusa. La mia rabbia fa concorrenza a quella di un toro kodo rabbioso... ma forse è colpa mia. Mandando dei viaggiatori nel ⟦Ragefire Chasm=Baratro di Fiamma Furente⟧, avrei dovuto prevedere che ne sarebbe potuto derivare qualche danno. Pare che sia Bazzalan sia Jergosh siano stati colti alla sprovvista e uccisi da qualche benefattore di Thrall. Un momento davvero inopportuno, ma ormai non si può più farci nulla.", 0x2986cf2d, 0x5fcb03d8, 0x09dd73b2, nil, 0x73f8739b, "...m." },
  [5730] = { "Nemici nascosti", "Parla con Thrall a Orgrimmar e riferiscigli ciò che hai scoperto.", "Sei <uno/una> dei miei luogotenenti! Preparati, {class}. Presto ti chiamerò.\n\nIl tempo che ho dedicato alla ⟦Searing Blade=Lama Rovente⟧ ormai potrebbe essere quasi sprecato, ma questo non significa che i piani del Concilio dell'Ombra altrove debbano soffrirne. Farò il possibile per limitare i danni qui nel ⟦Ragefire Chasm=Baratro di Fiamma Furente⟧. Nel frattempo, farò avviare ai miei agenti nelle ⟦Barrens=Savane⟧ e a ⟦Ashenvale=Valtetra⟧ il lavoro sul nostro nuovo progetto. Torna presto da me.", nil, "⟦Ashenvale=Valtetra⟧? Mmm, non avevo sentito di alcuna presenza del Concilio dell'Ombra o delle ⟦Burning Blade=Lame Ardenti⟧ a ⟦Ashenvale=Valtetra⟧. Le mie spie indagheranno, {name}. Hai fatto un buon lavoro.\n\nPer ora riposa, e tieniti occupat<o/a> con altri compiti. Presto ti chiamerò di nuovo.\n\nLok-Tar Ogar!", 0x2986cf2d, 0x8298346a, 0x8a8d0a1a, nil, 0x53caf27f, "...m." },
  [5741] = { "⟦Sceptre of Light=Scettro della Luce⟧", "Prendi lo ⟦Sceptre of Light=Scettro della Luce⟧ e riportalo ad Azore Aldamort, alla torre di Ethel Rethor.", "Si dice che le ⟦Burning Blade=Lame Ardenti⟧ della ⟦Thunder Axe Fortress=Fortezza Ascia del Tuono⟧, a est, si siano impadronite dello ⟦Sceptre of Light=Scettro della Luce⟧ sottraendolo ai naga. La leggenda narra che lo scettro sia capace di far sprofondare intere città sotto i grandi mari. Non si può permettere che le ⟦Burning Blade=Lame Ardenti⟧ possiedano un simile potere.\n\nPer questo devi recuperare lo scettro di persona! Lo custodisce un veggente delle ⟦Burning Blade=Lame Ardenti⟧, che lo studia dall'alto di una delle torri di guardia di Ascia del Tuono.", "Hai lo ⟦Sceptre of Light=Scettro della Luce⟧?", "L'inafferrabile ⟦Sceptre of Light=Scettro della Luce⟧! Recuperandolo hai eliminato una grave minaccia per il mondo. Ben fatto, {class}, ben fatto.", 0x50a7d789, 0x5315a126, 0xfea822cf, 0x818ecd10, 0xbc6ea27a, "....." },
  [5742] = { "Redenzione", "Ascolta ciò che Tirion Fordring ha da dire.", "Hai lavorato sodo, amico. Riposa le tue stanche ossa e lascia che mi presenti come si deve.", "Ti prego, amico, siediti e ascolta la mia storia.", "La redenzione dei Fordring sarà un compito difficile. Sei <pronto/pronta>?", 0x6cd36c83, 0x305ddac0, 0xa072e495, 0x0d71b4cb, 0x7a51c30b, "....." },
  [5761] = { "L'uccisione della bestia", "Entra nel ⟦Ragefire Chasm=Baratro di Fiamma Furente⟧ e uccidi Taragaman the Hungerer, poi porta il suo cuore a Neeru Fireblade a Orgrimmar.", "Il compito principale che mi ha affidato il nostro grande Capoguerra è stanare le creature responsabili di aver infestato con l'influenza demoniaca la grande città del nostro signore. Le ⟦Burning Blade=Lame Ardenti⟧ sono una minaccia, ma ce ne sono altre; la ⟦Searing Blade=Lama Rovente⟧, per esempio, che ha la sua base nel ⟦Ragefire Chasm=Baratro di Fiamma Furente⟧ e cerca di nascosto di corrompere membri innocenti dell'⟦Horde=Orda⟧.\n\nSe vogliamo fermarli, il loro capo deve essere ucciso: una vilguardia di nome Taragaman il Famelico.\n\nUccidilo, e il suo cuore placherà Thrall, ne sono certo.", "Hai ucciso la bestia? Dev'essere di sicuro il capo della ⟦Searing Blade=Lama Rovente⟧ nel ⟦Ragefire Chasm=Baratro di Fiamma Furente⟧.", "Ah! Ce l'hai fatta! Thrall ne sarà molto contento.\n\nMi assicurerò che di questo cuore ci si occupi come si deve.\n\nPer ora, però, devi festeggiare la tua vittoria. Informerò io Thrall del tuo successo.\n\nGrazie per il tuo aiuto, {class}.", 0x873710b1, 0xb103966d, 0x36988aea, 0x4914afb3, 0x5847a03e, "....." },
  [5762] = { nil, "Porta la ⟦Kravel's Crate=Cassa di Kravel⟧ a Hemet Nesingwary, a Rovotorto.", "Ho un pacco per un mio vecchio cliente, un nano di nome Hemet Nesingwary. Il pacco ci ha messo settimane ad arrivare, e ormai Hemet se n'è andato da un pezzo. Ha detto che andava a Rovotorto a cacciare le bestie del posto, ma mi ha lasciato del denaro per spedirgli la consegna appena potevo.\n\nHemet è un nano ricco, ed è una buona idea mantenere buoni rapporti con i ricchi, no? Allora... vuoi consegnare tu il pacco per me?\n\nHo sentito che Hemet ha un accampamento a Rovotorto, a nord di Grom'gol.", "Quella sul tuo colletto è polvere del deserto?\n\nMmm... se il naso non m'inganna, direi che non è polvere del deserto, è sale del deserto! Sei stat<o/a> alle Distese Salate, eh?", "Ottimo, il mio pacco da Koalbeard! Grazie, {name}. Questa cassa contiene munizioni di calibro speciale, e ci torneranno molto utili là fuori nella giungla!\n\nEcco la tua paga. E dimmi, come se la passa quel vecchio burbero di Kravel? Scommetto che ne combina sempre qualcuna...", 0xe0d7815a, 0x404d2976, 0x2bdcc27d, 0xc54cf9e3, 0x5e499535, "e...." },
  [5763] = { "A caccia a Rovotorto", "Porta il ⟦Roon's Kodo Horn=Corno di Kodo di Roon⟧ a Hemet Nesingwary, a Rovotorto.", "Molto tempo fa, un nano giunse in questa terra. Si chiamava Hemet e desiderava cacciare grandi bestie. La sua abilità con il fucile era prodigiosa, e passammo molti giorni a cacciare insieme. Persino l'inimicizia tra i nostri popoli fu dimenticata.\n\nQuando lasciò ⟦Desolace=Desolanda⟧ per Rovotorto, giurai che un giorno lo avrei accolto di nuovo, perché potessimo cacciare ancora. Ora è giunto quel momento.\n\nPorta questo corno di kodo a Hemet. Saprà che viene da me. Lo troverai a Rovotorto, a nord del Forte di Grom'gol.", "Siediti, {class}. Presto tornerai a colpire nella giungla.", "Ah, questo corno appartiene a un tauren, Roon Wildmane. Lui e io ci siamo divertiti un mondo a cacciare le bestie di ⟦Desolace=Desolanda⟧. Quindi Roon mi invita a tornare, eh?\n\nAdesso siamo nella giungla fino al collo, ma grazie, {name}. Forse la mia prossima spedizione mi riporterà a ⟦Desolace=Desolanda⟧, la terra dei centauri.", 0x4f9db5c4, 0x56715844, 0x7dbb31ff, 0x951011b7, 0x254429ff, "....." },
  [5781] = { "Ricordi dimenticati", "Raggiungi la Cripta di Zaeldarr, all'estremità meridionale delle ⟦Eastern Plaguelands=Terre Infette Orientali⟧, e recupera il ⟦Taelan's Hammer=Martello di Taelan⟧. Torna da Tirion Fordring quando avrai finito.", "Per aiutare Taelan a ritrovare ciò che ha perduto, devi raccogliere oggetti del suo passato.\n\nIl primo è un giocattolo che gli regalai per il suo 7° compleanno. Era la cosa a cui teneva di più: un martello da guerra in miniatura, la copia esatta del mio.\n\nQuando fui esiliato per tradimento, sua madre gli disse che ero morto. Lo portarono alla mia falsa tomba nella Cripta di Zaeldarr, dove seppellì il martello insieme al mio ricordo, per sempre.\n\nDevi andare nella Cripta di Zaeldarr e recuperare il martello di Taelan.", "Deve essere redento.", "<Tirion sbatte le palpebre per trattenere le lacrime.>\n\nEra destino che ci incontrassimo, {name}. Mi hai benedetto con la tua gentilezza.", 0x1d992727, 0xbd7cdebd, 0x537bd35c, 0x15f5081b, 0x9741ab3c, "....." },
  [5801] = { "Forgiata al Rilievo del Magma Colante", "Porta lo ⟦Skeleton Key Mold=Stampo della Chiave Universale⟧ e 2 Lingotto di Torio in cima al ⟦Fire Plume Ridge=Rilievo del Magma Colante⟧, nel ⟦Un'Goro Crater=Cratere di Un'Goro⟧. Usa lo ⟦Skeleton Key Mold=Stampo della Chiave Universale⟧ vicino al lago di lava per forgiare la ⟦Unfinished Skeleton Key=Chiave Universale Incompiuta⟧.\n\nPorta la ⟦Unfinished Skeleton Key=Chiave Universale Incompiuta⟧ all'alchimista Arbington, alla ⟦Chillwind Point=Gola di Ventofreddo⟧, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧.", "Ti servono due lingotti di torio e una fonte di calore potentissima per forgiare l'asta della chiave. Per il torio ti arrangi, ma per il calore posso darti una mano.\n\nA ovest di qui, nel ⟦Un'Goro Crater=Cratere di Un'Goro⟧, c'è il ⟦Fire Plume Ridge=Rilievo del Magma Colante⟧, un vulcano in ebollizione. Il lago di lava lassù in cima è caldo abbastanza da fondere insieme torio e ossa. Con il tuo oro ti sei comprat<o/a> uno stampo che basta immergere nel lago lassù; al resto penserà la lava.\n\nDa parte mia è tutto. Per finire la chiave dovrai parlare di nuovo con Arbington.", "Hai finito l'asta della chiave scheletrica? Mi dispiace che tu abbia dovuto sobbarcarti il costo dello stampo, ma dobbiamo tutti fare la nostra parte contro il Flagello. Quando mi darai la chiave incompiuta, sarai pront<o/a> per l'ultimo elemento che serve a completarla.\n\nNon sarà per niente facile, ma il lavoro che hai fatto finora per preparare l'assalto ad Andorhal comincerà a ripagarsi. Vedrai.", "Ci è costata parecchio questa chiave universale, eh, {name}? Eppure è ancora incompiuta; è giunto il momento di concentrarci sulla nostra creazione. Per questo dovrai affrontare il nemico supremo che ci prepariamo ad affrontare ad Andorhal... l'essere malvagio che comanda dentro le mura della città in rovina.\n\nParlo di Araj l'Evocatore, un lich, uno degli esseri più potenti che il Flagello annoveri tra i suoi.", 0x83cc7eb7, 0xd632e8fa, 0xfbf7c301, 0x54794b91, 0xa5094d5a, "....." },
  [5802] = { "Forgiata al Rilievo del Magma Colante", "Porta lo ⟦Skeleton Key Mold=Stampo della Chiave Universale⟧ e 2 Lingotto di Torio in cima al ⟦Fire Plume Ridge=Rilievo del Magma Colante⟧, nel ⟦Un'Goro Crater=Cratere di Un'Goro⟧. Usa lo ⟦Skeleton Key Mold=Stampo della Chiave Universale⟧ vicino al lago di lava per forgiare la ⟦Unfinished Skeleton Key=Chiave Universale Incompiuta⟧.\n\nPorta la ⟦Unfinished Skeleton Key=Chiave Universale Incompiuta⟧ allo speziale Dithers, alla Granbarricata, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧.", "Ti servono due lingotti di torio e una fonte di calore potentissima per forgiare l'asta della chiave. Per il torio ti arrangi, ma per il calore posso darti una mano.\n\nA ovest di qui, nel ⟦Un'Goro Crater=Cratere di Un'Goro⟧, c'è il ⟦Fire Plume Ridge=Rilievo del Magma Colante⟧, un vulcano in ebollizione. Il lago di lava lassù in cima è caldo abbastanza da fondere insieme torio e ossa. Con il tuo oro ti sei comprat<o/a> uno stampo che basta immergere nel lago lassù; al resto penserà la lava.\n\nDa parte mia è tutto. Per finire la chiave dovrai parlare di nuovo con Dithers.", "Hai finito l'asta della chiave scheletrica? Mi dispiace davvero che tu abbia dovuto sobbarcarti il costo dello stampo, ma dobbiamo tutti fare la nostra parte contro il Flagello. Quando mi darai la chiave incompiuta, sarai pront<o/a> per l'ultimo elemento che serve a completarla.\n\nNon sarà per niente facile, ma il lavoro che hai fatto finora per preparare l'assalto ad Andorhal comincerà a ripagarsi. Vedrai.", "Ci è costata parecchio questa chiave universale, eh, {name}? Eppure è ancora incompiuta; è giunto il momento di concentrarci sulla nostra creazione. Per questo dovrai affrontare il nemico supremo che ci prepariamo ad affrontare ad Andorhal... l'essere che comanda dentro le mura della città in rovina.\n\nParlo di Araj l'Evocatore, un lich, uno degli esseri più potenti che il Flagello annoveri tra i suoi.", 0x83cc7eb7, 0xfe8b3d2e, 0x27820a2f, 0x5ca18687, 0xa2278f31, "....." },
  [5803] = { "⟦Araj's Scarab=Scarabeo Araj⟧", "Distruggi Araj the Summoner e porta lo ⟦Araj's Scarab=Scarabeo Araj⟧ all'alchimista Arbington alla ⟦Chillwind Point=Gola di Ventofreddo⟧, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧.", "Araj l'Evocatore domina Andorhal dal cuore della città in rovina. Sappiamo che era il capo di Scholomance prima di prendersi la città. Per completare la chiave ci servirà il suo sigillo, detto scarabeo, montato come testa della chiave.\n\nRaggiungi il cuore di Andorhal e spezza il suo dominio sulla città, ora che è uscito allo scoperto. Una volta distrutto, strappa lo scarabeo al suo filatterio caduto!\n\nLa chiave di Scholomance ti aspetta, {name}!", "Sei arrivat<o/a> fin qui, {name}: solo la distruzione della forma fisica di Araj l'Evocatore ci darà i mezzi per completare la chiave. Prendi lo scarabeo di Araj con qualsiasi mezzo e portamelo: lo fonderò come testa della chiave.", "Sì, è proprio questo! Io... ancora una volta, sono assolutamente sbalordito dalla profondità del tuo eroismo. È incredibile fin dove sei dispost<o/a> ad arrivare per trionfare sulle forze dell'oscurità.\n\nPermettimi ora di fare la mia piccola parte. Ho preparato un solvente speciale che dovrebbe permettermi di fissare lo scarabeo come testa della chiave, infondendole il potere di aprire la porta sbarrata di Scholomance.\n\nVediamo un po'...", 0x40d2625d, 0xdc731f0e, 0x02a5ce97, 0x7c050df0, 0x94b2e77e, "....." },
  [5804] = { "⟦Araj's Scarab=Scarabeo Araj⟧", "Distruggi Araj the Summoner e porta lo ⟦Araj's Scarab=Scarabeo Araj⟧ allo speziale Dithers alla Granbarricata, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧.", "Araj l'Evocatore domina Andorhal dal cuore della città in rovina. Sappiamo che era il capo di Scholomance prima di prendersi la città. Per completare la chiave ci servirà il suo sigillo, detto scarabeo, montato come testa della chiave.\n\nRaggiungi il cuore di Andorhal e spezza il suo dominio sulla città, ora che è uscito allo scoperto. Una volta distrutto, strappa lo scarabeo al suo filatterio caduto!\n\nLa chiave di Scholomance ti aspetta, {name}!", "Sei arrivat<o/a> fin qui, {name}: solo la distruzione della forma fisica di Araj l'Evocatore ci darà i mezzi per completare la chiave. Prendi lo scarabeo di Araj, con le buone o con le cattive, e portamelo: lo fonderò come testa della chiave.", "Sì, è proprio questo! Io... ancora una volta, sono assolutamente sbalordito dalla profondità della tua astuzia e del tuo coraggio. È incredibile fin dove sei dispost<o/a> ad arrivare pur di vincere.\n\nPermettimi ora di fare la mia piccola parte. Ho preparato un solvente speciale che dovrebbe permettermi di fissare lo scarabeo come testa della chiave, infondendole il potere di aprire la porta sbarrata di Scholomance.\n\nCi vorrà solo un attimo...", 0x40d2625d, 0x65f60fe7, 0x02a5ce97, 0x2a6adaec, 0x23815c28, "....." },
  [5805] = { "Benvenut<o/a>!", "Porta il Buono Regalo della ⟦Northshire=Contea del Nord⟧ a Merissa Stilwell.", "Benvenut<o/a> in World of Warcraft!\n\nCome ringraziamento speciale per aver acquistato la Collector's Edition di World of Warcraft, consegna questo buono regalo a Merissa Stilwell nella ⟦Northshire Valley=Valle della Contea del Nord⟧. Riceverai in cambio un dono: un piccolo compagno che ti accompagnerà nella tua ricerca di avventura e gloria.\n\nGrazie ancora, e buona permanenza nel mondo di World of Warcraft!", "Salve! È un piacere conoscerti!\n\nVedo che hai un buono speciale. Dammelo e ti offrirò qualcosa in cambio.", "Sei davvero un<o/a> eroe speciale, {name}. Ti diamo il benvenuto nel mondo di Azeroth e ti offriamo uno di questi doni unici!", 0xd6adcb4f, 0x507c2857, 0x1a0e6aca, 0x2524e445, 0x4c44dc2c, "....." },
  [5821] = { "Guardia del corpo a pagamento", "Scorta la ⟦Gizelton Caravan=Carovana di Lentecurva⟧ oltre il villaggio dei centauri Kolkar. Parla con Smeed all'⟦Scrabblescrew's Camp=Accampamento di Torcivite⟧ per la ricompensa.", "In circostanze normali, io e Rigger guidiamo i nostri kodo oltre i centauri Kolkar. Ogni tanto sentiamo i tamburi di guerra dei centauri, e quando li sentiamo ci fermiamo. Morire non fa bene agli affari!\n\nFacciamo così, {class}: se ci proteggi finché non avremo superato il villaggio dei Kolkar, ne varrà la pena per te.\n\nÈ solo un breve tratto: devi solo tenere intatta la carovana, e potrai ritirare la ricompensa da Smeed Scrabblescrew, poco più avanti lungo la strada. Facciamo un po' di affari insieme.", "Perché mi ritrovo ad aspettare quella maledetta carovana?\n\n<Smeed ha un'illuminazione.>\n\nAh, già, sono loro a pagare i conti. Li hai visti?", "Sai, non mi sembra un buon affare pagare quelli come te per fare la guardia alla ⟦Gizelton Caravan=Carovana di Lentecurva⟧. {class}, se fossi un po' più alto potrei prendermi un secondo lavoro e sedermi all'amazzone su un kodo con il fucile più grosso che le mie mani possano reggere... e farei vedere io a quei maledetti centauri chi comanda.", 0x998f3fc8, 0x0697bce1, 0xa4b4d23d, 0x65827a69, 0xb6a810e3, "....." },
  [5841] = { "Benvenut<o/a>!", "Porta il Buono Regalo della ⟦Coldridge Valley=Valle Crestafredda⟧ a Yori Crackhelm.", "Benvenut<o/a> in World of Warcraft!\n\nCome ringraziamento speciale per aver acquistato la Collector's Edition di World of Warcraft, consegna questo buono regalo a Yori Crackhelm nella ⟦Coldridge Valley=Valle Crestafredda⟧. Riceverai in cambio un dono: un piccolo compagno che ti accompagnerà nella tua ricerca di avventura e gloria.\n\nGrazie ancora, e buona permanenza nel mondo di World of Warcraft!", "Salve! È un piacere conoscerti!\n\nVedo che hai un buono speciale. Dammelo e ti offrirò qualcosa in cambio.", "Sei davvero un<o/a> eroe speciale, {name}. Ti diamo il benvenuto nel mondo di Azeroth e ti offriamo uno di questi doni unici!", 0xd6adcb4f, 0x76066af0, 0x1ef929e0, 0xaec8f595, 0x4c44dc2c, "....." },
  [5842] = { "Benvenut<o/a>!", "Porta il Buono Regalo di ⟦Shadowglen=Vallombra⟧ a Orenthil Whisperwind.", "Benvenut<o/a> in World of Warcraft!\n\nCome ringraziamento speciale per aver acquistato la Collector's Edition di World of Warcraft, consegna questo buono regalo a Orenthil Whisperwind a ⟦Shadowglen=Vallombra⟧. Riceverai in cambio un dono: un piccolo compagno che ti accompagnerà nella tua ricerca di avventura e gloria.\n\nGrazie ancora, e buona permanenza nel mondo di World of Warcraft!", "Salve! È un piacere conoscerti!\n\nVedo che hai un buono speciale. Dammelo e ti offrirò qualcosa in cambio.", "Sei davvero un<o/a> eroe speciale, {name}. Ti diamo il benvenuto nel mondo di Azeroth e ti offriamo uno di questi doni unici!", 0xd6adcb4f, 0x30f931f5, 0x98375d78, 0x2524e445, 0x4c44dc2c, "....." },
  [5843] = { "Benvenut<o/a>!", "Porta il Buono Regalo della ⟦Valley of Trials=Valle delle Sfide⟧ a Magga.", "Benvenut<o/a> in World of Warcraft!\n\nCome ringraziamento speciale per aver acquistato la Collector's Edition di World of Warcraft, consegna questo buono regalo a Magga nella ⟦Valley of Trials=Valle delle Sfide⟧. Riceverai in cambio un dono: un piccolo compagno che ti accompagnerà nella tua ricerca di avventura e gloria.\n\nGrazie ancora, e buona permanenza nel mondo di World of Warcraft!", "Salve! È un piacere conoscerti!\n\nVedo che hai un buono speciale. Dammelo e ti offrirò qualcosa in cambio.", "Sei davvero un<o/a> eroe speciale, {name}. Ti diamo il benvenuto nel mondo di Azeroth e ti offriamo uno di questi doni unici!", 0xd6adcb4f, 0x805611c0, 0xbebd6483, 0xaec8f595, 0x4c44dc2c, "....." },
  [5844] = { "Benvenut<o/a>!", "Porta il Buono Regalo del ⟦Camp Narache=Campo Narache⟧ a Vorn Skyseer.", "Benvenut<o/a> in World of Warcraft!\n\nCome ringraziamento speciale per aver acquistato la Collector's Edition di World of Warcraft, consegna questo buono regalo a Vorn Skyseer al ⟦Camp Narache=Campo Narache⟧. Riceverai in cambio un dono: un piccolo compagno che ti accompagnerà nella tua ricerca di avventura e gloria.\n\nGrazie ancora, e buona permanenza nel mondo di World of Warcraft!", "Salve! È un piacere conoscerti!\n\nVedo che hai un buono speciale. Dammelo e ti offrirò qualcosa in cambio.", "Sei davvero un<o/a> eroe speciale, {name}. Ti diamo il benvenuto nel mondo di Azeroth e ti offriamo uno di questi doni unici!", 0xd6adcb4f, 0xbba6f3d6, 0x9ab96af7, 0x2524e445, 0x4c44dc2c, "....." },
  [5845] = { "Dell'onore perduto", "Raggiungi ⟦Northdale=Valnordia⟧, nella regione nord-orientale delle ⟦Eastern Plaguelands=Terre Infette Orientali⟧, e recupera il ⟦Symbol of Lost Honor=Simbolo dell'Onor Perduto⟧. Torna da Tirion Fordring quando avrai completato l'obiettivo.", "L'Ordine della ⟦Silver Hand=Mano d'Argento⟧ fu completamente decimato quando Uther venne ucciso.\n\nIl ragazzo resistette finché poté. Spinto fino al villaggio di ⟦Northdale=Valnordia⟧, devastato dalla guerra, vi combatté la sua ultima battaglia.\n\nEra rimasto in vita qualcuno dell'Ordine, si chiese... e aveva importanza?\n\nFu con quel pensiero che Taelan gettò a terra lo stendardo dell'Ordine e rinnegò tutto ciò che aveva conosciuto. Il suo onore rimase sul suolo intriso di sangue di ⟦Northdale=Valnordia⟧.\n\nDevi andare a ⟦Northdale=Valnordia⟧ e recuperare quel simbolo dell'onore perduto.", "La mia fede ti guiderà, {name}. La Luce non conosce confini.", "È glorioso ora, anche così logoro, come il giorno in cui lo vidi e prestai il mio giuramento di fedeltà.\n\nLa sua redenzione è vicina, e forse con essa anche la mia...", 0xead3f134, 0xa711412a, 0x8dc5f92c, 0x43f6b880, 0x8edec1d7, "....." },
  [5846] = { "⟦Of Love and Family=Amore e Famiglia⟧", "Raggiungi l'isola di Caer Darrow, nella parte centro-meridionale delle ⟦Plaguelands=Terre Infette⟧, e cerca qualunque indizio su dove si trovi il dipinto.", "Quando Taelan era bambino, andavamo spesso a Caer Darrow durante le gite di famiglia. Nella nostra ultima visita, un pittore di nome Renfray ci ritrasse in posa sulla spiaggia. È il ricordo più caro che ho di Taelan e di Karandra. Perché fu in quel momento, con mia moglie e mio figlio tra le braccia, che sentii un legame d'amore e di famiglia che non avrei mai più conosciuto.\n\nSe quel dipinto esiste ancora, devi trovarlo.\n\nRaggiungi l'isola in rovina di Caer Darrow e scopri se il dipinto o il pittore ci sono ancora.", nil, "Come potrei dimenticare? Molti degli spiriti di quest'isola sono condannati a rivivere il loro ultimo ricordo felice, prima della loro tragica fine.\n\nAnch'io sono maledetto, ma non come loro: sono uno dei pochi che ricordano tutto...\n\nForse ciò che mi chiedi è il motivo per cui infesto queste rovine. Forse ciò che ti dirò mi renderà libero.", 0x2e3d92e4, 0x8e686d8f, 0xb8d96ce4, nil, 0xd13e736b, "...m." },
  [5847] = { "Benvenut<o/a>!", "Porta il Buono Regalo di ⟦Deathknell=Albamorta⟧ a Claire Willower ad ⟦Deathknell=Albamorta⟧.", "Benvenut<o/a> in World of Warcraft!\n\nCome ringraziamento speciale per aver acquistato la Collector's Edition di World of Warcraft, consegna questo buono regalo a Claire Willower ad ⟦Deathknell=Albamorta⟧. Riceverai in dono un piccolo compagno che ti accompagnerà nella tua ricerca di avventura e gloria.\n\nGrazie ancora, e buona permanenza in World of Warcraft!", "Salve! È un piacere conoscerti!\n\nVedo che hai un buono speciale. Dammelo e ti offrirò qualcosa in cambio.", "Sei davvero un<o/a> eroe speciale, {name}. Ti diamo il benvenuto nel mondo di Azeroth e ti offriamo uno di questi doni unici!", 0xd6adcb4f, 0x1cf17152, 0x1b055ef2, 0x2524e445, 0x4c44dc2c, "....." },
  [5848] = { "⟦Of Love and Family=Amore e Famiglia⟧", "Raggiungi Stratholme, nella parte settentrionale delle ⟦Plaguelands=Terre Infette⟧. È nello Scarlet Bastion che troverai il dipinto '⟦Of Love and Family=Amore e Famiglia⟧', nascosto dietro un altro dipinto che raffigura le due lune del nostro mondo.\n\nRiporta il dipinto a Tirion Fordring.", "Il dipinto... È rimasto appeso per anni alla parete del mio laboratorio, nella caserma dell'Ordine.\n\nDopo il processo a Tirion, sapevo di non poterlo più tenere in vista. L'ho nascosto in un posto dove non avrebbero mai pensato di cercare.\n\nRaggiungi Stratholme e addentrati in quello che ora è lo Scarlet Bastion, poi cerca un dipinto delle nostre due lune. Gratta via la vernice finché non scoprirai il mio capolavoro, '⟦Of Love and Family=Amore e Famiglia⟧'.\n\nChe la Luce guidi le tue azioni.", "Il dipinto, {name}. Hai il dipinto?", "<Tirion per poco non crolla quando vede il dipinto.>\n\n<Comincia a singhiozzare in modo quasi frenetico.>", 0x2e3d92e4, 0x087c7818, 0x7fecbed3, 0x0606e29d, 0x90e5761d, "....." },
  [5861] = { "Trovare Myranda", "Raggiungi il ⟦Uther's Tomb=Sepolcro di Uther⟧, nelle ⟦Plaguelands=Terre Infette⟧ meridionali. Mostra il ⟦Tirion's Gift=Dono di Tirion⟧ a Myranda la Megera.", "{name}, finora hai fatto tutto ciò che ti ho chiesto. Resta un solo passo nella tua missione di redenzione.\n\nDevi consegnare a Taelan gli oggetti che hai raccolto. Purtroppo Taelan e i suoi crociati ti attaccheranno a vista.\n\nC'è un solo modo per recapitare il mio messaggio: con l'inganno.\n\nA sud troverai il Sepolcro di Uther. Lì vive ora Myranda, una mia vecchia confidente fidata: cercala. Mostrale gli oggetti e ti aiuterà.", "Sapevo che questo giorno sarebbe arrivato.", "Ero la consigliera più fidata di Tirion quando aveva il rango di signore di Mardenholde. Mi opposi apertamente al verdetto emesso dall'Ordine della ⟦Silver Hand=Mano d'Argento⟧ e fui esiliata per la mia insolenza.\n\nHa sopportato molto dolore e molte delusioni nella sua vita, {race}. Sei <pronto/pronta> a riparare i torti subiti dai Fordring?", 0x22b4fc0c, 0x4f73da99, 0x664166f9, 0x8e458cc7, 0xf937f539, "....." },
  [5862] = { "Sotterfugio scarlatto", "Parla con Myranda per ottenere l'⟦Scarlet Illusion=Illusione Scarlatta⟧. Raggiungi ⟦Hearthglen=Valsalda⟧ sotto l'effetto dell'⟦Scarlet Illusion=Illusione Scarlatta⟧ e consegna il ⟦Tirion's Gift=Dono di Tirion⟧ al gran signore Taelan Fordring.\n\n⟦Hearthglen=Valsalda⟧ si trova a nord; Taelan dovrebbe essere all'interno del ⟦Mardenholde Keep=Forte Mardenholde⟧.", "Sono ciò che si potrebbe chiamare un'illusionista. Anche se posso creare un'illusione che ti permetta di entrare a ⟦Hearthglen=Valsalda⟧, sappi una cosa: i miei poteri hanno dei limiti.\n\nSe ti allontanerai troppo da queste terre, l'effetto dell'illusione svanirà. L'incantesimo stesso mi richiede grande concentrazione e molto potere, perciò posso mantenerne l'effetto solo per poco tempo.\n\nParlami di nuovo quando sarai <pronto/pronta>.", "Sei dei rinforzi arrivati dalla ⟦Tyr's Hand=Mano di Tyr⟧?", "Cos'è questo, soldato?\n\n<Taelan apre la scatola e comincia a esaminarne il contenuto.>\n\nQuesto... questo non può essere vero. Eppure tutto ciò che mi hai mostrato...\n\n<Taelan cade su un ginocchio, il suo cuore batte più forte. La furia di intere ere sta per abbattersi su questa città.>", 0x381c7f37, 0xe3897007, 0x987323c5, 0xf0a0fb97, 0x97738e7f, "....." },
  [5863] = { "L'⟦Dunemaul Compound=Insediamento dei Mazzaduna⟧", "Andi Lynn, a ⟦Gadgetzan=Meccania⟧, vuole che tu distrugga l'⟦Dunemaul Compound=Insediamento dei Mazzaduna⟧ uccidendo 10 Dunemaul Brute, 10 Dunemaul Enforcer e Gor'marok the Ravager.", "Da poco un grosso gruppo di ogre nomadi è arrivato a Tanaris. A sud di qui hanno occupato una vasta zona del deserto e vi hanno costruito un insediamento. Diverse bande più piccole vagano per il deserto, e alcune hanno invaso le antiche rovine dei troll.\n\nL'⟦Dunemaul Compound=Insediamento dei Mazzaduna⟧ va distrutto! Non possiamo permettere a questi ogre di radunare un esercito.\n\nIl capo di questa banda si chiama Gor'marok il Devastatore; credo che porre fine al suo comando sarà l'inizio della fine per gli ogre.", "Che ansia! Ti prego, fa' attenzione!", "Che gioia, sei riuscit<o/a> a farlo per me, {name}! Grazie per l'aiuto!", 0xd39604a7, 0xc8426bdf, 0xf7ee5218, 0x1d17f52b, 0x0ae27f9d, "....." },
  [5881] = { "Il richiamo delle riserve", "Maggran vuole che tu consegni una lettera a Grish Longrunner, al Grande Ascensore nelle ⟦Barrens=Savane⟧.", "L'⟦Horde=Orda⟧ fa bene a tenere fresche le nostre truppe... dalla Grande Guerra qui a Kalimdor abbiamo prosperato.\n\nHo bisogno che tu mi faccia un favore. Ho un ragazzo di nome Grish Longrunner che protegge il Grande Ascensore, nelle Savane meridionali. Dagli questa lettera: lo informerà che sta arrivando un guerriero di riserva a dargli il cambio, così potrà andare a trovare la sua famiglia. L'aveva chiesto qualche tempo fa e sarà felice di sentire la notizia.", "Hai notizie da Maggran Earthbinder?", "Questa sì che è una bella notizia; sto qui a sorvegliare questo pezzo di legno da troppo tempo. Ora potrò passare un po' di tempo con la mia famiglia... Evviva!", 0x43b6d403, 0x9b65dff0, 0x68d44f68, 0xb6afe6ee, 0x6ac36c0d, "....." },
  [5882] = { "Unguento dalla caccia", nil, nil, "Con un Rilevatore Cenariano si può vedere un Frammento d'Anima Corrotto sulle bestie contaminate che vengono abbattute per il bene superiore. Io macino i frammenti fino a ricavarne un reagente che serve a preparare l'Unguento per Piante Cenariano. Useremo quell'unguento per far tornare sane le piante corrotte.\n\nIn cambio di questi frammenti, ti darò un po' di Unguento per Piante Cenariano che ho già preparato.", "Molto bene, ecco il tuo Unguento per Piante Cenariano. Perlustra ⟦Felwood=Vilbosco⟧ in cerca di piante corrotte, {name}! Ovunque si trovino, usa l'unguento che ti ho dato per purificarle.", 0x531b3091, nil, nil, 0xdedb609b, 0x944389af, ".mm.." },
  [5883] = { "Unguento dall'estrazione", nil, nil, "Se hai con te un Rilevatore Cenariano mentre estrai minerali a ⟦Felwood=Vilbosco⟧, potrai vedere il Vetriolo Corrotto che contamina un filone di metallo grezzo. So come purificare quel vetriolo e trasformarlo in un reagente che serve a preparare l'Unguento per Piante Cenariano. Poi userai quell'unguento sulle piante da salvare che troverai nella natura.\n\nSe hai raccolto del Vetriolo Corrotto, ti darò un po' di Unguento per Piante Cenariano che ho già preparato.", "Molto bene, ecco un po' di Unguento per Piante Cenariano. Se trovi altro vetriolo quando estrai minerali a ⟦Felwood=Vilbosco⟧, ricordati di tenerlo per me! Più ne trovi, più unguento potrò preparare.", 0x7f2307ff, nil, nil, 0x9d7a3c30, 0x6e2eea1b, ".mm.." },
  [5884] = { "Unguento dalla raccolta", nil, nil, "Un Rilevatore Cenariano permette a un erborista esperto di individuare l'insidiosa Vilerba, un frutto maligno della corruzione di ⟦Felwood=Vilbosco⟧. Il mio lavoro qui mi ha insegnato a purificare la Vilerba trasformandola in un reagente purificante... usato in quello che ora chiamiamo Unguento per Piante Cenariano.\n\nQuando raccogli erbe a ⟦Felwood=Vilbosco⟧, dovresti trovare la Vilerba, purché tu abbia il rilevatore. In cambio di ciò che mi porterai, ti darò dell'Unguento per Piante Cenariano già pronto.", "Ottimo lavoro, {name}: ogni briciolo di questo, una volta purificato, ci aiuterà a riprendere ⟦Felwood=Vilbosco⟧. Ecco, prendi qualche dose di Unguento per Piante Cenariano e addentrati nella foresta. La riconquista della terra dalla corruzione non aspetta nessun {race}!", 0xc206b641, nil, nil, 0xfeee85f3, 0x45ed0202, ".mm.." },
  [5885] = { "Unguento dalla scuoiatura", nil, nil, "Un Rilevatore Cenariano permette a uno scuoiatore ben addestrato di individuare i Pezzi di Pelle Corrotta sulle prede cacciate a ⟦Felwood=Vilbosco⟧. Io trasformo questi pezzi apparentemente inutili in una pasta densa che fa da acceleratore per l'Unguento per Piante Cenariano. Quando scuoi le tue prede qui a ⟦Felwood=Vilbosco⟧, assicurati di avere con te un rilevatore!\n\nQuando raccogli dei pezzi di pelle corrotta, portameli e ti darò un po' di Unguento per Piante Cenariano che ho già preparato.", "È proprio ciò che mi serve. Ecco, prendi questi unguenti per piante e usali per strappare ⟦Felwood=Vilbosco⟧ alla corruzione. Dobbiamo perseverare, {name}!", 0x4791f5d6, nil, nil, 0x7bb6e789, 0x3b679069, ".mm.." },
  [5886] = { "Unguento dal disincantamento", nil, nil, "Il potere di un oggetto magico disincantato si percepisce dall'essenza che produce. Ho escogitato un modo per trasformare l'essenza grezza usata dagli incantatori in un reagente adatto a creare l'Unguento per Piante Cenariano. Per questo non ti serve un Rilevatore Cenariano: va bene qualsiasi oggetto che, disincantato, dia una Lesser Nether Essence.\n\nMi basta una sola Lesser Nether Essence; in cambio ti darò dell'Unguento per Piante Cenariano. L'essenza è potentissima: ne basta davvero poca!", "Ecco un po' di Unguento per Piante Cenariano: per questo mi basta una sola Lesser Nether Essence, {name}. L'essenza è di gran lunga la cosa più potente che io possa usare per trasformare le spade in aratri, per così dire. Se ti serve altro unguento, mi trovi qui!", 0xdb31ab2a, nil, nil, 0x01b0d33a, 0x84936fd1, ".mm.." },
  [5887] = { "Unguento dalla caccia", nil, nil, "Con un Rilevatore Cenariano si può vedere un Frammento d'Anima Corrotto sulle bestie contaminate che vengono abbattute per il bene superiore. Io macino i frammenti fino a ricavarne un reagente che serve a preparare l'Unguento per Piante Cenariano. Useremo quell'unguento per far tornare sane le piante corrotte.\n\nIn cambio di questi frammenti, ti darò un po' di Unguento per Piante Cenariano che ho già preparato.", "Molto bene, ecco il tuo Unguento per Piante Cenariano. Perlustra ⟦Felwood=Vilbosco⟧ in cerca di piante corrotte, {name}! Ovunque si trovino, usa l'unguento che ti ho dato per purificarle.", 0x531b3091, nil, nil, 0xdedb609b, 0x944389af, ".mm.." },
  [5888] = { "Unguento dall'estrazione", nil, nil, "Se hai con te un Rilevatore Cenariano mentre estrai minerali a ⟦Felwood=Vilbosco⟧, potrai vedere il Vetriolo Corrotto che contamina un filone di metallo grezzo. So come purificare quel vetriolo e trasformarlo in un reagente che serve a preparare l'Unguento per Piante Cenariano. Poi userai quell'unguento sulle piante da salvare che troverai nella natura.\n\nSe hai raccolto del Vetriolo Corrotto, ti darò un po' di Unguento per Piante Cenariano che ho già preparato.", "Molto bene, ecco un po' di Unguento per Piante Cenariano. Se trovi altro vetriolo quando estrai minerali a ⟦Felwood=Vilbosco⟧, ricordati di tenerlo per me! Più ne trovi, più unguento potrò preparare.", 0x7f2307ff, nil, nil, 0x9d7a3c30, 0x6e2eea1b, ".mm.." },
  [5889] = { "Unguento dalla raccolta", nil, nil, "Un Rilevatore Cenariano permette a un erborista esperto di individuare l'insidiosa Vilerba, un frutto maligno della corruzione di ⟦Felwood=Vilbosco⟧. Il mio lavoro qui mi ha insegnato a purificare la Vilerba trasformandola in un reagente purificante... usato in quello che ora chiamiamo Unguento per Piante Cenariano.\n\nQuando raccogli erbe a ⟦Felwood=Vilbosco⟧, dovresti trovare la Vilerba, purché tu abbia il rilevatore. In cambio di ciò che mi porterai, ti darò dell'Unguento per Piante Cenariano già pronto.", "Ottimo lavoro, {name}: ogni briciolo di questo, una volta purificato, ci aiuterà a riprendere ⟦Felwood=Vilbosco⟧. Ecco, prendi qualche dose di Unguento per Piante Cenariano e addentrati nella foresta. La riconquista della terra dalla corruzione non aspetta nessun {race}!", 0xc206b641, nil, nil, 0xfeee85f3, 0x45ed0202, ".mm.." },
  [5890] = { "Unguento dalla scuoiatura", nil, nil, "Un Rilevatore Cenariano permette a uno scuoiatore ben addestrato di individuare i Pezzi di Pelle Corrotta sulle prede cacciate a ⟦Felwood=Vilbosco⟧. Io trasformo questi pezzi apparentemente inutili in una pasta densa che fa da acceleratore per l'Unguento per Piante Cenariano. Quando scuoi le tue prede qui a ⟦Felwood=Vilbosco⟧, assicurati di avere con te un rilevatore!\n\nQuando raccogli dei pezzi di pelle corrotta, portameli e ti darò un po' di Unguento per Piante Cenariano che ho già preparato.", "È proprio ciò che mi serve. Ecco, prendi questi unguenti per piante e usali per strappare ⟦Felwood=Vilbosco⟧ alla corruzione. Dobbiamo perseverare, {name}!", 0x4791f5d6, nil, nil, 0x7bb6e789, 0x3b679069, ".mm.." },
  [5891] = { "Unguento dal disincantamento", nil, nil, "Il potere di un oggetto magico disincantato si percepisce dall'essenza che produce. Ho escogitato un modo per trasformare l'essenza grezza usata dagli incantatori in un reagente adatto a creare l'Unguento per Piante Cenariano. Per questo non ti serve un Rilevatore Cenariano: va bene qualsiasi oggetto che, disincantato, dia una Lesser Nether Essence.\n\nMi basta una sola Lesser Nether Essence; in cambio ti darò dell'Unguento per Piante Cenariano. L'essenza è potentissima: ne basta davvero poca!", "Ecco un po' di Unguento per Piante Cenariano: per questo mi basta una sola Lesser Nether Essence, {name}. L'essenza è di gran lunga la cosa più potente che io possa usare per trasformare le spade in aratri, per così dire. Se ti serve altro unguento, mi trovi qui!", 0xdb31ab2a, nil, nil, 0x01b0d33a, 0x84936fd1, ".mm.." },
  [5901] = { "Che la piaga ti colga", "Usa il ⟦Empty Termite Jar=Contenitore di Termiti Vuoto⟧ sui termitai delle ⟦Eastern Plaguelands=Terre Infette Orientali⟧. Dopo aver raccolto 100 ⟦Plagueland Termites=Termiti delle Terre Infette⟧, torna da Mickey Levine alla Granbarricata, nelle ⟦Tirisfal Glades=Radure di Tirisfal⟧.", "Quindi, per portare dolore e discordia alla ⟦Scarlet Crusade=Crociata Scarlatta⟧, voglio sottrarle la sua preziosa segheria. Sono sicuro che perdere una risorsa simile li danneggerà parecchio, quando dovranno difendere e ricostruire la città per i loro scopi. Mi aiuterai, {name}?\n\nComincia portando questo contenitore a ⟦Plaguewood=Malaselva⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧. Riempilo con le termiti che trovi nei termitai sparsi per i boschi. Torna quando ne avrai abbastanza.", "Hai già le termiti, {name}? Sono sicuro che per <un/una> {class} in gamba come te sia una cosa ovvia.\n\nQuando ne avremo abbastanza, faremo in modo che nessuno possa più usare la segheria!", "Andranno benissimo, {name}. Grazie.\n\nSe sei <pronto/pronta>, possiamo passare al passo successivo.", 0x4a22873d, 0x115bb474, 0x6cb4acb7, 0x98ba611f, 0x3ff3ec65, "....." },
  [5902] = { "Che la piaga ti colga", "Trova un punto adatto al centro della ⟦Lumber Mill=Segheria⟧ di Cresta Nord, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧, dove piazzare il ⟦Barrel of Plagueland Termites=Barile di Termiti delle Terre Infette⟧.", "Ora che abbiamo termiti in abbondanza, porta questo barile rinforzato d'acciaio alla ⟦Lumber Mill=Segheria⟧ di Cresta Nord, a sud di ⟦Hearthglen=Valsalda⟧: la troverai a ovest della strada che sale fino alla città.\n\nUna volta lì, piazza il barile al centro della segheria, in un punto in alto, per esempio su una cassa o qualcosa del genere.\n\nDopo che l'avrai aperto, il resto verrà da sé. Poi torna qui e ti ricompenserò per l'aiuto.", nil, "Mentre posi il barile sopra la cassa, le termiti si fanno visibilmente irrequiete.", 0x4a22873d, 0x747b27e9, 0xe797190e, nil, 0xbeaa777d, "...m." },
  [5903] = { "Che la piaga ti colga", "Usa il ⟦Empty Termite Jar=Contenitore di Termiti Vuoto⟧ sui termitai delle ⟦Eastern Plaguelands=Terre Infette Orientali⟧. Dopo aver raccolto 100 ⟦Plagueland Termites=Termiti delle Terre Infette⟧, torna da Nathaniel Dumah all'⟦Chillwind Camp=Accampamento di Ventofreddo⟧, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧.", "Ho provato molte volte a scacciare la ⟦Scarlet Crusade=Crociata Scarlatta⟧ con la sola forza, ma senza risultato. Così, come alternativa, ho deciso di rendere loro la vita più difficile.\n\nSe sei <disposto/disposta> ad aiutarmi, voglio infestare quella segheria con la specie di termiti più terribile mai scoperta.\n\nA ⟦Plaguewood=Malaselva⟧, vicino a quella che fu la grande Stratholme, c'è una razza che è sopravvissuta sia alla piaga sia al Flagello. Trova i loro termitai e riempi questo contenitore, così potremo prepararle per scatenarle sulla Crociata.", "Hai trovato i termitai, {name}? Ho sentito che a ⟦Plaguewood=Malaselva⟧ sono dappertutto.", "Andranno benissimo, {name}. Grazie. Guardale... così tante, tutte ammassate. Quasi mi dispiace per la Crociata, ma d'altronde quella segheria non era mai stata loro, no?", 0x4a22873d, 0x464b47cb, 0x0c3da530, 0x23d993f7, 0xa68d8bd1, "....." },
  [5904] = { "Che la piaga ti colga", "Trova un punto adatto al centro della ⟦Lumber Mill=Segheria⟧ di Cresta Nord, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧, dove piazzare il ⟦Barrel of Plagueland Termites=Barile di Termiti delle Terre Infette⟧.", "Ora che abbiamo le termiti, porta questo barile rinforzato in acciaio alla ⟦Lumber Mill=Segheria⟧ di Cresta Nord, a sud di ⟦Hearthglen=Valsalda⟧: la troverai a ovest della strada che sale verso la città.\n\nUna volta lì, colloca il barile al centro della ⟦Lumber Mill=Segheria⟧; trova un punto adatto, per esempio sopra una cassa, e poi aprilo. Da lì le termiti dovrebbero fare il loro lavoro e rendere la segheria inservibile per la Crociata.", nil, "Mentre posi il barile sopra la cassa, le termiti si fanno visibilmente irrequiete.", 0x4a22873d, 0x747b27e9, 0x6902aded, nil, 0xbeaa777d, "...m." },
  [5921] = { "⟦Moonglade=Radaluna⟧", "Usa l'incantesimo \"⟦Teleport: Moonglade=Teletrasporto: Radaluna⟧\" per raggiungere ⟦Moonglade=Radaluna⟧. Al tuo arrivo, parla con Dendrite Starblaze nel villaggio di ⟦Nighthaven=Nottequieta⟧.", "Tutti i druidi sono benvenuti nelle terre sacre di ⟦Moonglade=Radaluna⟧, nonostante le attuali tensioni nel ⟦Cenarion Circle=Circolo Cenariano⟧ tra l'arcidruido Staghelm e il custode Remulos, protettore di ⟦Moonglade=Radaluna⟧. Ora che stai imparando le vie dell'Artiglio, ti insegnerò l'incantesimo che ti permette di trasportarti laggiù. Lancialo ogni volta che cerchi la conoscenza o il conforto di ⟦Moonglade=Radaluna⟧.\n\nPer la tua prima lezione, raggiungi ⟦Moonglade=Radaluna⟧ e parla con Dendrite Starblaze a ⟦Nighthaven=Nottequieta⟧ del cammino che hai intrapreso. Buona fortuna, giovane <druido/druida>.", nil, "\"E così ha inizio, padre Cenarius. E così ha inizio.\"\n\nDendrite traccia nell'aria sopra di sé un gesto rapido e invisibile. Una lieve aura di potere scende su di lui.\n\n\"La prima prospettiva della natura a cui devi adattarti è quella dell'orso. Ti avvierò sulla strada per comprendere questo aspetto della vita druidica, ma sei tu che devi abbracciarlo e diffonderlo, ora e per sempre!\"", 0xaeb97c8b, 0xf8085429, 0x6d17554b, nil, 0xeca326e1, "...m." },
  [5922] = { "⟦Moonglade=Radaluna⟧", "Usa l'incantesimo \"⟦Teleport: Moonglade=Teletrasporto: Radaluna⟧\" per raggiungere ⟦Moonglade=Radaluna⟧. Al tuo arrivo, parla con Dendrite Starblaze nel villaggio di ⟦Nighthaven=Nottequieta⟧.", "Tutti i druidi sono accolti nelle terre sacre di ⟦Moonglade=Radaluna⟧, tauren ed elfi della notte allo stesso modo. Il custode Remulos, protettore di ⟦Moonglade=Radaluna⟧, veglia su tutti i druidi che vi ibernano. Ora che stai imparando le vie dell'Artiglio, ti insegnerò l'incantesimo che ti permette di trasportarti laggiù. Lancialo ogni volta che cerchi la conoscenza o il conforto di ⟦Moonglade=Radaluna⟧.\n\nPer la tua prima lezione, raggiungi ⟦Moonglade=Radaluna⟧ e parla con Dendrite Starblaze a ⟦Nighthaven=Nottequieta⟧ del cammino che hai intrapreso. Buona fortuna, giovane <druido/druida>.", nil, "\"E così ha inizio, padre Cenarius. E così ha inizio.\"\n\nDendrite traccia nell'aria sopra di sé un gesto rapido e invisibile. Una lieve aura di potere scende su di lui.\n\n\"La prima prospettiva della natura a cui devi adattarti è quella dell'orso. Ti avvierò sulla strada per comprendere questo aspetto della vita druidica, ma sei tu che devi abbracciarlo e diffonderlo, ora e per sempre!\"", 0xaeb97c8b, 0xf8085429, 0xbc279cb2, nil, 0xeca326e1, "...m." },
  [5923] = { "Rispondere alla chiamata", "Parla con Mathrengyl Bearwalker nell'⟦Cenarion Enclave=Enclave Cenariana⟧, a Darnassus.", "Scusami, amic<o/a>...\n\nMi è giunta voce che Mathrengyl Bearwalker ha fatto sapere di volerti parlare. Sembra che il tuo addestramento da <druido/druida> stia per prendere nuova vita, e sarà lui ad addestrarti di persona. Mathrengyl è l'assistente diretto dell'arcidruido in persona, ed è uno dei druidi più saggi e venerabili che troverai a Teldrassil.\n\nSi trova nell'⟦Cenarion Enclave=Enclave Cenariana⟧ di Darnassus, al secondo piano dell'albero di Fandral Staghelm.", nil, "Sono lieto che tu abbia trovato la strada fin qui oggi, giovane <druido/druida>. È giunto il momento di fare un grande passo in un mondo molto più vasto.\n\nIn ciascuno dei figli di Cenarius c'è la chiamata a servire la natura. Animali e piante sono nostri amici e al tempo stesso affidati alle nostre cure. Scegliamo di dedicare la vita a preservare l'equilibrio, per il loro bene come per il nostro. Il tuo primo passo in questo mondo sarà imparare le vie dell'orso e la forza del corpo e del cuore.\n\nPreparati!", 0xfe4e1687, 0x6c0db897, 0x30240ec9, nil, 0x2b8e0102, "...m." },
