  [5926] = { "Rispondere alla chiamata", "Parla con Turak Runetotem sull'⟦Elder Rise=Altura degli Anziani⟧ di ⟦Thunder Bluff=Picco del Tuono⟧.", "Scusami, amic<o/a>...\n\nMi è giunta voce che Turak Runetotem ha fatto sapere di volerti parlare. Sembra che il tuo addestramento da <druido/druida> stia per prendere nuova vita, e sarà lui ad addestrarti di persona. Turak è uno degli assistenti dell'arcidruido; è noto come un druido saggio e paziente, e dovrebbe insegnarti bene.\n\nSi trova a ⟦Thunder Bluff=Picco del Tuono⟧, nella tenda principale del Circolo Cenariano sull'⟦Elder Rise=Altura degli Anziani⟧.", nil, "Sono lieto che tu abbia trovato la strada fin qui oggi, giovane <druido/druida>. È giunto il momento di fare un grande passo in un mondo molto più vasto.\n\nIn ciascuno dei figli di Cenarius c'è la chiamata a servire la natura. Animali e piante sono nostri amici e al tempo stesso affidati alle nostre cure. Scegliamo di dedicare la vita a preservare l'equilibrio, per il loro bene come per il nostro. Il tuo primo passo in questo mondo sarà imparare le vie dell'orso e la forza del corpo e del cuore.\n\nPreparati!", 0xfe4e1687, 0xb75320fd, 0x1a176df1, nil, 0x8ef40860, "...m." },
  [5927] = { "Rispondere alla chiamata", "Parla con Turak Runetotem sull'⟦Elder Rise=Altura degli Anziani⟧ di ⟦Thunder Bluff=Picco del Tuono⟧.", "Scusami, amic<o/a>...\n\nMi è giunta voce che Turak Runetotem ha fatto sapere di volerti parlare. Sembra che il tuo addestramento da <druido/druida> stia per prendere nuova vita, e sarà lui ad addestrarti di persona. Turak è uno degli assistenti dell'arcidruido; è noto come un druido saggio e paziente, e dovrebbe insegnarti bene.\n\nSi trova a ⟦Thunder Bluff=Picco del Tuono⟧, nella tenda principale del Circolo Cenariano sull'⟦Elder Rise=Altura degli Anziani⟧.", nil, "Sono lieto che tu abbia trovato la strada fin qui oggi, giovane {class}. È giunto il momento di fare un grande passo in un mondo molto più vasto.\n\nIn ciascuno dei figli di Cenarius c'è la chiamata a servire la natura. Animali e piante sono nostri amici e al tempo stesso affidati alle nostre cure. Scegliamo di dedicare la vita a preservare l'equilibrio, per il loro bene come per il nostro. Il tuo primo passo in questo mondo sarà imparare le vie dell'orso e la forza del corpo e del cuore.\n\nPreparati!", 0xfe4e1687, 0xb75320fd, 0x1a176df1, nil, 0x65aa7f11, "...m." },
  [5928] = { "Rispondere alla chiamata", "Parla con Turak Runetotem sull'⟦Elder Rise=Altura degli Anziani⟧ di ⟦Thunder Bluff=Picco del Tuono⟧.", "Scusami, amic<o/a>...\n\nMi è giunta voce che Turak Runetotem ha fatto sapere di volerti parlare. Sembra che il tuo addestramento da <druido/druida> stia per prendere nuova vita, e sarà lui ad addestrarti di persona. Turak è uno degli assistenti dell'arcidruido; è noto come un druido saggio e paziente, e dovrebbe insegnarti bene.\n\nSi trova a ⟦Thunder Bluff=Picco del Tuono⟧, nella tenda principale del Circolo Cenariano sull'⟦Elder Rise=Altura degli Anziani⟧.", nil, "Sono lieto che tu abbia trovato la strada fin qui oggi, giovane {class}. È giunto il momento di fare un grande passo in un mondo molto più vasto.\n\nIn ciascuno dei figli di Cenarius c'è la chiamata a servire la natura. Animali e piante sono nostri amici e al tempo stesso affidati alle nostre cure. Scegliamo di dedicare la vita a preservare l'equilibrio, per il loro bene come per il nostro. Il tuo primo passo in questo mondo sarà imparare le vie dell'orso e la forza del corpo e del cuore.\n\nPreparati!", 0xfe4e1687, 0xb75320fd, 0x1a176df1, nil, 0x65aa7f11, "...m." },
  [5929] = { nil, "Cerca il Great Bear Spirit nel nord-ovest di ⟦Moonglade=Radaluna⟧ e scopri cosa ha da insegnarti sulla natura dell'orso. Al termine, torna da Dendrite Starblaze a ⟦Nighthaven=Nottequieta⟧, ⟦Moonglade=Radaluna⟧.", "Nella parte nord-occidentale di ⟦Moonglade=Radaluna⟧ si trova la dimora di un essere saggio e nobile che chiamiamo Great Bear Spirit. Per tutti i druidi è stato precettore e mentore, guidandoli verso la prima vera comprensione naturale dell'orso. Tutti i druidi, prima o poi, cercano la saggezza dello spirito, e tu non farai eccezione.\n\nVa' ora dal Great Bear Spirit e impara ciò che ti insegnerà. Quando sarà soddisfatto di te, torna da me qui a ⟦Nighthaven=Nottequieta⟧. Vedremo allora se hai davvero fatto tesoro delle lezioni che impartisce.", "Torna solo quando il Great Bear Spirit ti avrà rimandato da me. Il tuo addestramento non può proseguire senza la sua benedizione.", "Mentre ti avvicini, Dendrite traccia un altro gesto invisibile nell'aria sopra di sé. Un'altra aura di potere lo avvolge, e lui accenna un lievissimo sorriso.\n\n\"Sento in te una saggezza, giovane, che non c'era al nostro primo incontro. Mi guardi con forza e con intento consapevole, anche se questo intento non è ancora focalizzato. Ora imparerai a concentrare la tua forza e a fare tua la natura dell'orso nel tuo operato.\"", 0xf41bfb43, 0xbe60f9ec, 0xfdf1fe79, 0x63fce517, 0x63faa67b, "e...." },
  [5930] = { nil, "Cerca il Great Bear Spirit nel nord-ovest di ⟦Moonglade=Radaluna⟧ e scopri cosa ha da insegnarti sulla natura dell'orso. Al termine, torna da Dendrite Starblaze a ⟦Nighthaven=Nottequieta⟧, ⟦Moonglade=Radaluna⟧.", "Nella parte nord-occidentale di ⟦Moonglade=Radaluna⟧ si trova la dimora di un essere saggio e nobile che chiamiamo Great Bear Spirit. Per tutti i druidi è stato precettore e mentore, guidandoli verso la prima vera comprensione naturale dell'orso. Tutti i druidi, prima o poi, cercano la saggezza dello spirito, e tu non farai eccezione.\n\nVa' ora dal Great Bear Spirit e impara ciò che ti insegnerà. Quando sarà soddisfatto di te, torna da me qui a ⟦Nighthaven=Nottequieta⟧. Vedremo allora se hai davvero fatto tesoro delle lezioni che impartisce.", "Torna solo quando il Great Bear Spirit ti avrà rimandato da me. Il tuo addestramento non può proseguire senza la sua benedizione.", "Mentre ti avvicini, Dendrite traccia un altro gesto invisibile nell'aria sopra di sé. Un'altra aura di potere lo avvolge, e lui accenna un lievissimo sorriso.\n\n\"Sento in te una saggezza, giovane, che non c'era al nostro primo incontro. Mi guardi con forza e con intento consapevole, anche se questo intento non è ancora focalizzato. Ora imparerai a concentrare la tua forza e a fare tua la natura dell'orso nel tuo operato.\"", 0xf41bfb43, 0xbe60f9ec, 0xfdf1fe79, 0x63fce517, 0x63faa67b, "e...." },
  [5931] = { "Ritorno a Darnassus", "Torna a Darnassus e parla con Mathrengyl Bearwalker nell'⟦Cenarion Enclave=Enclave Cenariana⟧.", "È giunto il momento di separarci, giovane, poiché mettere in pratica le tue lezioni ti riporta da chi ti ha mandato da me. Mathrengyl Bearwalker cammina davvero in equilibrio con la natura, anche se dimora pericolosamente vicino al luogo dove l'equilibrio ha vacillato. Ascolta le sue istruzioni e presto completerai le tue prime lezioni nel ruolo di <protettore/protettrice> dell'equilibrio.\n\nVa' ora, giovane. Ci rivedremo.", nil, "Bentornat<o/a>, {name}. Sento che il tuo primo incontro con il Great Bear Spirit è stato come per tutti i druidi quando muovono i primi passi sulla via dell'Artiglio... un po' sconcertante, ma molto intenso. So che per me fu così.\n\nIl Great Bear Spirit fa parte di Azeroth da quando Azeroth esiste nei cieli. Abbiamo imparato ad affidarci alla sua saggezza e al suo potere per alimentare il nostro scopo. Ora è giunto il momento della tua prima prova di questo scopo. Ascolta bene...", 0xf19243a5, 0x17d4d4c5, 0x96c7c00f, nil, 0x0683c922, "...m." },
  [5932] = { "Ritorno a ⟦Thunder Bluff=Picco del Tuono⟧", "Torna a ⟦Thunder Bluff=Picco del Tuono⟧ e parla con Turak Runetotem sull'⟦Elder Rise=Altura degli Anziani⟧.", "È giunto il momento di separarci, giovane, poiché mettere in pratica le tue lezioni ti riporta da chi ti ha mandato da me. Anche se si pensa che i tauren siano giovani nelle vie di Cenarius, Turak Runetotem cammina in grande equilibrio al cospetto della natura. Ascolta le sue istruzioni e presto completerai le tue prime lezioni nel ruolo di <protettore/protettrice> dell'equilibrio.\n\nVa' ora, giovane. Ci rivedremo.", nil, "Bentornat<o/a>, {name}. Sento che il tuo primo incontro con il Great Bear Spirit è stato come per tutti i druidi quando muovono i primi passi sulla via dell'Artiglio... un po' sconcertante, ma molto intenso. So che per me fu così.\n\nIl Great Bear Spirit fa parte di Azeroth da quando Azeroth esiste nei cieli. Noi tauren ascoltiamo con attenzione questi spiriti, e tutti prosperiamo grazie al suo scopo. Ora è giunto il momento della tua prima prova di questo scopo. Ascolta bene...", 0x03abdae1, 0x7484d02e, 0x98aa7b3f, nil, 0x93bf0b6f, "...m." },
  [5941] = { "Ritorno da Chromie", "Porta il ⟦Bundle of Relics=Gruppo di Reliquie⟧ a Chromie, ad Andorhal.", "Hai raccolto molte reliquie della battaglia del ⟦Darrowshire=Borgo di Darrow⟧. Ogni volta che tornavi con altre reliquie, il mio cuore si struggeva per il mio villaggio... desiderava proteggerlo dal suo destino.\n\nSo che non può essere, ma Chromie, quella strana gnoma di Andorhal, mi dice che è possibile. Dice che puoi salvare il ⟦Darrowshire=Borgo di Darrow⟧!\n\nMi ha chiesto di riunire le reliquie e di fartele portare a lei. Ha detto che ti aspetta nella locanda in rovina di Andorhal.", "Sono stata in contatto con il tuo amico Carlin. Soffre molto per la rovina del suo villaggio, ma parla molto bene di te e sa che puoi rimettere le cose a posto.\n\nOh, ma sto divagando... {name}, hai le reliquie che ti ho chiesto?", "Ah sì, eccole. Insieme intrecciano un incantesimo potente, uno che risveglierà gli spiriti del ⟦Darrowshire=Borgo di Darrow⟧.\n\nCon quell'incantesimo, e un po' di fortuna, possiamo salvare Joseph Redpath!", 0x0c34da70, 0x164a0999, 0x123d1e2c, 0x8ae7ea24, 0x2f189558, "....." },
  [5942] = { "Tesori nascosti", "Porta la ⟦Joseph's Key=Chiave di Joseph⟧ al forziere di Joseph.", "Papà mi ha detto di darti questa chiave. Ha detto che apre un forziere sul retro, dietro la casa.\n\nVoleva anche che ti ringraziassi. Gli hai fatto un favore? Gli hai detto che hai trovato la mia bambola?\n\nBe', ecco la chiave. E grazie, {name}. Grazie! Sei <un/una> <signore/signora> molto gentile!", "Questo forziere è vecchio e coperto di sporcizia.", "La chiave entra nella serratura e il forziere si apre...", 0x557f556a, 0xcbae56d2, 0x9a480987, 0x30a3f649, 0x0a527a15, ".....", nil, nil, 0xe14cba19, nil, nil },
  [5943] = { "La ⟦Gizelton Caravan=Carovana di Lentecurva⟧", "Scorta la ⟦Gizelton Caravan=Carovana di Lentecurva⟧ attraverso la ⟦Mannoroc Coven=Congrega di Mannoroc⟧. Parla con Smeed all'⟦Scrabblescrew's Camp=Accampamento di Torcivite⟧ per ricevere la ricompensa.", "Sembri <un/una> {race} in gamba. Magari cerchi un modo per fare qualche soldo? Io e Cork abbiamo messo su questa carovana per fare un mucchio di soldi; non immaginavamo quanto fosse pericoloso fare affari!\n\nPiù avanti c'è la ⟦Mannoroc Coven=Congrega di Mannoroc⟧... di solito i demoni ci ignorano, ma stavolta qualcosa ha spaventato i kodo. Ti pagherò per proteggere la carovana oltre la ⟦Mannoroc Coven=Congrega di Mannoroc⟧. Quando l'avremo superata sani e salvi, potrai ritirare la ricompensa dal nostro socio d'affari Smeed, all'⟦Scrabblescrew's Camp=Accampamento di Torcivite⟧.", "Sai, se quella carovana sparisse sarei rovinato! Non sarai mica qui a portare cattive notizie sulla carovana, vero?\n\n<Smeed si asciuga la fronte.>\n\nGrazie alla dea dell'avidità!", "Non sono sicuro che pagare così tanto per proteggere la ⟦Gizelton Caravan=Carovana di Lentecurva⟧ sia un affare. Cork e Rigger guadagnano solo una moneta d'oro a settimana, ma finché continuano a pagarmi per i miei kodo, di come gestiscono i loro affari non mi importa un fico.", 0x263585ae, 0x8ba6f882, 0x4d9b60f3, 0xdd8ee6b2, 0xc76ce493, "....." },
  [5944] = { "Nei sogni", "Scorta Taelan Fordring fuori da ⟦Hearthglen=Valsalda⟧.", "Per tanto tempo sono stato una marionetta del Gran Crociato. Che motivo c'era di combattere contro ciò che la ⟦Scarlet Crusade=Crociata Scarlatta⟧ era diventata? Sono passati decenni, eppure i ricordi di mio padre, quei ricordi preziosi, sono ciò che mi ha tenuto in vita.\n\nFaccio dei sogni, stranier<o/a>. In questi sogni mio padre è con me. Sta fiero al mio fianco mentre vengo accolto nell'Ordine. Combattiamo legioni del Flagello, fianco a fianco. Portiamo onore all'⟦Alliance=Alleanza⟧, a Lordaeron.\n\nNon voglio più sognare.\n\nPortami da lui.", "<Tirion riacquista il controllo di sé.>", "La morte di mio figlio per mano di questi mostri non resterà senza conseguenze. Consolati sapendo che l'Ordine è rinato.\n\nOra prendo il mio posto come gran signore del nuovo Ordine della ⟦Silver Hand=Mano d'Argento⟧.\n\nQuesti oggetti del mio passato sono tutto ciò che posso offrirti per tutto ciò che hai fatto. Ti prego, accettali come simbolo della mia gratitudine: mi hanno servito tutti bene negli anni.\n\nChe possiamo rincontrarci, in tempi migliori, e ricordare i giorni ormai lontani... le battaglie combattute duramente... i sogni riscattati.", 0x743d7929, 0x53749095, 0x545379f7, 0x0d0306a9, 0x74ecb267, "....." },
  [5961] = { "Il campione della Regina delle Banshee", "Parla con Nathanos Blightcaller nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧. Si dice che si sia stabilito alla Cascina dei Marris.", "Mi fa molto piacere vedere i temprati dalla battaglia unirsi alla nostra causa. Ogni giorno che passa crescono il nostro numero e la nostra forza. Forse sei <pronto/pronta> a mettere alla prova il tuo valore, {class}?\n\nTra i primi dei miei campioni ci fu Nathanos, ora noto come il Blightcaller. Pochi, tra le nostre file, hanno più dedizione e vigore di lui.\n\nCercalo nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧. Risiede alla Cascina dei Marris e di tanto in tanto si aggira per le lande devastate, abbattendo tutta la feccia del Flagello e dell'⟦Alliance=Alleanza⟧ che incrocia il suo cammino.", nil, "Di certo la Dama Oscura non ti ritiene degn<o/a> di incontrare il suo campione. Sei qui per sfamare i miei segugi, vero? Non può esserci altro motivo per questa interruzione.", 0x406ba2fa, 0x06d74e67, 0x946f8091, nil, 0xad0a34c1, "...m." },
})
